window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20140415-6","meetingId":"h26-cm04","date":"2014年4月15日","dateIso":"2014-04-15","committee":"区民委員会","time":"午後１時００分～午後２時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２６年度 区民活動助成制度および協働事業提案制度の変更点","agenda":"の平成２６年度 区民活動助成制度および協働事業提案制度の変更点","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。変更点ということで２点お伺いいたしましたが、そもそも、例えば２番目の変更点としまして、平成２３年度から休止していたものを復活させるということですね。","respondent":"寺嶋協働・国際担当課長","answer":"休止の理由は、今ご案内したとおりですけれども、再開に当たりましては、これまでの委員会でもそういったご意見とかご質問もいただいておりまして、再度検討を加えたというのが一番大きなところです。","voiceIndex":9,"id":"exchange-001"},{"speaker":"石田（し）委員","kind":"提案","question":"社会貢献のきゅりあんでやられているイベント、僕もこの間、見させてもらいましたけれども、本当に多くの団体が活動していると改めて感じましたので、せっかく間口を広げていただくのであれば、ぜひ周知のほうをしっかりと行っていただいて、皆様がその制度をもう一度再認識というか、新しく知る人もいると思うので、そういったところの周知をしっかりと各地域団体にやっていただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"お願いします。１のほうの区民活動助成制度のほうですけれども、継続３年間という考え方を審査項目などの実施体制がスケジュールや実施可能の期間というものがあったのですけれども、それを３年間のスパンで見るという考えでよろしいのですか。","respondent":"寺嶋協働・国際担当課長","answer":"ただし、今までは１年こっきりだったということで、例えばですけれども、やってみて非常に好評だったものもありますし、あと、逆に審査会での意見などでは、単発のイベント的なものよりも、もっと地域に根ざした継続活動が望ましくて。","voiceIndex":12,"id":"exchange-003"},{"speaker":"吉田委員","kind":"確認","question":"審査によっては、経過を見て、それによって同じものでも１年でだめになる、もう１年出してもだめということになるということですけれども、それは、先ほど、新しい審査基準がないということに関してどうなのかと。ということは、新しい審査基準もあるのではないかと思いますけれども、それは確認をお願いします。","respondent":"寺嶋協働・国際担当課長","answer":"３年目の団体は特にこういう条件があるとか、２年目はこうだと、そういう意味での新しい審査基準は特に設けることではないということで、今までも単純に同一事業で１回申請があったものは。","voiceIndex":14,"id":"exchange-004"},{"speaker":"吉田委員","kind":"意見","question":"わかりました。やはり継続的ということはとてもいいことではないかと、発展できるのではないかと思いますし、よくもやっていけるのではないかと思うので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"制度の変更点はご説明があったのですけれども、変更した理由がよくわからなかったので改めて伺いたいと思いますけれども、区民活動助成制度では、要するに、これまで１回だったものをなぜ継続３回までにしたのか。先ほどの説明ですと、立ち上げ支援という趣旨もあるので、それにふさわしいということなのでしょうか、ここに変更した理由や検討の経過を改めて伺いたいと思います。","respondent":"寺嶋協働・国際担当課長","answer":"もう一つの理由としては、できるだけ多くの団体の活動を支援するという目的も含めて、機会をなるべく増やすということで１事業については１回と、こういうことが当初のスタンスだったのですけれども、実質的にこの数年間も予算を全て使い切っているという状況ではなく。","voiceIndex":17,"id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"１つだけ教えていただきたいのですが、１点目の区民活動助成制度の中で、先ほどから３回継続、１年ごとに申請し直してということですけれども、極端な話ですが、今まで何かしてずっと、例えば今年１０個、助成をいただいてやっていました。個数的に受けるラインというか、例えば極端に全部継続が１０個できました。新たなまた５個とか４個とかあったときに、限度というか、それはないのでしょうか。","respondent":"寺嶋協働・国際担当課長","answer":"あくまでも歳出予算ベースでの支出になりますので、予算規模としては３００万円、１団体の上限が５０万円なので、予算上は５０万円掛ける６団体ということで予算計上しておりますが、３００万円を超えない範囲であれば。","voiceIndex":19,"id":"exchange-007"}]},{"id":"topic-02","title":"の国際交流推進事業","agenda":"の国際交流推進事業","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"せっかくアメリカのポートランド市の市長夫妻が来られるということで、もちろん市長ですから、向こうのまちづくり等も熟知された方だと思いますので、２０２０年に向けた品川のまちづくりの部分に関しても、僕は、彼らが見るものを区にフィードバックしてもらえれば、非常に大きなまちづくりに寄与できるのではないかというふうに思いますので、その点、ぜひ国際友好協会とも連携をしていただいて。","respondent":"寺嶋協働・国際担当課長","answer":"１週間弱という限られた日程ではありますけれども、この中で直接お話しできる機会としては、先ほどもお話をしたウェルカムセレモニーというもの、それからパーティー、それから最後のさよならパーティー、こういう機会でかなり歓談する時間を用意しておりますので。","voiceIndex":27,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"２１日の区内見学ですけれども、どちらにいらっしゃるのか、区内を観光するということは、我が品川区を見ていただくという意味でとても重要だと思いますけれども、ご予定はどうなっているのか教えてください。","respondent":"寺嶋協働・国際担当課長","answer":"これ、時間とコースどりを考えると、歴史館、品川学園と行ったときに、どうしても時間の関係もありまして、そこから一番近い商店街は北品川周辺の商店街の辺りがそこからも歩いていける距離ということもありまして、ぜひそちらのほうにご案内するということで商店街を考えて。","voiceIndex":30,"id":"exchange-009"},{"speaker":"中塚委員","kind":"確認","question":"深めてきた友情をぜひ再確認するという国際交流も大事だと思いますけれども、今も触れておりますけれども、先方が望んでいる交流とかテーマというのがどういうものなのか伺いたいのと、それに応える我々がどういうふうにやっていくのか、そこを伺いたいと思います。","respondent":"寺嶋協働・国際担当課長","answer":"今、そういった形でのある程度年度で決まった交流事業もずっと進めてきておりまして、今のところ、そういった事業を継続していきましょうということでの約束が取り交わされているということなので、これにつきましては、継続していく予定ですけれども、今回。","voiceIndex":32,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"せっかく３０周年で来ていただくので、今後の姉妹都市との交流というのを考えるいいチャンスになると思いますので、そのとき区として、今後の姉妹都市との交流、もちろんホームステイをやったり、先ほど、スポーツを通じて交流があるというのはお伺いしているのですが、せっかくのチャンスですから、そういった今後、未来に向けて、どういった交流ができるのかというのも、区からも発信して、また。","respondent":"寺嶋協働・国際担当課長","answer":"正式にいわゆる議論をするという形での時間設定は特に設けてはいないですが、先ほど申し上げたように、懇談の中で意見交換をしていくということで、ほかの都市とも共通しておりますけれども、この提携当時と比べると、大分情報の交換は密になっておりまして。","voiceIndex":34,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺のところが、交流で行政のほうが入っていけるのか、その辺はどういうふうに考えたらいいのか。","respondent":"寺嶋協働・国際担当課長","answer":"今、委員のおっしゃるとおりですけれども、もともとは、成り立ちから言うと、品川国際友好協会のそもそもの設立趣旨から言っても、民間でできるものというか、草の根レベルの交流が望ましいということで。","voiceIndex":36,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"了解しました。ただ、スポーツ交流でこちらから行ったときも、たしか前回も行政ではなくて民間で、友の会が受け入れて対応してくれたというお話を聞いていましたし、逆に言うと、議会側としても接触がないというふうに判断していたのです。先方があることですから、どのようにできるかはわかりませんけれども、考えておいていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"}]},{"id":"topic-03","title":"続きまして、(3)の地域住民と外国人との交流促進","agenda":"続きまして、(3)の地域住民と外国人との交流促進","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"平仮名だったり漢字、漢字は人気ですよね。片仮名だったり、大切な日本文化ですから、英語や海外の言葉のコミュニケーションとしてはきっかけは大事ですけれども、やはりここは日本語というところもしっかり押し出していただいて、交流のきっかけづくりにしていただきたいというふうに思いますけれども、その点についても、どういうふうに今後取り組まれていくのか伺いたいです。","respondent":"寺嶋協働・国際担当課長","answer":"３点ございましたので、順にご説明します。","voiceIndex":43,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味では、今回は商店街ということですけれども、ぜひお買い物だけでなく、銭湯を楽しんでいただいたり、何なら駄菓子屋で少し子どもたちと買ってみたり、いろいろできるようなホスピタリティーを大事にできるように準備をしていただきたいと思いますけれども、今後の準備の過程や、まだオリンピックまでに何年かありますので、どういうふうな経過を踏んでいこうと思っているのか。","respondent":"寺嶋協働・国際担当課長","answer":"そういうことがないように、笑顔で迎えられるようにするというのもこの事業の趣旨でありますので、そこは含めてあわせて取り組んでいきたいと考えております。","voiceIndex":45,"id":"exchange-015"},{"speaker":"山元委員","kind":"質問・要望","question":"今回、この目的のところに、「商店街を対象とした実践型の英会話講座を実施する」ということで、今回、テレビを見ていると、実践型で外国のメンバーが商店街へ入って、即英語でしゃべるというか、その前に講座みたいなことを商店街の方たちに実際やってあげるのかどうかということをお聞きしたいということと、それから、今回、第１回をやったのですけれども、先ほど、課長もおっしゃっていましたけれども。","respondent":"寺嶋協働・国際担当課長","answer":"そういう意味では、もとより結果的には語学の学習という位置づけには若干なりがちなので、強制してやれるものでもないし、嫌々やってできるものでもないですけれども、ぜひこういう取り組みがあるのでやっていただきたいという奨励等々ご案内して。","voiceIndex":47,"id":"exchange-016"},{"speaker":"山元委員","kind":"意見","question":"そうすると、イメージとしては、外国の方がそこへ降りて、会場まで歩いていくのだろうということを想像するのですが、降りそうなところの商店街の人たちをぜひバックアップしてほしいということと、それからやはり高齢化しているので、外国人というと拒否反応をしてしまうという部分があるので、その辺、上手に持っていき方というか、外国人は怖くないんだみたいな、少し言い方は変ですけれども、もっと簡単。","respondent":"寺嶋協働・国際担当課長","answer":"言葉がどうしてもという部分も含めて、一番導入しやすくなるような仕組みは、今回、第１回目の検証も踏まえて検討していきたいと考えております。","voiceIndex":49,"id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問","question":"ただ、八百屋に外国人の方が、例えば八百屋でキュウリを割り箸に刺して、その場で食べられるようなものとかを販売しているところだったら寄られるのかというイメージがありますけれども、その点、どういう選定というかあれで、こういった、八百屋も手を挙げてくれたのかとは思いますけれども、そういった部分に関しては、手を挙げてもらったらとりあえずやってもらうというのが。","respondent":"寺嶋協働・国際担当課長","answer":"普通に果物を買って持っていて、お腹がすいたらかじるという文化がある国も多々あると思うのです。ただ、余談ですが、八百屋のご主人がおっしゃっていたのは、バナナを房でなくて１本だけ買いたいとかと言われたことがあって困ったみたいな話がありました。","voiceIndex":52,"id":"exchange-018"}]},{"id":"topic-04","title":"のプレミアム付区内共通商品券発行事業への助成","agenda":"のプレミアム付区内共通商品券発行事業への助成","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"その対策等はどういうふうに、ここにありますけれども、春と秋の、例えば、もうすぐ切れますよみたいな、そういうものはあるのか、やっていたら、また知らなくてごめんなさい。チラシの裏面にアンケートがありますけれども、このアンケートはどのようなことに使うのか、何かアンケートを使って、これからどういうふうに改善するのか、そういうことを考えている、そのことを教えてください。","respondent":"米田商業・観光課長","answer":"使用率は、ここのところずっと変わっておりませんが、おおむね９９％台半ばということで推移しています。多少の上り下がりはありますけれども、おおむね２００枚に１枚が使い忘れというようなことでご理解いただければと思います。","voiceIndex":59,"id":"exchange-019"},{"speaker":"吉田委員","kind":"意見","question":"９９％使い切っていると、すばらしいというのがわかりました。このアンケートに関して、今おっしゃったように、集計が出たら、それによってどうこうというのはないのですけれども、やはり皆様の意見なので、十分それを考慮という言い方はおかしいですけれども、それに左右されるという意味ではなくて、傾向を見ていただくようにご努力をお願いしたいと思います。それを、アンケートに関して。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"済みません、そういうことに関していかがでしょうか。","respondent":"米田商業・観光課長","answer":"こちら、お買い求めになられる方のという限定はつきますが、そういう方のご意向ということでは、貴重な資料として商店街連合会のほうからの集計を踏まえて、こちらのほうもいろいろご意見等賜れればというふうに思ってあります。","voiceIndex":63,"id":"exchange-021"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。）」と書いてありますけれども、１８日にスタートして、その日に完売というのはないのかもしれないですけれども、「売り切れ次第終了」と書いてあって、１８日に完売した場合に１９日にも販売をするというのは、１８日に完売してしまったら、１９日に販売するものが本来存在しないのに、ここの記載に書かれているというのは、これはどういった意味なのか、そこだけ少し教えてください。","respondent":"米田商業・観光課長","answer":"そういった意味では、１８日にもし万が一、金融機関、郵便局等で売り切れた場合であっても、商店街連合会のほうでは１９日分ということで、土曜日、日曜日でしかお買い求めになれないような方もいらっしゃると思いますので。","voiceIndex":65,"id":"exchange-022"},{"speaker":"山元委員","kind":"質問・要望","question":"一つは、アンケートには１冊から４冊まで購入した冊数をチェックする欄が書いてありますけれども、また年代別にもなっているのですが、この数字的なものというのは、今までもしわかっていれば教えていただきたいということと、それから、全部で大体何人ぐらいの方が買っていらっしゃるというのですか、その人数がわかれば教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"年代ですけれども、１０代、２０代はさすがにそんなに多くありませんが、３０代からはおおむねバランスよくというようなことでお考えいただければと思いますが、その中でも６０代、７０代が若干その年代の中ではやはり厚めかというようなことが購買の実績状況です。","voiceIndex":68,"id":"exchange-023"},{"speaker":"山元委員","kind":"質問・要望","question":"思わずやはり４冊買ったら４,０００円つくという計算をしてしまうのですが、そういうことをいろいろ考えて、やはり年代的に後半になればなるほどお買い求めになる方が多いのかと思いますが、今回は４口が最大限ということで、将来的にもう少し、先ほど、１万人の方が購入できるとおっしゃっていましたけれども、もう少し広げようとかというお考え、今回まだ数を減らしたばかりなのであれですが、その辺。","respondent":"米田商業・観光課長","answer":"そういった意味では、やはり口数を減らすというのを単純にすぐにやるよりは、推移を見極めてからというようなところだろうと考えていますので、今回、口数を変えましたので、その推移をよく見極めて、なおかつ、お買い求めになりたいというお声も多々聞こえますので。","voiceIndex":70,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"今までも何度か説明があったかもしれませんけれども、商品券はおつりはどういうふうに取り扱っているのか、それぞれの取扱店にどんなふうに説明をしているのか伺いたいのと、それと、「しながわ水族館でもご利用できます」とチラシにありますけれども、区の施設で利用ができるのはしながわ水族館ということなのか、商品券発行の目的にもかかわってくると思いますけれども、逆に伺うと。","respondent":"米田商業・観光課長","answer":"おつりのほうです。基本的におつりのないように使っていただくというのを原則にしておりますので、５００円以上の買い物で使っていただくというのが原則です。","voiceIndex":73,"id":"exchange-025"},{"speaker":"藤原委員","kind":"意見","question":"勘違いかもしれないのですけれども、今までプレミアム付区内共通商品券発行事業を委員会に報告されるときは、春は春、暮れは暮れみたいな形で報告があって数字的なものも出てきたのではないかと思いますけれども、こうやって今回、助成額は春・秋で一発で出てきているというのは、もしくは今までもそうでしたというのだったらいいのですけれども、何か春と秋は分かれて出てきたと思うのですが。","respondent":"米田商業・観光課長","answer":"そういった意味では、今回、予算計上しておりますのが６億６,０００万円で、うち春が消費税率の落ち込みのために４億４,０００万円、とにかく区内のいわゆる商店や商店街の景気浮揚のために、いわゆる消費税率の改定に伴う影響を最小限にするために。","voiceIndex":75,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"緊急経済対策の一環ですので、毎回そういう形でやられたわけですけれども、まさに緊急経済対策であるわけですから、年間の金額がありきで、そこからまず４億円という形でやって、残りが２億円で、だから秋２億円というのは、緊急経済対策という形ではどうしても違うのではないかという思いがあるのが１点と、それと、売れる期間で言うのであるならば、春よりも秋のほうが早いですよね。","respondent":"米田商業・観光課長","answer":"それの売れ行き状況だったり、あるいは使用された結果、区内の景気がどのように変わっているか、こういうようなお声も十分踏まえつつ、今後の対応については考えてまいりたいというようなことでご理解いただければと思います。","voiceIndex":77,"id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"逆に緊急経済対策がなくなってしまうかもしれませんけれども、だけど、上がるという可能性も含まれるかもしれないと、それはそのときの経済状況によっていろいろまた考えていきますよということで、これで質問をやめますので、そこだけ改めて確認なので、答弁いただけますか。","respondent":"米田商業・観光課長","answer":"十分に今後の区内経済の状況、それから消費者の方々の消費動向、これを十分に見極めて、現在の予算額の中ではこういうことだということでご理解いただきたいと思いますが、予算特別委員会を含めて、多様なご要請があったことも十分勘案しながら。","voiceIndex":79,"id":"exchange-028"}]},{"id":"topic-05","title":"の就業支援事業","agenda":"の就業支援事業","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"広報についてお伺いしたいと思います。だれをターゲットにするかというのを行政としてもそろそろ考える必要があると思うのです。そういったところも、せっかく委託をされているのですから、ぜひ活用していただいて、若者が見て、「ああ、いいな」と、こういうことを区がやってくれていると、行ってみようと思ってもらえるようなものにしていただきたいというふうに思います。","respondent":"山崎ものづくり・経営支援課長","answer":"より効果的なＰＲでありますとか、目に触れる機会を創出するとか、工夫してまいりたいというふうに思ってあります。それと、付随的に親御さんの方への媒体も含めて、いろいろな角度から事業の特性を踏まえて周知、ＰＲに努めてまいりたいというふうに考えてあります。","voiceIndex":85,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"それとも、時給１,１００円で１６万円になるように仕組みとして組んであるということなのか、そこを伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"説明が不足しておりまして、委員のご質問の件について、昨年と変わっておりません。具体的には、時間単価が１,１００円で、１日７.５時間ということになりまして、掛けますと８,２５０円ということになります。","voiceIndex":88,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"その位置づけを伺いたいと思います。ぜひここに広げた意味合いを伺いたいと思います。実家で暮らしている場合は区内かもしれませんけれども、ひとり暮らしを始めると、いろいろ物件を探す中で必ずしも区内というわけにもなりませんので、そういう意味では、この平成２４年３月以降の卒業というのは、実態に即して広げていくということも検討が必要ではないかと思いますけれども、その点はいかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"私ども、事業を実施する区としましては、やはり区民の皆様の就業を力強く支援するという立ち位置でございまして、そこの部分はしっかりいわゆる優先といいますか、そうした考えのもとですけれども、今回、大学・専門学校を卒業したというところで。","voiceIndex":90,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"今ではバイトを辞めたくても辞めさせてもくれないとか、こういう無理な働かせ方をして体を壊す方もいるわけですけれども、こういう相談の中で、例えば『ポケット労働法』を紹介するだとか、大崎労政を紹介するだとか、こういう解決事例やこういう力になる労働組合があるだとか、そういうところの連携や、具体的には『ポケット労働法』の配布なども行っていらっしゃるのか、その点を伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"委員ご指摘のような企業の不適切な雇用条件でありますとか、そういうようなことの相談が来ましたら、そうしたことの相談窓口の国の機関などにしっかり状況を踏まえてつなぐような、そういったことでこの窓口も機能してまいりたいというふうに考えてあります。","voiceIndex":92,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、具体的に『ポケット労働法』を配布しているのかと伺ったのですけれども、この点については、どうなのか、中小企業センター内で、たしかこれは置いてあった気がしなくもなかったのですけれども、そこだけ現状をご説明いただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"もろもろ雇用関係の適正な執行の機関としましては、労働基準監督署とも協議会をつくっていろいろやりとりしております。窓口なり冊子を置かせていただく、ＰＲブースのほうにそうしたものも置かせていただいております。","voiceIndex":94,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"わかもの就業相談のコーナーとの関係ですけれども、１階の品川区就業センター、ハローワークとか、こことのつながりは、どういうふうに仕切ったらいいのかということが理解があまりいかなかったので。","respondent":"山崎ものづくり・経営支援課長","answer":"１階のハローワークの窓口にも、本日説明したような就職にかかわる相談コーナーがあるよというようなことを周知しておりまして、通常、若者に限らず、職を探しにハローワークに来られて、例えば端末で検索をして求人票を出してというようなことが。","voiceIndex":96,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"意見","question":"うまくつないでもらいたいのだけれども、要するに、就業センターでやるべきところを２階に持っていかれてしまうのではないかという、少し悪くとれば、今言ったように説明、１階では対処し切れないから２階で指導してくださいよというふうな部分もある。それも必要なのだろうけれども、どっちかというと、ハローワークの仕事との絡みというのは、そこら辺、もう一度。","respondent":"山崎ものづくり・経営支援課長","answer":"私どもの２階のわかもの就業相談につきましては、区民の方を対象というようなところもありますので、そうしたつなぎをさせていただきながら、ご自身で何の仕事をどういうふうに探していいのかわからないというようなレベルの方を少し誘導していきながら就業に結びつけていく。","voiceIndex":98,"id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"理解しました。その辺はうまく就業に結びつけていただきたい、よろしくお願いします。ただ、１点気になったのは、品川区民に対して、１階に来る方は区民ではない方も来る。そこが、これを見て、区民以外の方が来たときに、どう断り切れるのかというのが、その辺の懸念があると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"わかもの就業相談の中に、今度、新しく女性向け就業相談の実施ということで、新しくできたということですけれども、子育てしている人にとっては大変いいことだと思いますけれども、これ、周知というか、４月１日からスタートしたということですが、この周知の仕方というのは、どのようになさっていたのかということと、それから、こちらにも書いてあるように、やはり子育てをしている。","respondent":"山崎ものづくり・経営支援課長","answer":"女性向け就業相談も実施ということで、４月１日より経営支援の窓口で若者相談窓口を新設しまして、この女性の就業相談はそこの場所と同様のブースで行いますので、わかもの就業相談と一緒にＰＲをさせていただいて、チラシ、それから本日のシートのほうにも。","voiceIndex":101,"id":"exchange-037"},{"speaker":"山元委員","kind":"質問","question":"そういう意味では、女性にとってすごく希望が持てるという感じだと思いますけれども、とりあえず、今、１週間のうち金曜日の午前中だけ、２人までが申し込みできるということですけれども、ゆくゆくは申込者が多ければ広げていこうというようなお考えでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"就業のいろいろな支援の方向性としまして、女性の就業支援というのも大きな視点の一つというふうに区のほうでも捉えていまして、そういう意味では、ここでの相談コーナーの状況ですとか、そういったものを見極めて、今後のここの分野での施策の組立てですとか。","voiceIndex":103,"id":"exchange-038"}]},{"id":"topic-06","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"なぜかというと、議案審査など委員長報告は正副一任を委員会で確認した上でつくっているわけですけれども、やはり所管事務調査の活動報告ですから、その性格上、このように議論をして確認をすることがふさわしいと思いますので、その点はということですけれども、その上で委員長に伺いたいのですけれども、進め方がそうだということで、その上で伺いたいのは、全て残したと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-039"},{"speaker":"中塚委員","kind":"意見","question":"「官民相互で整備を進める」と、その後ろに、「なお、進めるべきではないとの意見もあった」というように追記をする。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、委員長がおっしゃったとおり、そういうことを言ったら一つ一つ、これは反対だ、これは反対だと、意見のまとめになってしまうので、あくまで委員長が言ったように、そういう発言自体は本来おかしな発言だということを委員としても意識していただきたいと、先ほど言われたようなことの前提は違うということをかなり意識してほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-041"},{"speaker":"中塚委員","kind":"意見","question":"なので、要するに、「なお、進めるべきではないという意見もあった」という両論併記で、そういう意見もあったという紹介にしていただけたらいいというふうに思ったのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-042"},{"speaker":"中塚委員","kind":"意見","question":"それだけに最近のスポーツの場での人種差別的な発言や横断幕というのはとんでもない話だし、また、東北の復興を棚上げにしてオリンピックをてこに箱もの事業や、要するに、都市の基盤の整備だとか、そういうことに集中するでは、東北を置き去りにしていいのかという思いもありますので、やはり環境に配慮したオリンピック、また、人権を守るオリンピックムーブメント。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2692#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":40830,"voices":130}},{"id":"h26-20140415-7","meetingId":"h26-cm04","date":"2014年4月15日","dateIso":"2014-04-15","committee":"厚生委員会","time":"午後１時００分～午後２時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)の「組織改正に伴う所管事項の変更について」","agenda":"はじめに、(1)の「組織改正に伴う所管事項の変更について」","exchanges":[{"speaker":"井上委員","kind":"質問","question":"点線のところで、介護保険担当と高齢者支援第一から第三の一部は変更ということだったのですが、介護保険に関しては、どういった部分が移行されているのか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"介護保険担当のほうからは、成年後見申立てに関することと、やさしいまちづくり推進事業の２点について動いているところです。","voiceIndex":25,"id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こういった組織改正は、今回、品川区独自でやったことなのか、全国的にとか、２３区的に進んでいるものなのか。こうしたことで、サービス、事業への利点は、どういうふうに考えているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"区民の方への丁寧な説明が必要であるということから、重点的にやるということ。それから、地域福祉に関しても共助という考え方は、丁寧に支援していかないとなかなか進まないということから、新しい課の体制をつくったところです。","voiceIndex":27,"id":"exchange-002"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"各区それぞれの考えで進めているということで、私も昨日、特別養護老人ホームのことでいろいろお聞かせいただいたんですけれども、福祉計画課ができたので、そちらのほうで一緒に進めていくと聞いたんですけれども、区民が窓口に行ったときに、あちらこちらになるということはない状況なのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"広報の仕方ですけれども、広報「しながわ」に、組織改正の記事は載せてあります。それから、在宅介護支援センターにも組織改正のこともご連絡をしておりますので、スムーズな移行ができるように努めていきたいと考えております。","voiceIndex":29,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"どういったことを計画して、それをどういうふうに区民に知らせていくのか、もう少し細かく教えてください。","respondent":"永尾高齢者福祉課長","answer":"施設の整備、何をどういうふうに整備するかという内容になりますと、介護保険事業計画と密接に係わってくる内容ですので、こちらにつきましては、高齢者福祉課が担当になるのですけれども、実際に整備をする段階になって、工事事業者とか、地元の住民に対する説明とか。","voiceIndex":31,"id":"exchange-004"}]},{"id":"topic-02","title":"の「第二庁舎売店の障害者雇用の場としての活用について」","agenda":"の「第二庁舎売店の障害者雇用の場としての活用について」","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"ミニコンビニと書いてあるんですが、それから、納品を行うベンダーと社会福祉協議会が提携しているんですけれども、どんなイメージか、もうちょっと教えていただけますか。","respondent":"中山障害者福祉課長","answer":"ミニコンビニのイメージになりますが、食品を中心に、特にお弁当とか、パンとか、菓子類、それから飲み物を中心としまして、そのほか雑貨としては、例えばティッシュペーパー、ストッキング、こういったものをそろえる予定です。","voiceIndex":38,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"これはイメージなんですけれども、いろいろなコンビニが民間にありますよね。今あれかもしれませんけれども、そういうところで売っている商品と同じようなものがここに入ってくるという考えなのでしょうか。前のときは、コンビニで売っているというよりも、ちょっと手作り感があったんですけれども、そういうのではなく、コンビニのものがそこに入ってくるというイメージなのか。","respondent":"中山障害者福祉課長","answer":"委員ご指摘のとおり、コンビニに置いてある、例えばおむすびであったりとか、お弁当であったり、そういうもののほかに、区内の授産施設である、例えばプチレーブのパンを販売したりということで、品ぞろえとしては。","voiceIndex":40,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"社会福祉協議会が運営事業者ということで、障害者の雇用の場ということなんですけれども、そこの雇用体系みたいなものは、社会福祉協議会が考えるのか。いろいろな方たちがいらっしゃる、知的障害者もいる身体障害者もいるというところで、どういうふうな人選をしていくのか、そういったところの具体的な運営方法をどう考えているのか、教えてください。","respondent":"中山障害者福祉課長","answer":"現在は、ふれあい作業所は法外事業ということでやっているのですけれども、平成２７年度からは、就労継続Ｂ型ということで、こちらの場所を活用しまして、指導員とともに作業生がここで売店の売り子であったり、納品であったり、陳列であったりとか。","voiceIndex":42,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"ふれあい作業所が社会福祉協議会が運営しているということなので、今されている公園清掃とか、そういった事業体系と同じような一つのセクションとしてここを利用していくということで考えているのでしょうか。","respondent":"中山障害者福祉課長","answer":"ふれあい作業所のメインである公園清掃だけではなく、自転車の補修であったり、あるいは、手工芸品みたないものを制作しています。そういったメニューの一つとして新たに売店の店員という仕事が加わるというようなことになります。","voiceIndex":44,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"そういった場合に、ここがそういう形で活用されればいいと、一つの場になるのかなと思っていたんです。そういったところも検討したうえでの決定だとは思いますけれども、そういう部分について、ここを活用しようという、そういう協議というのが、どこが関係所管と言われるところなのかということと、もう一つ、訓練の場というような検討は、どういうふうにされたうえでの判断だったのか、教えてください。","respondent":"中山障害者福祉課長","answer":"ですので、法外事業であったとしても、あるいは、平成２７年以降の就労継続Ｂ型になったとしても、そこで作業をしていくことで、積み上げが自信につながり、いずれは一般企業への就職にもつながっていくことにはなると思います。","voiceIndex":46,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"そこのスタッフの人数とか、サポートする人とＢ型に就労する方というのは、どういう規模なのでしょうか。それからスペースは、今と同じなのか。もう少し広くしないといろいろな部分で、ミニコンビニといっても難しいのかなと思うんですけれども、スペース的な拡大があるのか。それから、スタッフ態勢はどんなふうに考えていらっしゃるのでしょうか。","respondent":"中山障害者福祉課長","answer":"やはりお昼前後が一番売店の売り上げを伸ばしたいところでありますので、そういうときには、場合によっては職員が２名、作業生が３名から４名態勢もあるでしょうし、開店準備であるとか。","voiceIndex":48,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"今、火曜日にリボンの前で、そういった授産品を販売していますけれども、そこは今までどおりなのか、何か協議で変わったことがあるのか、そこはどうなっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"例えばよその法人でつくっている花ふきんであるとか、ゆかいな雑巾であるとか、ああいったものは置けると思うのですけれども、火曜日にやっているふれあい市は自転車などをやっておりますので、自転車の販売については売店では難しいので。","voiceIndex":50,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"今回、ゴールデンウイーク明けに、今の売店のところに、そのような形で常設といいましょうか、常時区内の各法人でつくられた授産品が売られるということで、質問ではなくて、要望させていただきたいのです。区の庁舎の中に売店が２階にありますよと、ただ表示板に売店と書いてあるのではなくて、そのようなものができますというようなことを、広報なりで告知をいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"意見","question":"我々が行政視察で行った福岡の１０円クッキーは、市長さんがかなりプロモーションをされていて、行政視察に来た方は、みんなここに案内されるというような取り組みもありましたし、また豊島区なんかに行くと、区庁舎に入ってすぐのところにパンを売っているところがあって、そこは日替わりでいろいろな福祉系の事業者の方たちがきている。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"障害者の雇用の場ということで、私たちも求めてきたことですので、ほんとうに歓迎するところです。就労継続Ｂ型ということで、訓練の場にもなっていくということですが、納品業者がベンダーというところで、これはどういった事業者を検討しているのか、お聞かせください。","respondent":"中山障害者福祉課長","answer":"ローソンとか、例えばセブンイレブンのような大手もあるのですけれども、ああいった企業は、フランチャイズの契約でかなり高額な金額がかかるということもありますので、障害者の福祉の就労として、あるいは、商品の品ぞろえをやりつつ。","voiceIndex":54,"id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、品ぞろえというか、こういう品物がなくなったとか、こういう品物があったほうがいいとか、そういうことを検討するのは、働いている方になってくるということですか。","respondent":"中山障害者福祉課長","answer":"実際、ベンダーの仕事として、１日に２回の納品というのがあります。店舗の中でなくなっている商品、要するによく売れる商品については、追加ですぐに入るような仕組みになります。","voiceIndex":56,"id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"母子寡婦福祉連合会がやられていたときも、売上げがなかなかうまくいかないということで、撤退になっていったということですけれども、今回、売上げを上げるためにいろいろ工夫されるということが、何となく読めるんですけれども、ここも売上げが伸びなければ、結局撤退ということになってしまうのでしょうか。","respondent":"中山障害者福祉課長","answer":"作業生の工賃については、こちらの売上げの利益がそのままお給料になります。生活指導員といいますか、指導をする職員の経費は、法内のサービス費のほうで給付されますので、一般的に通常の方が運営するよりも、仕組みとしては継続しやすい仕組みになっているかと考えています。","voiceIndex":58,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今、ほかの委員からも出ましたけれども、福祉施設でつくられた商品を庁舎内で販売していくというのを、厚生委員会のみんなで望んできたことなんですけれども、それを継続させるのと同時に、雇用の場にもなっていくというところでは、ほんとうに長く継続させていただきたいと思いますので、やはり区からの支援というのも強めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-017"}]},{"id":"topic-03","title":"の「品川区立心身障害者福祉会館の定員変更について」","agenda":"の「品川区立心身障害者福祉会館の定員変更について」","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今まで、実際にここで自立訓練で機能と生活の訓練をされていた方たちが、６名、６名になってしまうということは、今までの方たちはどういうふうに変更になるのか。利用者側にしてみると、どういう変化になるのか、そこをお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"すみません、私の説明がちょっと不十分でございました。今まで生活訓練、機能訓練を受けていらした方たちの訓練というのは有期限サービスになっております。","voiceIndex":66,"id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"今まで自立訓練をされていた方たちは、生活介護という枠の中なんだけれども、訓練という人数の中にいたということなのか。今まで訓練をされていた方たちは、これからの一定期間で家庭に戻ったり、そういうふうに移行されていたのか。それとも、定期ではない方たちが多かったということになるんですか。","respondent":"中山障害者福祉課長","answer":"今回、自立訓練の機能訓練と生活訓練を新しく６名ずつに切りかえたところにつきましては、ほんとうに有期限で、短時間のリハビリであったり、ＯＴによる生活訓練であったりということをやって、それをやることで、在宅での生活。","voiceIndex":68,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"スペースは変わらないところに１２名の増員ということなんですけれども、その部分で、需要に供給が合うのか。これからも増えていく見込みだろうというところで、きつきつというか、場所的にはすごく厳しいスペースで事業が行われるのかと思いますけれども、その辺についての見通しは、どんな感じでしょうか。","respondent":"中山障害者福祉課長","answer":"新たに６名ずつ設けます機能訓練の生活訓練につきましては、４階のスペースの、例えばパソコン室ですとか、訓練室がありますので、そちらを活用することで、そこの整備をすることで、逆に有機的な訓練を行っていきたいと考えているところです。","voiceIndex":70,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"もう一つ最後なんですけれども、ちょっと広い部屋で総会とかいろいろな大人数の会合ができたときに、今回、４階に部屋を分けたことによって、利用がなかなか難しくなったと、団体の方からの声がありましたけれども、それをまた今回、少し動かすことで、そういった利用者側の団体の方たちの限られた、あそこはそういう方たちが使える施設としてすごく重宝されていたところが。","respondent":"中山障害者福祉課長","answer":"大幅なレイアウト変更とかは特にする予定はありません。今までの部屋のスペースを、逆に機能訓練の場ですとか、そういった訓練の道具をそろえることで活用してまいります。訓練室２のところが、恐らく団体の方がお使いになられていたお部屋かと思います。","voiceIndex":72,"id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"新しく自立訓練の機能訓練と生活訓練の６名、６名の１２名をプラスしていくところで、それで生活介護が５０名になっていくんですけれども、４月１日から変更されて、これはもう全て定員はいっぱいになっているのか。それから、増えたことで支援員というか、スタッフはさらに増員されているのか、お伺いします。","respondent":"中山障害者福祉課長","answer":"ただ、これでいいかといいますと、生活介護自体は、５人に対して１人のスタッフというようなサービスになりますが、それですと実質的にはかなり介護が難しい状況になっておりますので、心身障害者福祉会館のほうでは、現在でも、特に男性介護のスタッフを、今募集をしています。","voiceIndex":74,"id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"保護者からも、ほんとうに詰め込まれているようだという声なんかも伺うこともあるので、やっぱり増やしていくことを検討していかないと、ちょっと無理な状況になっていくのではないかという心配はありますけれども、その辺を、区としてはどうお考えでしょうか。","respondent":"中山障害者福祉課長","answer":"ただやはり、また今後も特別支援学校の卒業生の方とかは、これからも出てきますので、そこにつきましては、卒業生の今後の見込みといったところをしっかりと把握する中で、きちんとした対応がとれるよう考えてまいりたいと考えています。","voiceIndex":76,"id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"卒業生が出てくる中で、不安だという声が、保護者の皆さんからあって、むつみ園なんかも、この間、開所式に出させていただきましたけれども、設立されたと聞いています。ですからやはり、品川区はそこの声にしっかりこたえていく、支援をしていく体制をしっかりとる計画をつくっていくということが大切だと思いますので、増設していくことを望みたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-024"}]},{"id":"topic-04","title":"の「障害児日中一時支援事業「にじのひろば」運営事業者の変更について」","agenda":"の「障害児日中一時支援事業「にじのひろば」運営事業者の変更について」","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"今年度、にじのひろば、４００万円の増額をしていただいて、安全性とか、そういったところを強く要望してきて、そうなったところで、ＮＰＯ法人のほうでは困難だということで、ここについてはとても残念な思いとともに、もう少し早く対応していただきたかったというのは、区の体制として考えていただきたいと、これは一言ほんとうにお伝えしたいと思いました。","respondent":"中山障害者福祉課長","answer":"これを児童福祉法上の放課後等デイサービスという新しいメニューができたことにより、そちらに移行するか、あるいは、移行せずに区が委託事業として引き続き運営したほうがいいのか、ここについては、またこの１年間考えていければと思っているところです。","voiceIndex":84,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"今まではＮＰＯ法人の独自事業ということも少しあって、区外の方でも、ＮＰＯが独自で、という形で、そこはほんとうに区内、区外ではなく、求めている人たちにというＮＰＯの方針があったかと思うのですけれども、今回、受託法人が品川区社会福祉協議会ということになりますと、区外でどうしても利用させてほしいという方たちが排除されてしまうのか、今までどおりそこは担保されるのか。","respondent":"中山障害者福祉課長","answer":"実際に、今回、この制度を変えるにあたりまして、区外のご利用の方がどれくらいいらっしゃるかということも調査させていただきましたが、登録はしてあっても、実際にはご利用になられる方はほんとうに１名、２名で、しかもすごく少ない回数でしたので。","voiceIndex":86,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"なかなか大変な方たちをケアされていた部分で、定員が多い中で頑張ってこられたのですけれども、今回、社会福祉協議会になると、ＮＰＯとかそういったところとは違って、変更はなかなか難しいかもしれないのですが、区としては、定員の見直しとか、状況の変化とか、そういったところは柔軟に対応するのか、それとも法人にお任せしていくのか、お考えをお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"ただ今後、区が申請書を必ず受け取って、利用決定していく中で、どれくらいのサービスの必要性があるのかというのは見ていけることになりますので、定員を変更するというのは、むしろ安全性の担保のところで難しいかなというところもありますが、場所がここだけで足りるのか。","voiceIndex":88,"id":"exchange-027"},{"speaker":"たけうち委員","kind":"質問","question":"法人より、受託継続が難しいとの報告を受けたとあるんですけれども、この辺の事情というか、法人の代表の方がお亡くなりになったというのは伺っているんですが、そういうことなのか、それとも制度上何かあったのか、その辺をもう少し教えてください。","respondent":"中山障害者福祉課長","answer":"ただなお、実際にケアを受ける子どもにとっては、ケアするスタッフが変わるのが一番きびしいかと思いましたので、どりいみんぐの、にじのひろばを運営していただいていた職員につきましては、引き続き社会福祉協議会の職員ということで、今回、変更をしています。","voiceIndex":90,"id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"利用される方にとって、職員の変更はないというところでは安心なのかと思いますけれども、利用方法が変更されているというところで、使えていたところが使えなくなるとか、そういう仕組みになったのか、そういった人も生まれてくるのかを、ちょっと伺います。","respondent":"中山障害者福祉課長","answer":"どういったご利用をされていたかというのは、この間、ＮＰＯのほうでも個人面談を行っております。そうした中で、区のほうに新たにまた申請書を出していただき、利用決定をしていきますので、特段の問題はないのではないかと考えているところです。","voiceIndex":92,"id":"exchange-029"},{"speaker":"渡部委員","kind":"質問・要望","question":"すみません、ちょっと確認を二つほどさせていただきたい。今、ほかの委員からの質問で、聞こうと思っていたことは大体わかったのですが、わかりやすく言うと、利用者側からしてみれば、申請の方法が変わっただけで、職員もそのままということですから、何も変わってないのかという確認がまず一つ。","respondent":"中山障害者福祉課長","answer":"現場では、そういうときには、職員の数を手厚くして対応をしてきたところなのですが、例えば、２５人定員としていたときに、まだあいているではないか、まだ入れるのではないかといった保護者のお声もありますので、一定そこで定員の縛りをかけさせていただいたところです。","voiceIndex":96,"id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"定員に関しては、運営する側のスタッフの関係というところで、この人数になったというのが本音のところでしょうか。","respondent":"中山障害者福祉課長","answer":"スタッフのほうは配置をすれば何とかなる現状はあるのですが、むしろ実際にあのスペースに２５人入れるかといったときに、重度の方がいらっしゃる、あるいは、自閉の強い方で個別支援が必要な方がいらっしゃるという中では、１５人という数字が。","voiceIndex":98,"id":"exchange-031"}]},{"id":"topic-05","title":"の「品川区新型インフルエンザ等対策行動計画の策定について」","agenda":"の「品川区新型インフルエンザ等対策行動計画の策定について」","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"２点、ちょっとお伺いします。それが一つ。それから二つ目は、そのインフルエンザの場合、ちょっと名前はど忘れしてしまったんですけれども、富山から新型インフルエンザの薬が認可されたのだけれども、これは新型インフルエンザに限って使うようにということで、今、認可されましたけれども、それはこの計画に何らかの形で関係しているのでしょうか。","respondent":"佐藤品川区保健所保健予防課長","answer":"中国のインフルエンザにつきましては、Ｈ５Ｎ７のことと認識しております。昨年４月に大変に報道されまして、Ｈ５Ｎ７型の鳥インフルエンザが人に感染を起こしているということで、国も、東京都も、品川区も含めまして、一時緊張が走ったところです。","voiceIndex":105,"id":"exchange-032"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今中国で流行している、既に死者が１００人を超したというのですけれども、新しいインフルエンザのタイプの感染症に関しては、今のところ、厳重に経過を見るということでよろしいわけですね。","respondent":"佐藤品川区保健所保健予防課長","answer":"現在のところ、委員ご指摘のとおり、厳重に経過を見ていくという段階です。","voiceIndex":107,"id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それは、新型インフルエンザに限ってという限定で認定されたので、当然、新型インフルエンザ対策の中に組み込まれてくると思うんですけれども、それに関しては、今のところ、東京都のほうからも、厚生労働省のほうからも何もないから、今、国のほうを注視するということでよろしいわけですか。","respondent":"佐藤品川区保健所保健予防課長","answer":"おっしゃるとおり、こちらのほうも、情報収集に努めてまいりたいと考えています。","voiceIndex":109,"id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この行動計画の９ページの品川区の役割のところで、発生時にはとあり、最後のほうに、生活支援などの対策とあるんですが、生活支援というのは、具体的に何のことなのか、ちょっとお聞きしたいと思います。","respondent":"佐藤品川区保健所保健予防課長","answer":"これにつきましては、まだこれから関係各所と詰めていくところですので、今後、皆様のご意見、ご要望を聞きながら、なるべく区民の生活が守れるような方向で検討してまいりたいと考えています。","voiceIndex":111,"id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"緊急通報システムについて、ちょっと伺いたいと思っていまして、消防庁型が今回なくなったということですが、予算のところでは書いてあったと思うのですが、委員会では報告がなかったと思うので、緊急通報システムについて、突然ですので、わかる範囲でいいのですけれども、消防庁型がなぜなくなったのか、利用者はどれくらいいたのか。東京都の制度としては残っているのかを、伺いたいのです。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"消防庁型になりますが、この１２月から、今までの機種をつくっていた事業所が、もう製造休止になったということでした。保守を含めて、今年度の１２月までしか継続ができないというようなお話がございました。ちょっと数字を手元に持ってきていないので、何台かというのは覚えていないのですけれども、同じ理由で、それがもうかなり古い機種になっておりまして、メンテナンスが効かないということで。","voiceIndex":116,"id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"東京都としての制度はあるのかということ。後でわかるところで詳しくお聞かせいただきたいと思うんですけれども、有料になったことで、これをつけるのをやめたという方がいたんです。今、孤独死、孤立死がいろいろ社会問題になっている中で、有料になるのでやめるという、この点について、品川区としてはどう考えているのか、ちょっとお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"機種の変更等もあって、今回どうしようもなくやっている部分もありますけれども、見守りというのは緊急通報システムのみではありませんので、地域の見守り体制も広げているところですし、自治会・町会の見守りへの助成金も、今回、拡大しております。","voiceIndex":119,"id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"毎日毎日、皆さんがその方のお宅に伺うというのはなかなか難しいことですし、最後の切り札だと思うんです、この緊急通報システムは。１,０００円かかっていたものを５００円にしていったという軽減していった経過はあると思うんですけれども、住民税非課税の方は無料にするという、今後の考えとしては、区としてはいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今は５００円かかっておりますけれども、機種代とか、設置料というのは、区が全て助成をしているところです。金額が手元にないので、幾らと言えないのですけれども、そういうものを総合すると、５００円という金額がそれほど高い金額にはならないかと思います。","voiceIndex":121,"id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"いろいろ区も支援はされているということですけれども、現に有料になることで、５００円が大した額ではないと言いますけれども、それすら押さえる今の状況ですので、やはり住民税非課税は無料にすることを進めていくべきだし、そういった計画というか、今後を見据えて、高齢者も増えていきますし、孤立死、孤独死がこれだけ問題になっているときなので、ちょっと考えていただきたいと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3382#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":24889,"voices":126}},{"id":"h26-20140415-8","meetingId":"h26-cm04","date":"2014年4月15日","dateIso":"2014-04-15","committee":"建設委員会","time":"午後１時００分～午後３時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区地域交通検討会の開催状況","agenda":"品川区地域交通検討会の開催状況","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"開催状況についてはご説明いただいたのですが、改めて品川区地域交通検討会の設置の目的と、それから、通常、こういう検討会をつくった場合に、例えば区側から何か諮問事項があって、それに対してこの検討会で検討して回答を出すイメージがあるのだけれども、諮問したような感じにも見えないので、改めてこの検討会で当然これから議論されていくでしょうし、そこで得た結論が出るでしょうけれども。","respondent":"中村都市計画課長","answer":"そういったさまざまなものにつきまして、実際に実現が可能かどうかもこの検討会の中で基本的な方針を出して、また、品川区内の役所の組織の中で他課との連携が必要な場合も出てくるかと思いますので、そういったときには、他課との調整なども含めて。","voiceIndex":19,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"この組織をつくること自体については問題ないと思うのですが、諮問がされているのか、ないのかわからなかったので、品川区から例えばこういうようなことをこの検討会に何か区長名で諮問をされたのかどうかの確認と、それから年に２回ということなのですか。そうすると、非常にこれだけの大きなテーマを議論するに当たっては、回数が少ない感じがするのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、非常に曖昧な感じがするわけです。だから、もう少し品川区がリーダーシップをとっていくとするならば、こういう方々を年２回だけではなくて、もう少し集めて、そこから得られるさまざまな情報を行政に活かしていきたいと思っていらっしゃるのでしょうから、それは２回ということではなくて、もっと回数があっても私はいいと思うのです。","respondent":"中村都市計画課長","answer":"委員ご指摘のとおり、まず第１回目としまして、包括的な検討をしたところですが、今後、この会で出されました個々の内容につきまして、具体的な検討にこれから入っていきたいと考えております。","voiceIndex":24,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、目的のご質問が出ていたのですが、こういう報告については、何のための会議かをまず明らかにしていただきたいと思うのが一つ要望ですけれども、今回、「地域交通検討会」という名称がついておりますけれども、私たち、地域公共交通会議が開かれるのかなと思っていたのですけれども、どこがどう違うのかをまず教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"この地域交通検討会、今回の本会ですけれども、こちらは、今後さまざまなバスや、鉄道や、あるいは地域の中での乗用車を利用した交通手段だとか、さまざまなものを検討していくに当たりまして、特に議題を区切ったりですとか、あるいは構成メンバーを区切ったり。","voiceIndex":26,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間の中で私たちが注目しているのは、高齢者とか障害を持った方々の立場を考慮した、移動しやすい交通機関、現在あるものも含めて、新たにそういう手立てもとってほしいというところですけれども、一つは、そういった面でのアンケートがこの間の中ではやられていないというお答えが出ていたのですが、その辺、ぜひ特化して、高齢者とか、障害者とか。","respondent":"中村都市計画課長","answer":"アンケートにつきましても、これもこの検討会の中でも出されたものですけれども、一つは、身障者あるいは高齢者の方にアンケートをとると、そのアンケートの中では「必要ですか」「必要でないですか」というような問いに対しては、皆さん。","voiceIndex":28,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"利便性といった意味では、実際にバス運行業者の方たちもいらしていましたけれども、今の品川区内の道路状況は、交通調査にかかわると思うのですが、渋滞の関係とか、交通量の増減とか、その辺はこの調査に入っているのか、把握されているのかどうか、そこもわかったら教えてください。","respondent":"あべ委員長","answer":"今の議題が「交通検討会の開催状況について」という報告ですので、検討そのものではないので、その点も踏まえてのご答弁ということでいいですね。","voiceIndex":30,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"そう、調査の中で入っているかどうかという意味です。","respondent":"中村都市計画課長","answer":"それからあと、交通の状況ですけれども、これは品川区内だけに限るのはなかなか難しい話で、隣接区あるいは都内全般の交通とも関係してきますので、具体的な交通量の調査ができるか、あるいは統計的な問題、それらは検討してまいります。","voiceIndex":32,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"確認したいのですが、今回の議題の中で、区民からの要望事項ということでこの(4)の意見ということになっていたのですが、この意見は、構成メンバーの中の「住民または利用者の代表」という方々からのご意見と受けとめてよろしいのでしょうか。そこをお願いします。","respondent":"中村都市計画課長","answer":"それからあと、その他の区民から寄せられている声、これは本会議が開催のときにはこの資料が作成されておりましたので、この会での意見ということではなく、それまでさまざま区に要望がございましたものをまとめたものを報告いたしました。","voiceIndex":34,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、この会議の中で「住民または利用者の代表者」はお三方いらっしゃいますけれども、この方からはどういう意見が出ているのでしょうか。三人です。この方たちはどういう意見をお持ちだったのかということで、ここにリンクしてればいいのですけれども、まだほかのものが出ているのか、大体こういう形で出ましたと強調されていることとか、特徴的なものがあれば教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"区民としてのメンバーからの意見ですけれども、これは今、お手元にお配りさせていただいた資料の「主な意見」は、当日、この会議で出たものですが、その中で、区役所の付近の５差路の立会道路と三間通りの逆走が、この中から意見として出されました。","voiceIndex":36,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"二つあります。せっかく代表ですから、それぞれの団体ですから、いろいろな意見が出ると思うのです。それをもったいないので、しっかりと抽出する仕組みがあれば、アンケートという方法もあるけれども、非常に効率よく、そして、各町会長は本当に地域のいろいろな状況を知っているわけですから、そういう意見がかなり集まるのではないかと思います。そこはいかがでしょうか。","respondent":"中村都市計画課長","answer":"この会の参加に当たりまして、それぞれの３会長のご出席をいただく中では、当然、この会全体の中でのそれぞれの会の中で意見を吸い上げていただく認識は持っていただいているとは思います。ですので、特に第１回目については、そういったことは申し上げてはおりません。","voiceIndex":40,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"せっかくいい機会でもありますし、多分、いろいろな意見が出ていると思います。なので、しっかりと代表者の方に、これはこういう位置づけでたくさんのご意見をいただきたい、皆さんはその代表として来ているということでまとめていただきたいということを、しっかり伝えていただきたいと思うのです。この調査は、誰が、どのように進めていくのかについてお願いします。","respondent":"中村都市計画課長","answer":"それに当たりまして、必要なデータの事前調査は区で行いまして、それを改めてこの会に諮って検討していくというようなことでお願いしていくというようなことで考えております。","voiceIndex":42,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな状況を把握していくという、いろいろな立場から情報交換をしながら、品川区の住民の皆さんにとってどういう交通がいいのか、手段も含めて、先ほどの立場によっても利用の仕方が変わってくると思うので、そこを知るためにも、調査は効率よくやっていただきたいと考えていますので、２回では少ないのではないかと私も思いますので、回数を増やすなり、ただ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-012"},{"speaker":"原委員","kind":"意見","question":"私も、各委員の方々の意見となるべく重ならないようにしたいのですけれども、スタートのときに傍聴させていただきまして、第１回目としては絞り切れない点とか、また、構成員の関係を考えても、これでいいのかという思いもあったのですけれども、まず初めに、次が半年後ということですけれども、事務方は記載がないので、どういった形で１回目、それから今度、２回目。","respondent":"中村都市計画課長","answer":"事務局ですけれども、これは私、都市計画課長以下、都市計画課の職員で構成しております。","voiceIndex":45,"id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"構成員は今後において、というのは、先ほど各会の会長が来ているとか、構成員の方は見させてもらうと、かなり多忙な方々が多いものですから、その中で説明する。そうすると、半年後に会ったときに、同じ内容を繰り返すのでは、あまり成果が上がらないと思うので、その辺のところの持っていき方を区の担当部署としてどういうふうに考えていらっしゃるのか。","respondent":"中村都市計画課長","answer":"この会の回数ですけれども、こちらは今、第１回目でいろいろと課題がございまして、今度整理をして、また必要な調査を踏まえて第２回目に臨みたいとは考えておりますが、回数につきましては、これは第２回目が開かれた状況によりまして、この次が今度は年度末というのではなくて。","voiceIndex":47,"id":"exchange-014"},{"speaker":"原委員","kind":"質問・要望","question":"そうしますと、構成員の問題ですとか、それからあとは、先ほど一部、河川の話もしましたけれども、それだけではなくて、品川区、大田区が絡んで、実際には羽田、先ほどお話もありましたように、区内だけではなくて、隣接区とか、当然、交通の問題ですから、東京都や国との絡みもありますし、ですから、その辺のところは、構成員ということではなくてもオブザーバーであったり。","respondent":"中村都市計画課長","answer":"オリンピック・パラリンピックも、輸送手段を考える上では非常に重要な要素だと思いますけれども、まずは地域に密着した生活活動としての交通手段から解決することが優先順位としては最初かと、また、本会の目的もそういったところにあるのかという認識をしております。","voiceIndex":49,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問","question":"いろいろ質疑を聞いていたのですけれども、すみません、どうもこの位置づけがいまいちはっきりしない感じがするのです。品川区からの諮問さえなければ、それから今の質問の中にはメンバーも今後かえていく話をされています。それがなかなか見えないので質問しているのだけれども、この検討会の位置づけを品川区はどうお考えなのですかというところでお伺いしているのですが。","respondent":"中村都市計画課長、藤田都市環境事業部長","answer":"第１回目でいろいろと出されたわけですけれども、例えば具体的に申し上げますと、バス停のバリアフリーならバリアフリーで一つの解決方法を検討していかなければいけない、こういったものが列挙されたのかなと考えております。第１回目ですが、実はやはり構成員のメンバーの方々に品川区の現状をまず知っていただこうということで、その現状をお知らせするのが中心であったので、そのことも含めて考えると、テーマが絞りにくい。","voiceIndex":53,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問","question":"だから、それを、例えば私の思いとしては、１年、２年、時間を区切った中で集中して意見を出していただいて、それを成果物という形で、例えば品川区に諮問するなり、検討会が諮問するなり、そういうふうにしていくべきであると思うのです。そうしないと、この検討会だけがずっと続いていって、何かだらだらと重ねていくようなことであってはいけないと思うのですが、そのところはいかがでしょうか。","respondent":"中村都市計画課長","answer":"これを区だけで検討するよりも、効率よくいろいろなアイデアが出されるのではないだろうかというような期待も含めてこの会を構成しているわけですので、最終的にこの会の中で結論が出て、それを、ではそのままやっていくということではなくて。","voiceIndex":56,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめますけれども、事務局が品川区の方がやられるわけですから、それはやり方としては、この検討会の方向性をいろいろリードできると思うのです。だから、ここで出た意見をぜひ集約していただいて、そういう方向へ持っていっていただきたいのと、それから、検討した結果がこうだったということについては、ぜひ議会への報告をお願いしたいと思います。議会とかさまざまな形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"福祉バスのところもそうですね。あちこちでいろいろな方法をとられているので、そういったところもぜひ集約して、よりよい会議にしていただきたいと思うのですが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"こういった個々の意見全てに対応することはなかなか難しいことだと思います。コミュニティバスのあり方そのものも、今ある路線バスとのすみ分けも整理をしていく必要があると考えておりますので、引き続き検討してまいります。","voiceIndex":59,"id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"最後、簡単に。あえてなぜこの会議体をつくらなければいけなかったのかと私は思って、新規事業にするよりは、既にある事業をもう１回ローリングして見直して、それを充実させることのほうが私はむしろ大事だと思いますけれども、それについてご意見をお伺いいたします。","respondent":"中村都市計画課長","answer":"この会議だけが検討の時間ということではなく、これを受けて区でもさらに調査を進め、また、解決方法については継続して検討しておりますので、この会議だけが検討の場ではないというところをご理解いただければと考えています。","voiceIndex":61,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"それは、中村課長はかわったばかりなので、流れを見るというよりは、何が言いたいかというと、要は、現状ある事業をしっかりともっと精査していただいて、「いたずらに」という表現が適当かどうかはわかりませんが、新規事業ということで新たに入れるよりも、むしろ現状あるものをもう１回見直しをしっかりやっていくことが大事なのではないかと私は思ったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-021"},{"speaker":"こんの副委員長","kind":"確認","question":"検討会という形でなされたということですけれども、認識としては、これまで議会の中でも一般質問で、あるいは党としても区民の交通の利便性というところで交通会議の必要性を話をしていたこともある中で、たしか議事録を確認すると、昨年の１１月の建設委員会等でもこの話題が出ておりますので、当然、地域公共交通会議という形で進んでいくものと認識しておりました。","respondent":"中村都市計画課長","answer":"第１回目でいろいろと課題として主な意見として出されたものにつきまして、一遍に解決できればそれにこしたことはないのでしょうけれども、なかなか一方通行を逆走するものですとか、そういった非常に多くの時間をかけてまだ検討。","voiceIndex":64,"id":"exchange-022"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"おっしゃるとおり、なかなか見通しが難しいというのはわかっているところですけれども、スピーディーにというお言葉もいただいたので、より進めていただきたいという要望ですけれども、一つには、オリンピック・パラリンピックというところでの見通しも、東京都で招致されたこともあると、安全・安心なまちづくりにもかかってくることだと思います。","respondent":"中村都市計画課長","answer":"この会議の中で解決に当たりまして、検討会のメンバー、例えば自動車の運送業者ですとか、それからあと法律的な解決では警察署や、あるいは道路管理者、こういったさまざまな機関の意見を踏まえて、そして迅速に解決していく必要があると考えております。","voiceIndex":66,"id":"exchange-023"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"見通しとしてここではっきりしたお答え、あるいはお考えというところでの確認はさせていただきましたので、これからの後も、この検討会のこれは原則公開していくことですけれども、見ていけばいいことでもあるのですが、機会あるごとに議会にもご報告をということを私も要望しておきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-024"},{"speaker":"あべ委員長","kind":"質問","question":"私からも２点、お伺いしたいと思います。１点。こういった会議体ができたこともよかったと思います。今後、品川区での交通政策は、区の中では都市計画課が中心になって取り扱っていくことになるのだという理解でよろしいかどうかということを１点お伺いしたい。","respondent":"中村都市計画課長","answer":"今、福祉関係部署ということで、これは出された課題の中でも非常にハードウエアの整備に関することやソフトウエアの整備に関すること、いろいろ分類できると思いますけれども、この中で。","voiceIndex":69,"id":"exchange-025"}]},{"id":"topic-02","title":"平成２６年５月都営住宅入居者募集について","agenda":"平成２６年５月都営住宅入居者募集について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"区内の募集戸数は現段階でまだわかっていないということですが、わかるのはいつか教えてほしいのと。これ以前にはわからないのですか、発表するときでしか。その点を知りたかったのですが。すみません、定期使用住宅というのがどういうものか、説明をしていただけますか。","respondent":"矢木住宅担当課長","answer":"２点、ご質問をいただきました。１点目です。申しわけございませんが、品川区内の募集戸数についてはプレス発表前にはわからないです。もう１点目、定期使用住宅と申しますのは、期間を区切りまして使用の許可を与えるといった形式の形態になっております。","voiceIndex":77,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"定期使用住宅のところですが、これはいろいろなタイプがあって、それによって使用期間が違うということですか。ここにとりあえず若年ファミリー向けとか多子世帯向けとあるのですが、どういう区切りがあるのか、教えてください。","respondent":"矢木住宅担当課長","answer":"こちらはさまざまな段階がございまして、世帯員の年齢、構成等に応じまして使用期間が限られているものと認識しております。","voiceIndex":79,"id":"exchange-027"}]},{"id":"topic-03","title":"中延二丁目旧同潤会地区防災街区整備事業準備組合設立について","agenda":"中延二丁目旧同潤会地区防災街区整備事業準備組合設立について","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"０.６haで地権者の方が８４名いらっしゃるということですけれども、この０.６haの中に住宅が何棟あって、地権者ではない方がどのくらいいらっしゃるのかを一つ知りたいのと、あと、５７名の方が加入されていますが、未加入の方、準備組合に入っていらっしゃらない方がどういう状況なのか、内容がわかったらありがたいので、よろしくお願いします。","respondent":"品川木密整備担当課長","answer":"地権者数は８４名ですが、大体、棟数として８４棟程度、８０棟から９０棟ぐらいあるとご認識していただければと思います。","voiceIndex":85,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"勉強会とか、個別の調査とか、結構細やかにいろいろこの間されていらっしゃるのですけれども、到達点は今はどういう状況に、何かいろいろな建築物も案が出ては変わったりとかも聞いていますが、到達点がどうなっている、特に共同化の問題と、共同化は嫌でほかの案でとかという、その辺の到達点を教えていただきたいのと、今後、準備組合が進めるのですけれども、例えば組合に入っていらっしゃる方もいるし。","respondent":"品川木密整備担当課長","answer":"これも、都市計画決定をとる前の段階で、大体の概算の規模となりますけれども、一応、それを計画して都市計画決定をとっていくというような流れになっていると考えております。","voiceIndex":87,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"ここの点線のところが全部対象になってしまうと、例えば、先ほど道路側はある程度しっかりされている部分があるということで、そういうところもあると思うのですけれども、全部が共同建て替えとかいろいろな形での対象になってしまうのか、そこはいかがでしょうか。","respondent":"品川木密整備担当課長","answer":"資金面で厳しい方もいらっしゃれば、あとは家を建替えたばかりという方もいらっしゃいますし、まだいまだにこの地区で新築される方もいらっしゃいますし、そういった方については、当然、家を建てたばかりなのに共同建替えとはどういうことですかということで。","voiceIndex":95,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"新しく新築されている、大分前から視察へ行ったりすると、結構、建替えされている方がいらっしゃるのです。でも、ここは、かなり前から危険度が高いと言われている上に、なぜ建替えするのかと私は疑問に思っている部分があるのですが、その対処法があるのかどうかわかりませんが、そこで規制がかかっていなかったのか、保護法はいずれはというようなところはなかったのかというそこだけを教えてください。","respondent":"品川木密整備担当課長","answer":"ですので、建替えていただく、いただかないは、地権者というか、個人の方々の自由という形になります。例えば新しく建替えている方につきましても、ここが共同建替えを考えているのは認識しての建て替えという形で建替えられていらっしゃる方もいらっしゃいます。","voiceIndex":97,"id":"exchange-031"}]},{"id":"topic-04","title":"百反ずい道周辺道路の交通規制変更の周知について","agenda":"百反ずい道周辺道路の交通規制変更の周知について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"それとあと、現階段を使って、オレンジの歩道がなくなるわけですけれども、ここの時期的な問題がどうなのかと思って、不都合がないかどうか、そこを一つお伺いしたいのが、人が通るとき。新設の歩道橋は、エレベーターで自転車も行けるのですか。その辺を教えてください。","respondent":"溝口都市開発課長","answer":"これにつきましては、新たな赤い一方通行化にあわせて、２.５ｍの通行部分、歩行者が通れる部分を確保いたしますので、それに伴っての歩道の撤去、階段閉鎖となりますので、今回の交通規制の変更時期に合わせて閉鎖するような形で考えております。","voiceIndex":103,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"確認","question":"赤いところの歩道部分が設置されても、車道の部分は変わらないのでしょうか。そこを一つ確認したいのと、あと、自動車のルートですが、一方通行区間を設けるということですけれども、百反の通りからずい道を通って、今まで右に行けましたね。だから、第一三共とか、貨物とか、工業団地等があるあの地域は、右側を通って行く地域の利便性がどう変化するのか教えてください。","respondent":"溝口都市開発課長","answer":"これを解消するべく、今度は、この後、説明しますけれども、広町一丁目の第一三共の地区計画等の定めた中で、新たに三嶽橋から百反ずい道に向けての８ｍの道路を地区計画で設置することになりましたので、そういったところで大型のトラックが通れるように、または。","voiceIndex":105,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"周知のところに、関係町会等への説明をきちんとしていくということは、ぜひ、特に第一三共で、今、工業団地、車は結構使っていらっしゃる方が多いので、その辺の遠回りをしてうんと時間がかかってしまうようなことがないようにしていただきたいと思うのですが、その辺のコミュニケーションは既にできているのでしょうか。","respondent":"溝口都市開発課長","answer":"広町一丁目の地区につきましては、この後ご説明しますけれども、広町一丁目地区の地区計画を定めるということで、かなり私ども、地権者の中に入っています。","voiceIndex":107,"id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問","question":"両面通行が一方通行になることは理解しているのですが、これだと、百反ずい道から山手通りまでの間のところが、信号で車が渋滞する可能性がより出てくると思うのだけれども、当然、そのことは警察署と協議をしっかりとしたのでしょうけれども、そのことについての品川区の見解と、それから、例えば両面通行が一方通行になるわけだから、何かしら新しい。","respondent":"溝口都市開発課長","answer":"今回、この歩道設置と、またあわせて一方通行化をする際に、うちの中でも平成１６年からずっといろいろ検討していく中で、最終的にこの案でということをしております。","voiceIndex":109,"id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"単純に車の量が二倍になるわけです。だから、そういう見通しでいいのでしょうかという心配があるのですが、例えばそれを実際に交通量をはかって、確かに物理的にこうだということがあるのだったらまだわかるのですけれども、現状でこのままでいいのではないかというのは非常に不安なので、そのことについてのご答弁をあわせてお願いします。","respondent":"溝口都市開発課長","answer":"ただ、今後、やはり実際見ていく中で、規制後の話にはなりますが、今、現状でいきますと、交通量調査とかそういったものを勘案して、渋滞しないという結果が出て、そういったものを協議して警視庁とも定めておりますが、例えば信号現示の変更とか、そういったものも、今後。","voiceIndex":111,"id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"まとめますけれども、この周知ですけれども、町会とか地元に言っているのは当然なのだけれども、運転する方々、ここを常時通る方々に対しては、例えば一つの期間のチラシか何かを配って、いつからこうなりますよとか、もっと利用者の目線に合ったＰＲをするべきと思うのですが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"委員言われたように、利用者、特に車の利用者の方に影響が大きい工事ですから、そういった中でどうやって周知していくかは、引き続き検討していかなければいけない部分でありますが、今の段階でいきますと、なかなか予算の話もありますけれども、看板等、また。","voiceIndex":113,"id":"exchange-037"}]},{"id":"topic-05","title":"広町一丁目周辺地区地区計画について","agenda":"広町一丁目周辺地区地区計画について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"Ｃ地区の地権者の方が何人いらっしゃるのか、また、そのほかの方がどのくらいいらっしゃるのかと、あと、この地域でものづくりが多いと思うのですが、どういった業種があるのか、その辺を教えてください。","respondent":"溝口都市開発課長","answer":"当地区の権利者数ですが、権利者数でいきますと、Ａ、Ｂ、Ｃ全部合わせて４５人の権利者がいます。そのうちＣ地区が一番多くなっていまして、権利者数としては４０人の方がいらっしゃいます。","voiceIndex":119,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"Ａ４判に、平成２５年１２月１２日に「Ｃ地区の地区整備計画策定に向けての意向把握」と書いてあるのですが、この「意向把握」の中身がどのようなものなのか教えてください。","respondent":"溝口都市開発課長","answer":"Ｃ地区の意向把握とは、まさにこの下に書かれております地区整備計画として新たに今回定めた新たなものですから、建物の用途制限ですとか、敷地の最低限、または建物の形態・色彩、その他意匠に関する制限、そういったものの制限をかけていくことになりますので。","voiceIndex":121,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"現段階においていろいろな意見を伺っていると思うのですけれども、慎重な意見とか、困るというような反対の意見とか、いろいろあるのでしょうか。その辺を教えてください。","respondent":"溝口都市開発課長","answer":"ただ、今、土地利用転換というか、工場を廃止してほかのものに利用する場合、どのようなものができるのかという問い合わせですとか、今回説明している説明会の中で一番多かったのは、先ほど報告した広町一丁目の百反ずい道の一方通行化もあわせて報告していますので。","voiceIndex":123,"id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問","question":"この内容とは違う話で申しわけないのですけれども、日本ペイントがこのＣ地区の中に入っています。ここにご承知のように明治記念館、ご存じですか、日本で初めてペンキがつくられたところ、これは品川区の教育委員会のお願いで日本ペイントが保存されているわけです。だから、そういうものは当然、残してほしいということを品川区から言っていくべきだと思うのです。","respondent":"溝口都市開発課長","answer":"委員が言われた明治記念館の件は、日本ペイントとも今後お話しする機会がありますので、そのときにもあわせてお願いしていきたい、また、あと教育委員会との連携はしっかり図っていきたいと考えております。","voiceIndex":125,"id":"exchange-041"}]},{"id":"topic-06","title":"続きまして、(6)「環境マネジメントシステム再構築について」","agenda":"続きまして、(6)「環境マネジメントシステム再構築について」","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ＩＳＯ１４００１ですけれども、これは区独自でということになるのですが、これは何が不足していてこういう経緯になったのか。区独自のＥＭＳは、普通、企業でもこういうＩＳＯを取ると、それでステータスになるということになると思います。なのに、区独自のＥＭＳとなると、果たしてそれが、そこがなくなるわけですね。どうしてそういうふうになっているのか、その理由をまず教えてください。","respondent":"三ツ橋環境課長","answer":"環境マネジメントシステムというものがございまして、その中の一つの手段がＩＳＯ１４００１でした。それが、今はもう職員の意識なども大分統一されまして、環境への意識を図ってまいりましたので、区独自でも大丈夫だと考えております。","voiceIndex":131,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"それが「品川区の」と言っても、皆さん、知らないわけで、これは今、ほかの自治体なども含めてこういう傾向にあるのか、どういう形で、返上までするわけですから、今、このＩＳＯはあまり意味ないですよということで、これを取っても別に品川区がほかの自治体と比べていいとか、悪いとか、そういう指針にはならなくなってしまったということなのか、その辺はいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"現在、２３区中、品川区以外でＩＳＯを取っているところは、３区のみになっております。１９区は、ほかの独自のＥＭＳになっております。","voiceIndex":133,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ということは、１９区が取っていないということは、別にＩＳＯを取っても仕方ないというか、そういう考えで１９区には広がらなかったのか、独自でつくっていったということの意味合いがよくわからないのです。ＩＳＯ自体がそんなに世の中できかなくなってしまっているのか、むしろ自治体独自のＥＭＳのほうが、世の中では認められる世界になってきているのか、そこら辺はどういう考え方なのですか。","respondent":"三ツ橋環境課長","answer":"従来のＩＳＯのすぐれたプロセスは継承しつつ、区独自の効率化、実効性を進めていこうと考えています。","voiceIndex":135,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"ＩＳＯは、世の中的、世間的に言うと、今、余り言わなくなってきたのは事実ですけれども、ただ、ＩＳＯを認定されると、そこはきっちりとやっている証明になっていたわけです。そういう基準から返上してまでというところがよくわからないのですけれども、どういうことなのですか。","respondent":"三ツ橋環境課長","answer":"説明不足で申しわけありません。今、現在のところ、環境ＩＳＯと、そのほかに省エネ法や実行計画などがあります。","voiceIndex":139,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今まではこうでしたが、これがこういうふうに変わっていって、ちゃんと守られていきますよというものを、これからだと思いますが、きちんと示していただきたい。だから、どこでどういうふうに管理をしていくのですかという、その辺を知りたいと思うのと、あと、財政面でどう変化をしていくのかというあたりも教えてください。","respondent":"三ツ橋環境課長","answer":"費用面に関してですけれども、費用面に関しては、今年度のコンサルティング代のみで、次年度以降はかからない予定です。","voiceIndex":141,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろなところ、では、今年度はコンサルティング業者とともに再構築をしたら、庁内でしっかりと管理をしていける状況になるということなのですね。では、特別にたくさんの財源はかかっていかないと。よそなどはそういう感じでやっているところが多いということなのでしょうか。このコンサルティング業者がどういうところなのか、そこも教えてください。","respondent":"三ツ橋環境課長","answer":"コンサルティング業者につきましては、知識研究所というところで実際にプロポーザルを行った中で選定いたしました。","voiceIndex":145,"id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問","question":"多分、この再構築をした目的は、わざわざＩＳＯ１４００１の審査を取ったのに、お金をかけずに、１４００１審査に基づく規格を新たにつくって利用することで、結果として税金を安くおさめられるし、それから品川区のさまざまな環境に貢献する仕組みをつくり上げていくから、返上してこれにしていくのだということでよろしいのですよね。答弁をお願いします。","respondent":"三ツ橋環境課長","answer":"委員のおっしゃるとおりです。","voiceIndex":147,"id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問","question":"要は、何で１４００１を返上してＥＭＳに変更するかということについても疑問でわからなかった。そうしたら、ぜひ改めてそういうふうな施政をしたということは、先ほど西本委員がおっしゃったように、進んだわけじゃないですか。１４００１シリーズではなくて、さらに進んでこうしたと。しかも、税金を節約したということであるから、それはぜひさまざまな形でＰＲしていっていただけないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-049"},{"speaker":"原委員","kind":"質問","question":"そうしますと、先ほど、もう１回すみません、コンサルティング業者名をお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-050"},{"speaker":"原委員","kind":"意見","question":"いいです。非常に選定するのは簡易型のプロポーザルで難しかったと思うのです。この二つの方向ですが、今後、このコンサルタントの、今はパート、パートでいろいろな部分で話し合っているということですけれども、再構築についてというご説明なので、入り口部分で結構なので、その辺のところを環境課長としてお話しいただければと思います。","respondent":"三ツ橋環境課長","answer":"入り口部分での環境の再構築ということですけれども、実際問題、今、話し合っている最中ですけれども、先ほど言いました、従来のすぐれたプロセスは継承しつつ、効率化と実効性の両立ということを考えておりますので、実際にＩＳＯよりも退化しているとはみなさず。","voiceIndex":152,"id":"exchange-051"},{"speaker":"原委員","kind":"質問","question":"これだけで終わりにしますけれども、伊藤委員がおっしゃったように、今後については、今まで本当にほかの委員の方もおっしゃっていたし、西本委員も話したように、ＩＳＯ、ＩＳＯと庁内でいっぱい張ってあったと思います。区の経費を使って税金を無駄にしないでいくわけですから。ただ、方向性を間違えないでお願いしたいということなので、その辺についてお考えがあればお願いします。","respondent":"三ツ橋環境課長","answer":"じっくりと検討していって、方向性を間違えないような体制にしていきたいと思いますので、よろしくお願いいたします。","voiceIndex":154,"id":"exchange-052"}]},{"id":"topic-07","title":"エコライフアイデア・コンテスト等について","agenda":"エコライフアイデア・コンテスト等について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"低公害車の買換え支援事業ですけれども、これの窓口はどこにあるのか。予算的なものも教えていただけますか。","respondent":"三ツ橋環境課長","answer":"窓口ですが、環境課の環境推進係で受け付けております。予算につきましては、２００万円程度となっております。２００万円ぐらいです。","voiceIndex":160,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"買換えの時期、新たな低公害車への買換えの支援ということですが、前回がいつごろだったか、よくわからないのですが、この利用はどのくらいあるのか、わかったら教えてください。","respondent":"三ツ橋環境課長","answer":"新たな買換えの時期ですが、前回、利子補給や保証料、低公害車利子補給、買換え利子補給を、平成１５年から１９年に実施しておりました。そして、それから７年程度たちましたので、買換えの時期としています。利子補給の利用状況は、平成２６年に受け付け済みのものに、予定額ですけれども、平成２６年度は恐らく１００万円程度、それから平成２７年度については５０万円程度となって、実績については今すぐに把握しておりません。","voiceIndex":162,"id":"exchange-054"},{"speaker":"大沢委員","kind":"質問","question":"サマールックキャンペーンですが、表紙は広告代理店に頼んだのですか。","respondent":"三ツ橋環境課長","answer":"広告代理店に依頼いたしました。","voiceIndex":166,"id":"exchange-055"},{"speaker":"大沢委員","kind":"質問","question":"まとまる質問ではないのですけれども、どうもサマールックキャンペーンでも、脈絡がなくて、いろいろ金魚が出ていたり、風鈴がついていたり、この絵図柄しかなかったのかもしれないですけれども、これ、脈絡がなさ過ぎるような気がするのですけれども、そこのところはどういうふうにお考えですか。何を基準にしてこれを選ばれたのか。","respondent":"三ツ橋環境課長","answer":"地球を基準にして、地球のところで、例えば北極にいる北極熊が地球にとってよいように、品川区から節電をしていけば環境によいというイメージです。","voiceIndex":171,"id":"exchange-056"},{"speaker":"大沢委員","kind":"意見","question":"西アジアのところに北極熊がいる、おかしな絵のような気がするのです。トナカイが海の上にいるし、金魚がこっちへぽっと出てくるというのは、もう少し脈絡があるような絵図柄を選んでいただいてもよかったのではないかという気がするのですけれども、どう感じられますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":173,"id":"exchange-057"}]},{"id":"topic-08","title":"大井火力発電所 ガスタービンについて","agenda":"大井火力発電所 ガスタービンについて","exchanges":[{"speaker":"西本委員","kind":"質問","question":"廃止理由の中で、今後新たな電源の営業運転、試運転が順調にということですが、どういう形になっていて、どこから順調になっているのかという、その辺をもう少し詳しく教えてください。","respondent":"三ツ橋環境課長","answer":"営業運転につきましては、広野火力発電所６号機、常陸那珂火力発電所２号機が平成２５年１２月に運転開始をしております。試運転につきましては、鹿島火力発電所７号系列、千葉火力発電所３号系列が、平成２５年１２月から３月にかけて順次開始しております。","voiceIndex":180,"id":"exchange-058"}]},{"id":"topic-09","title":"３、その他","agenda":"３、その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"劇団四季に行くのに、余りよろしくないというか、雰囲気的にあそこに３ｍでどーんとなってしまうと、威圧感がありますし、景観上もよくないと思うので、例えば絵を描くとか、そういう劇団四季をバックアップするような、そういう景観を配慮していただけないものかと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"それとあと、３ｍの鋼板の関係ですが、まず劇団四季のところになるのですが、前面にシートを張って美装化しているフェンスは取り除いておりませんので、それの後ろに３ｍの鋼板がつくような形にはなっておりますが、ＪＲ東日本には劇団四季等の来客者が多い。","voiceIndex":186,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"雰囲気が悪いと、なかなか入ってこられなくなるし、結局、商店街等々も、一応、応援している段階でもありますので、そこは協力していただかないと、ということはかなり強烈に強めに言っていただきたいところがありますが、いかがですか。","respondent":"溝口都市開発課長","answer":"ただ、取り壊しについては、その前にやりますので、多分、方針が例えばこの平成２６年度中に決まれば、平成２７年から解体工事に入るようなスケジュールになっていきますので、区といたしましても早急に、また、ＪＲ東日本とも同じようなことはわかっていますので。","voiceIndex":188,"id":"exchange-060"},{"speaker":"木村委員","kind":"質問・要望","question":"劇団四季の土地が区の持ち物ということでありますから、ＪＲ東日本と品川区が主に協議をして、何か一つの大きなまちをつくっていくということになろうかと思いますけれども、そこに東急電鉄が横にありますから、これとの関係というものがわかれば教えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"そういった中でいきますと、まちづくりはこの社宅跡地だけ、または劇団四季が入っています、それとあと駐車場も、品川区の土地だけでできるものではありませんので、そういったところの連携は必要になってくると思いますので、いずれ品川区、ＪＲ東日本、東急電鉄を含めて。","voiceIndex":190,"id":"exchange-061"},{"speaker":"木村委員","kind":"質問","question":"店が営業停止になりましたけれども、そういうところも、今後、そういうものができれば、そういうところとＪＲ東日本の跡地にできる建物とも何か一緒に連帯ができるのかどうかということと、あともう一つ、大体これを、くしくも２０２０年、東京オリンピックになりますけれども、これに合わせて計画が進んでいきそうなのかどうか。","respondent":"溝口都市開発課長","answer":"ただ、私どもだけでなくて、地主はＪＲ東日本になりますので、ＪＲ東日本の意向等も酌みながらやっていきたいと考えていますが、一つのキーとしては２０２０年を目指すというのはあると思いますので、そういった中で何ができるのかは、引き続き検討していきたいと考えています。","voiceIndex":192,"id":"exchange-062"},{"speaker":"伊藤委員","kind":"意見","question":"１点だけですけれども、写真を見て気になったのですけれども、向かって左側、「万能鋼板による閉鎖」という緑のところがあります。途中で切れているのです。だから、何なのか、それだけのことですけれども。","respondent":"溝口都市開発課長","answer":"跡地利用については、今後、どのようになるのかは、ＪＲ東日本で検討しているというのが今の状況です。","voiceIndex":194,"id":"exchange-063"},{"speaker":"伊藤委員","kind":"質問","question":"今、話の中で駐車場に貸し出すということがあるとするならば、これはより一層、安全対策なり、時間貸しの駐車場になるのでしょうね、多分、そうすると、いろいろな方々がここに来られるようになるわけだから、そうすると、万能鋼板を張るだけで、果たしてそれで安全面が担保できるのかという心配ができたので、それはどうなのですか。","respondent":"溝口都市開発課長","answer":"そういった中で、例えば３ｍの万能鋼板だけでは不十分で、中に入られたりとか、そういったところ、また、建物の下には入れないような対策はとりますが、それでは不十分だとか等々出てくる場合については、ＪＲ東日本が言っていることには、まずこの形でやらせていただいて、今後。","voiceIndex":196,"id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問","question":"そういうリスクを抱えるこういう建物については、品川区としては厳しい指摘をしていただいて、例えば防犯対策をしっかりしていただくなり、それから、監視カメラなりをつけていただくなり、ハードルを上げていただいて、不特定多数の方々が横行するのはＪＲ東日本としては仕方のないことだけれども、それに伴うさまざまなリスクについては抑え込むようなことを。","respondent":"溝口都市開発課長","answer":"これまでの経緯としては、しっかりＪＲ東日本のほうでも、警察、消防と協議していく中で、ここまでの対策をとると決めている経緯もありますが、より安全な市街地に向けて、しっかりとＪＲ東日本にはさらなる安全対策については要望していきたいと考えております。","voiceIndex":198,"id":"exchange-065"},{"speaker":"伊藤委員","kind":"意見","question":"これで最後にしますけれども、ご承知のようにお召列車がここにありますよね。だから、いろいろな方々が来る可能性があるわけですよ。天皇陛下に対していろいろな考えを持つ方がいらっしゃるわけだから、そういういろいろなリスクが高まっていることは当然であるので、それはきちんと品川区として強く申し入れをしていただいて、安全策をとるようにお願いしておきたい。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけですが、跡地利用が決まるまで撤去しないということですけれども、現存している建物の耐震性がどうかはわからないですけれども、６強とか、７とか、大きな地震が来たときに、倒壊の危険性とか、周囲に与える影響とか、その辺はないのか、考えられているのかどうか、１点だけ教えてください。","respondent":"溝口都市開発課長","answer":"そういった意味でいきますと、耐震性は低いものであるというのは事実だと思います。とはいえ、これだけの広大な空地がありますので、それなりの避難地域の確保ができると考えているところです。","voiceIndex":201,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"なので、大丈夫ということですね。阪神・淡路大震災のときは、大きなビルごと倒れたりとか、いろいろな状況があったので、耐震性がないと言われている建物なので、できたら早く撤去して更地にするほうが安全ではあると思いますけれども、でも、その辺は検討されて、ＪＲ東日本においては大丈夫であるというところの判断なのですか。もう１回、そこのところだけお願いします。","respondent":"溝口都市開発課長","answer":"今回、跡地利用等の検討をしていく中で、ＪＲ東日本については、そういった広域避難所の場所であるという指定ということはしっかり言ってきております。そういった中で、一定の検討をしていく中で、広域避難所としての機能は確保できると考えてきているものです。","voiceIndex":205,"id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"鉄道事業者はご存じのように区と比べると、力関係はかなり強いと思いますけれども、先ほど来、課長のほうで、区の意思をしっかりと伝えていくという、「しっかり」「しっかり」というお言葉をいただいたのですけれども、しっかり伝えるためにどのようにしていこうと考えているのか、また、ＪＲ東日本にしっかり伝えるためには、どのように向き合うべきだと考えているのか。","respondent":"溝口都市開発課長","answer":"ただ、「しっかり」というところでいきますと、一つは、回答を求めるのが一つだと思いますので、区のほうから安全対策について検討ということで文書を出して、それに対するＪＲ東日本の正式な回答をいただきながら、そういった形で要望していきたいと考えているものです。","voiceIndex":207,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"補助２９号線と放射２号線の沿道でアンケート調査が行われたと思いますけれども、このアンケート調査の中身とか結果を議会にご報告してくださるのかどうか、また、地域の住民の方にどのように返していかれるのか、その辺をお伺いします。","respondent":"品川木密整備担当課長","answer":"その報告を行う直前ぐらいに議会にもご報告したいと考えています。それから、不燃化助成ですけれども、周辺の用途とあわせた形で不燃化助成も行っていきたいということがありまして、その辺、今、東京都とタイミングを調整しながら進めているような状況です。","voiceIndex":212,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問","question":"まだ時期的にはいつと言う状況ではない、近々ではないのですね。なので、いつぐらいに、どういった中身が報告されるのかが知りたかったのと、用途変更ということでは、地区計画の変更が出されるということですか。","respondent":"品川木密整備担当課長","answer":"用途変更のほうも、地区計画をやるのか、やらないのかというあたりも、東京都と現在、調整している段階です。ですので、説明会等はいついつと申したいのですけれども、まだ現状では、未定という段階ではあります。","voiceIndex":214,"id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4102#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":48254,"voices":217}},{"id":"h26-20140415-9","meetingId":"h26-cm04","date":"2014年4月15日","dateIso":"2014-04-15","committee":"文教委員会","time":"午後１時００分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"(1)平成２６年度学級編制","agenda":"(1)平成２６年度学級編制","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"第四日野小は２クラスだからあれですけれども、これは下を見ると、弾力的運用で学級編制３クラスに品川区の判断でしたということなんですけれども、ここのところをもう一度説明していただきたいのと。そのあたりを教えていただきたいのと。具体的な内容について教えていただきたいと思います。よろしくお願いします。","respondent":"野呂瀬学務課長","answer":"それと加配というものの考え方ですけれども、３５人に対して教員を１人配置するという、それが２クラスになれば教員をクラスに張りつけるんですけれども、それに対しては、例えば３５人以上になったとしても、例えば１クラスを２人の先生で見るとか。","voiceIndex":19,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"だから、２人配置をしているんだということなんだろうと思うんですけれども。したがって、だから、とりわけ伊藤学園の中学１年生のところで言えば、教室の学校のキャパの部分でもう無理じゃないかなというのがあって、３７人でもやむを得ないというふうに判断して、教員を１人加配しているのかなというふうに私は理解したんですけれども、伊藤学園ではそういうことではないわけですか、というのが一つ。","respondent":"渋谷指導課長、野呂瀬学務課長","answer":"中学校の場合は、教科で加配の先生をもらえますので、学校経営を考えていったときに、うちの学校は英語に力を入れたいといったときに、学級数の関係で１人プラスアルファ人がもらえるといったときには英語の先生をとりたいというような。なおまた、その学級数において、やはり子どもたち一人一人に応じた教育の実現をしていく、これに対しては何ら変わるところはございません。","voiceIndex":21,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そのこと自体は本当にうれしいなと、教育分野を担当する文教委員としても、増えてきているということはそれなりの評価があることなんだろうというふうに思うんですけれども、だからこそ、やはり増えちゃって困っちゃったよなとかということはもちろんないわけですけれども、やはりよりよい教育環境を整えてほしいという思いの中で質問をしているんですけれども、さっきの説明の中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"小学校で５校、中学校で１校、このような判断をされているんですけれども、その最終的にそういうふうな判断をしたという、これだという部分を説明をしていただきたいのと。校長判断と区の判断というのがありますけれども、先ほどの答弁では校長判断ということだったんですけど、この弾力的判断は区が判断するということなんですけれども、その辺の仕分け方というんでしょうか。","respondent":"野呂瀬学務課長","answer":"ただ、１年生だけは３５人でずっといくわけではなくて、そういう考え方も含めて、じゃあ、１年生はちょっと多いけれども、２年生、例えば中学校でも８年生になったらもう４０人学級なんだからとか、そういう考えも総合的には学校長の判断の中には入っていると思います。","voiceIndex":25,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"弾力的運用でやっている判断をする必要があるのかなと思うんです。この１クラスで済むところをあえて２クラスに、３７人であれば３７人で１クラスで可能なのに、１８人、１９人にする部分、その説明と言うんでしょうか。１クラスで済むのであれば１クラスのほうがいいのではないのか。少人数がいいと先ほど質問が出ていたんですけど、私はその真逆を言っているんですね。","respondent":"渋谷指導課長","answer":"そうなると、ある程度のやっぱり一定規模のきちっとした集団の人数を確保しながら教育活動を行っていくということは非常に重要なことだというふうに考えているところです。","voiceIndex":27,"id":"exchange-005"}]},{"id":"topic-02","title":"平成２６年度移動教室について（小・中）","agenda":"平成２６年度移動教室について（小・中）","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"中学校のほうなんですけれども、二つ行き先があって、これはどういうふうにしてそれぞれの学校がどっちへ行くというふうに決めているのかというところ。それだけ教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"もともと中学校は裏磐梯の福島のほうを中心に進めていたところでありますが、先の事故を受けまして、菅平を選択肢として選んだということで、あとはただオプションとしてさまざまな選択肢がやはり福島のほうが雨天コースも含めて非常に多様なコース展開ができるということで。","voiceIndex":34,"id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"やはり安全が確認できないというのは何かなと思ったんですが、その震災関係ということだというふうな理解をしたんですけれども、そうした中でやはり、では、どっちになるんだとなったときに、福島県裏磐梯のほうが若干少な目ということは、やや品川区の皆様、保護者、また、生徒の皆様もそういう心配がいまだにあるのかなと思ったりするんですけれども、そこら辺の、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-007"}]},{"id":"topic-03","title":"荏原文化センター耐震改修他工事に伴う荏原図書館の休館","agenda":"荏原文化センター耐震改修他工事に伴う荏原図書館の休館","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"利用者協議会となると利用者さん中心なのかなと、ちょっと今イメージしたんですけれども、それだけではなくて、周辺に学校は隣にあるんですけれども、住宅も幾つか建っていますので、そういう部分の説明、理解を求める説明だとかも含めてちょっと確認したいのと、それから、その利用者協議会なり何らかの形の説明会で、かなり図書館というと、ここの利用も高いところだというふうに思うし、長期にわたって。","respondent":"中元品川図書館長","answer":"通常この規模の工事規模ですと、周辺住民説明会等は開催をするものではないということで聞いております。それで、また、周辺の学校等には個別に私どもから施設長としてご挨拶は参りますが、住民の方への説明会は考えておりません。","voiceIndex":48,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"１０ヶ月に及ぶ休館なので、近隣の図書館に職員を厚く配置するということとか、いろいろな形での利用はしていただけるような対応をとるということなので、それはそれとして伺っておきたいと思うんですけれども、図書館に対する、夏休み期間はちょっと外れるのであれですけど、ちょっとその辺の長期にわたる工事のときに、私、果たしてそういう体制だけでいいのかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-009"}]},{"id":"topic-04","title":"品川区臨時給付金","agenda":"品川区臨時給付金","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"消費税の引上げに伴いということなんですけれども、１回こっきりですよね、これ、たしか。そこをちょっと確認したいのと。それから、あと申請書を送付で、その申請書をもって１２月中旬までに来るということになるわけですよね。そのあたりを教えていただきたいと思います。","respondent":"福島臨時給付金担当課長","answer":"特に、１２月中旬までの受付期間でありますので、未申請者勧奨などしていく予定です。今想定していますのは、１０月ないし１１月ぐらいで申請されていない方には再度はがきによる案内をするかどうか、その辺のところについても検討しています。","voiceIndex":56,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"そういう理論というのは許されないことだというふうに思います。したがって、できるだけもらわないでしまった方をなくすというふうに、そういう努力というのは本当に必要だというふうに思いますので、１０月から１１月に再度案内状を発送するかもしれないという話なんですけれども、本当に生活を守るという点からも、漏れがないように対応していただきたいということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-011"},{"speaker":"高橋委員","kind":"意見","question":"私、わからないのでちょっとお尋ねするんですけど、結局税の情報を利用して支給するということは、本来の目的と違うものに使うわけですね、税の情報を。その税の情報を本来審議会でしたっけ、にかけて公開するというようなのがあるんですが、そういういろいろな手続なくして、今回の給付金に税情報を使うというのは、どのような仕組みになっているのかというところを、すみません。","respondent":"福島臨時給付金担当課長","answer":"その中に申請書も同封するというような形で行っていきます。こういった形につきましては、国のほうからもそれで大丈夫だというふうに説明を受けていますので、品川区としてもそういうものをつくりまして申請書をお送りする予定です。","voiceIndex":59,"id":"exchange-012"},{"speaker":"高橋委員","kind":"確認","question":"ということは、そういう税の情報を確認したので、そういう仕組みの中で支給しますよということを、支給される方に知らせるということなんですね、その仕組みでいいということで。それを使っていいですか、どうですかという本人の承諾を得たりするという手続きをする自治体もあるとお聞きしているんですけれども、こちらはそういうものがあるということでしょうか。","respondent":"福島臨時給付金担当課長","answer":"区としましては、特にその確認をすることは行いませんで、あくまでも課税されていない方を対象に、課税されていないという情報とともに申請書を送るという形をとりたいと考えています。","voiceIndex":61,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"今の税情報との関係なんですけれども、この通知を発送するにあたっての、ちょっと私、予算書を見てこなかったので単純な質問なんですけど、費用的にはどのくらい経費がかかるんですか。","respondent":"福島臨時給付金担当課長","answer":"〔「その額はいくらかと」と呼ぶ者あり〕 まず、臨時福祉給付金のほうで、申請書のほうで１，５９７万８，０００円を予定しています。もう一つの子育て世帯臨時特例給付金のほうで６００万円を想定しています。","voiceIndex":63,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"発送費用というのは２、０００万円ちょっとぐらい、２，２００万円ぐらいですかね。額的には決して多い額ではありませんけれども、やはり何て言うんでしょうかね、こういうお金の使い方というのはやはり私としてはよろしくないと。そういうことを改めて思って、そういうふうな印象を持つものですから、その私の印象を改めて表明をしたところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-015"}]},{"id":"topic-05","title":"父親のための親育ちワークショップの実施","agenda":"父親のための親育ちワークショップの実施","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"その辺のニーズの兼ね合いというのは、ちょっと背景を少しご説明いただければと思うんですけれども。","respondent":"伊崎子育て支援課長","answer":"先ほど申し上げました、児童センターでは、ここ５年、６年、父親のための子育て支援事業をやっております。","voiceIndex":71,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。あるいはそれはちょっといろいろな意味で課題があるのか、施設の状況とか。その辺だけちょっとお伺いしたいと思います。","respondent":"伊崎子育て支援課長","answer":"今回、初年度ですので、モデル事業として２カ所実施をいたします。ここでの実施の状況を見ながら、今後の展開は検討してまいります。","voiceIndex":73,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"いわゆるニーズがもしあった場合に各児童センターにもっと広げていくという場合に、ハード面とかあるいはソフトの人材面とかというところでの課題はそれほどないという認識でよろしいでしょうか。","respondent":"伊崎子育て支援課長","answer":"人材ですが、児童センターの職員も長い親育ち支援の経験がありますので、企画というところからは問題はないんですが、やっていただく、例えば講師などは目的によって選定が必要になってくると考えております。","voiceIndex":75,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"当然お父さんとしての子育てのいろいろな知識も含めてのワークショップなので、「父子での参加とし」というふうになっているわけですから、０歳なり１歳の子どもさんも一緒に参加をするということですよね。単純に児童虐待をする人がどうこうということではないんですけれども、その辺もちょっと含めた視野で企画していただけたらなと思っているんですけれども、その辺の見解を教えてください。","respondent":"伊崎子育て支援課長","answer":"今後の展開ですが、先ほども申し上げましたとおり、この２カ所での事業の実施状況を検討いたしまして、年内中には考えてまいります。","voiceIndex":77,"id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"モデル事業としてこのゆたか児童センターと大井倉田児童センターということだったんですが、この場所の設定について、ちょっと聞き漏らしたかもしれないので、もう一度、なぜここだったのかというのをご説明いただきたいのと。","respondent":"伊崎子育て支援課長","answer":"こちらの８月の９日と１０日が続いているというところは、実は９日に料理の講師を呼んでお父さんたちに料理をマスターしていただき、１０日にそれを家族を呼んで披露するというプランを考えておりますので、ここは日曜日が入っているところです。","voiceIndex":79,"id":"exchange-020"},{"speaker":"大倉委員","kind":"質問","question":"場所については地域バランスを見て、比較的今まで行ってきたワークショップ等の父親の事業についての参加が多かったということで、人数もそういった参加のバランスを見て１５人ということになったんでしょうか。","respondent":"伊崎子育て支援課長","answer":"ワークショップですので交流ができる人数ということで、あまり多い人数は難しゅうありますので、１５人が適当であろうということで１５人といたしております。","voiceIndex":81,"id":"exchange-021"},{"speaker":"大倉委員","kind":"意見","question":"ニーズがあった地域を選んだということで、そうすると、お父さん方の参加したい意欲が高いところを設定したのかなというところで、本当は、この目的で父親への子育て意識を高めるという部分で言えば、たしかに実績をつくらなければいけないのかなというのもあるんですけれども、お母さん方からお父さんになかなか関心を持っていただけない部分でアピールをするというところとしては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-022"}]},{"id":"topic-06","title":"事業所型家庭的保育事業（保育ママ）の新規開設","agenda":"事業所型家庭的保育事業（保育ママ）の新規開設","exchanges":[{"speaker":"南委員","kind":"質問","question":"初歩的な質問で恥ずかしいのですけれども、保育ママの広さだとか、そういう施設的な基準というのを教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ママが１人増えるごとに、そのお部屋といいますか、区画が増えていくというイメージです。","voiceIndex":89,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとその施設が、広さしかさっき伺わなかったんですけど、施設基準というのが、保育ママで今までは大体、数年前までは個人の方が受けていただいているケースが多かったんですけれども、最近は事業所で人数もずっと増えてきているので、ちょっとそのあたりのことが気になっているので、施設的なところを教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ですので、３．３かける例えば保育ママ３人ですと、本来ならば３０m2あれば一定広さ、保育室は満たすのですが、それ以外にキッチンスペースや先ほどの沐浴スペースなどを含めまして、大体５０m2以上の広さで保育ママ３人の場合は実施しています。","voiceIndex":91,"id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"その開設準備経費として１施設当たり３００万円なんですが、その３００万円で、例えば調乳のいろいろな調理台も含めて必要なものをそろえるとか、沐浴に必要な器具、設備をそろえるとかと、そんなふうな考え方でこの開設準備経費というのが充てられるというふうに考えていいんですかね。","respondent":"今井制度改革・待機児童対策担当課長","answer":"委員ご指摘のとおり、この１施設当たり３００万円の中では、例えばベビーバギーですとか、今お話がありました沐浴のコーナーですとか、そういうものも全て含めまして１施設当たり３００万円という形で助成しております。","voiceIndex":93,"id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"だらだら質問してしまって恐縮なんですけれども、そうすると、今まで事業所型というのは１５カ所になったという説明だったんですが、それぞれ、時々文教委員会でも視察に行って現地を見てきたりすることはあったんですが、大体３人ですから、１０m2かける事業所型３０m2以上の、そのほかに沐浴、調乳、そういうところが設備されているというのは確認してきたところはあるんだけれども。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただし、給食という形で給食をやっている事業者もありますので、事業者によっては給食の関係の広さはいろいろありますけれども、今、委員ご指摘のとおり、調理設備と沐浴スペースですね、こちらについては全て備わっております。","voiceIndex":95,"id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"これは増やそうと思えばこの中にもう一つ、３人のユニットを１８人にする、２１人にするということが可能なのかどうか。その基準の面で可能なのかということと、もしそうだとしたら今回１５人としたという理由をお伺いしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちら、ちょっと皆様の図面といいますか、施設(2)の裏面の予定地を見ていただきますと、少し建物が変則的な形状でございまして、手前のほうに３つの保育室、奥のほうに２つの保育室という形で、今、レイアウトを考えております。","voiceIndex":97,"id":"exchange-027"},{"speaker":"沢田副委員長","kind":"確認","question":"改めて確認をしたいんですけれども、先ほどもお話ありましたが、待機児童が品川区も今年多かったということで、こういった今回４施設ということを計画されて、今のところ３施設が開設されるということですけど、こういった社会福祉法人だとか、この株式会社だとかがやられている家庭的保育事業の、こういう会社とか団体に対して、区として来てくださいということをどのように働きかけが行われて。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、この事業所型家庭的保育事業は、やはり事業者はどちらかというとＮＰＯ法人ですとか、地元に密着した事業者が多いので、区内の中でこの３事業者もそうなんですけれども、既に１施設開設していて、やはり１施設だけですと、なかなか運営が保育士の状況も難しいので。","voiceIndex":99,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"さっき５月に入れなかった０歳から２歳の保護者に案内をするというふうに説明があったと思うんですけれども、そこの説明に関連してなんですが、５月に入れなかったという予想というのはどのくらい持っているのか。ちょっとそのあたりのことも含めて教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、こちらのほう、審査が終わりまして、実際に決定したときに周知するときに、その通知の中に保育ママのご案内を同封する予定です。","voiceIndex":101,"id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、やはり４月１０日に締め切って、今日は１５日ですから、一定の期間はあるわけなので、やはりこの文教委員会にそういう資料も持って参加していただきたいし、今わからなければ時間をとって後ででもいいからぜひ教えていただきたいと。わからないということなので、わからないで私は納得できないから、ぜひ教えていただきたいというふうに思っていますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"委員長が今、適宜適切にとおっしゃった、それはそのとおりだと思うんですけど、でも、時期がね、５月には委員会は予定されるんですか、文教委員会。ゴールデンウィークが終わった後ですよね。そういうつもりでおっしゃったということであれば、では具体的には今日は４月１５日ですから、３日とか今週中とか、そういうことで受けとめていいということですね。委員長のおっしゃった発言というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-031"}]},{"id":"topic-07","title":"(3)のその他","agenda":"(3)のその他","exchanges":[{"speaker":"南委員","kind":"意見","question":"とりわけオアシスルームの利用状況がどうなっているのか、ちょっと知らないですけれども、そういう一般の児童センター利用だけではなくて、オアシスルームもあるそういう施設なだけに、ちょっとその辺の日程についての設定が考慮がそこまでする余地もなく、こういうふうになったのかというあたりを聞きたいと思います。","respondent":"伊崎子育て支援課長","answer":"工事期間につきましては、やはり事業者との関係がありますので、この期間となっております。なるべく短期間に終わらせたいということで安全確保をするため、土日も含めてこの期間に工事を予定しております。","voiceIndex":111,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"２００８年の６月６日付で総務省が出した留意事項というのがあるのですけれども、１９項目を示しているんですけれども、業務要求水準書というのはそれに基づいてつくられるべきだというふうに思っているんですけれども、当然そういうふうになっているんだろうと思うんですけれども、あえて確認をさせていただきたいと思います。","respondent":"中元品川図書館長","answer":"最初のプロポーザルの方式ですが、現在、これはまだ調整中ですが、方向性としましては公募型プロポーザル方式ということで検討を進めております。","voiceIndex":114,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"品川区の場合、指定管理者を指定するのは９館ですよね。同一事業者にするのか、あるいは９館とも別々なのか。これから指定管理者になっていった際に、図書、資料等々の購入について、やはり地元の書店等も含めて対象に入れていっていただきたい。ですから、そういう視点をぜひ入れて募っていただきたいというふうに思っているんですけど、そのあたりの点について。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4820#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":31059,"voices":120}},{"id":"h26-20140415-5","meetingId":"h26-cm04","date":"2014年4月15日","dateIso":"2014-04-15","committee":"総務委員会","time":"午後１時００分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区長期基本計画の改訂および品川区総合実施計画（第３次）の策定","agenda":"品川区長期基本計画の改訂および品川区総合実施計画（第３次）の策定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで言えば、私はそれぞれの分野別に各常任委員会で３年間でこういうふうな方向でいくというところでのご報告をいただいて質疑ができるというようなことにぜひしていただきたいなというのが１点です。この本編のほうはどういうふうにしたら手に入るのか、そのことについてちょっとお聞かせください。","respondent":"柏原行財政改革担当課長","answer":"それぞれ個別の事業というところで入ってまいりますので、細かく内容をどこまで説明するかというのはあるかと思いますが、一旦はこちらの場でトータルの説明をさせていただいたところで、これをご紹介をしてこういう形で進めするです。","voiceIndex":19,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、ちなみに幾らぐらいするのかということを聞かせていただきたいのと、それからこの概要版は、ではちょっとみんなで勉強会をしたいとかということで何部というふうなことでいただきたいということであれば、その部数というのはいただけるということでいいんでしょうかということを、まずちょっとお聞かせください。","respondent":"柏原行財政改革担当課長","answer":"長期基本計画の冊子の部分ですが、ちょっと今皆さんお手元にはないかもしれませんが、こちらの本編のほうは１冊１,０００円ということになっております。ちなみに、実施計画のほうが５００円ということになってあります。","voiceIndex":21,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この品川区の総合実施計画のダイジェスト版なんですが、これは第３次ということでのダイジェスト版ということで、この見開き、１番最後の品川区総合実施計画の数字がいっぱい書いてあるのが第３次ということなんですけれども、この中身そのものも第３次ということで捉えるものなんでしょうか。それとも、この品川区長期基本計画の中身についての説明ということなんでしょうか。","respondent":"柏原行財政改革担当課長","answer":"委員おっしゃるとおりでございまして、こちらのほうが品川区総合実施計画、ダイジェスト版ですけれども、これが第３次の実施計画ということで、こちらに入っている内容が、その事業ですけれども、細かく書いてある項目そのものが実施計画事業ということになってございまして。","voiceIndex":23,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと中身のことで若干お聞きしたいんですけれども、例えばこの基本計画の概要版のところでも、１０ページの「未来を創る子育て・教育都市」というところで、待機児童対策の推進ということで書かれているんですけれども、区としては待機児童の解消という方針というのは持たないのかということが１点と、それからここのところでは、区立認可保育園の計画というのは全くないので。","respondent":"柏原行財政改革担当課長","answer":"この実施計画事業におきましては、この３年間、全くこのままいくということではなくて、考え方としては常に見直しという視点を入れながら、おそらく大きな見直しというのは１年か２年後、全体のローリングという形で入ってくると思いますけれども、個別の予算事業の中で毎年。","voiceIndex":25,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ありがとうございました。ちょっとすみません、今聞き漏らしてしまったんですけれども、待機児童は区の方針としては解消の方針ということでいいのか、待機児童解消というところで対策をとっていくという考え方でいいのかだけちょっと確認いたします。","respondent":"柏原行財政改革担当課長","answer":"言葉のあれになってしまいますけれども、品川区といたしましては、待機児童に対してはそういったことがなるべく出ないような形で対策を総合的にとっていきたい、そういう姿勢だと。","voiceIndex":27,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ待機児童は１人も出さないというところで、私は認可保育園に申し込んでいる子どもたちが全て入れるという形にしていただきたいと希望させていただきたいと思います。それと改めて、こういう３年間の計画というところで出されているわけですから、各常任委員会での報告をして、議論もできるような形でこういうことを今後ぜひご検討いただきたいということで要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"特に上の表１のほうで、都市像別計画事業費が平成２８年度が突出していると。今度、下のほうの財政収支のほうも、歳入について平成２８年度はまたぐっと出ている、伸びているということですが、これは何かそういう根拠があってあれなんでしょうか。一般の区民が見られたときに何かこれだけ急に伸びるということは何かあるのかなと思いますが、ちょっと中身を、どういうことなのか教えてください。","respondent":"柏原行財政改革担当課長","answer":"こちらのほうの事業費の推移です。平成２８年度につきましては、計画を進めていく中で、例えば再開発の事業、こういったところの建設ですね。","voiceIndex":30,"id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"もう一つなんですが、特別区税を含めて交付金、国・都支出金は事業費に対して伸びていくんだからそれはそれでいいと思いますが、こういうふうに第３次を見る限りにおいては、若干でこぼこはあるにせよ、伸びていくというような予測を立てているということで考えていていいんですね。","respondent":"柏原行財政改革担当課長","answer":"こういった財政のフレーム等々は予測を立てるときに、その先まで正確にどうかというのはありますけれども、現段階での状況を見ながら、緩やかな景気の回復基調にあるといったところを見込みながら、こういった予想を作成するといったものです。","voiceIndex":32,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"長期基本計画の改訂版、また総合実施計画ですけれども、先ほど販売をされているということで、１,０００円、５００円ということですけれども、これまで実際にどのぐらい、人気と言ったらおかしいですけれども、販売量があるのかないのかちょっとお伺いしたいのと、あと概要版とダイジェスト版ですけれども、これも数に限りはあるんでしょうけれども、お渡しできるということですが。","respondent":"柏原行財政改革担当課長","answer":"実施計画のダイジェスト版は３年分ということでございまして５,０００部つくってございまして、周知のやり方にもよりますけれども、半分ぐらいまでは何とか出ていくんではないかなと思ってあります。","voiceIndex":34,"id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"それと、ホームページでも公開をされているということで、私も見てみたんですけれども、ちょっと見方が悪かったのか、きのうから今日にかけて変わったのか、総合実施計画のほうが第２次しか出てこなかったので、多分もう改訂されているかと思いますけれども、この件は確認をしておいていただきたいのと、あとこちらについてもどのぐらいのアクセス数というのがあるのか、また。","respondent":"柏原行財政改革担当課長","answer":"実施計画のほうのホームページです。申しわけございません、実は長期計画のほうは既にホームページにアップしているのですが、今日、この委員会の報告をもってということで考えてございましたので、実は本日ホームページには更新させていただいてあります。","voiceIndex":36,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"今お伺いしようと思ったことをお話しいただいたんですけれども、今年度の長期基本計画ですとか実施計画とか、こういうことに関して、実際に区民からどのようなご意見、また問い合わせがあるものなのか、件数とか概要とか、もしわかればということで教えていただければと思います。","respondent":"柏原行財政改革担当課長","answer":"昨年は改訂を行ってございましたので、改訂に伴いましてご意見といった形は若干あったのですが、平常時といいますと実施計画が動いている中ではあまりこのことについては個別具体に何かということはございません。","voiceIndex":38,"id":"exchange-011"},{"speaker":"浅野委員","kind":"意見","question":"ずいぶん力を入れて、今回の長計の改訂と、また総合実施計画というのができていると思いますので、なるべく区民の方の目に触れるような形をこれからもつくっていっていただいて、また幅広くご意見をいただけるような、ある意味ではコミュニケーションがとれるような状況をつくっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはぜひしっかり実行していただきたいと思いますけれども、言葉の、実施をするにあたって、区長が「第３次の策定にあたって」、「改訂にあたって」という用語、ご挨拶をしていて、改訂にあたってのほうは非常に最後の部分で、「『輝く笑顔住み続けたいまちしながわ』の実現をめざして、長期基本計画を真摯に実行していくことが使命と考えておりますので。","respondent":"柏原行財政改革担当課長","answer":"続きまして、保育課です。こちらのほうは、名称変更、分割、新設等書いてありますが、端的に申しますと再編でございまして、平成２７年度に子ども・子育て支援新制度になってまいります。","voiceIndex":41,"id":"exchange-013"}]},{"id":"topic-02","title":"ないので、以上で本件を終了いたします。 ──────────────────────────────────────────── (2)","agenda":"ないので、以上で本件を終了いたします。 ──────────────────────────────────────────── (2)","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは兼務なんだけれども、課長で担当課長ができたんだったら、もう主査というのは、この推進担当は下に来るのが普通ではないのかなと思って見ていたんだけれども、あえて上に置いてあるという、何か意味合いがあるのかどうか、何でかなとちょっと思ったので、それを教えていただきたい。","respondent":"柏原行財政改革担当課長","answer":"ただ、直接的にこれで書かなくちゃいけない決まりではありませんので、今後こういった際にはちょっとわかりやすい表記を考えていきたいと思います。考え方としては、そういう表記の仕方をしています。","voiceIndex":45,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはそれでなんとなくわかったんですけれども、今言った担当課長も主査でという形でいいんだけれども、課長だった。だから、これ、待機児童のところもそうですよね。いいんですよ、僕は文化スポーツ振興課長がそれを一緒に統括するんだというのなら何となくわかるんだけれども、担当課長がいてもいいけれども統括するんですよという理解でいいのかどうか、そこら辺の理解の感じを教えてもらえるかな。","respondent":"柏原行財政改革担当課長、秋山情報システム課長","answer":"説明が少なくて申しわけありません。この委員会のもとに、条例改正や個人情報保護評価などの体制を検討する部会、それからシステム改修等を検討する部会の２部会で番号制度導入について実務的な検討を進めてまいる予定です。","voiceIndex":47,"id":"exchange-015"}]},{"id":"topic-03","title":"ますので、以上で本件を終了いたします。 ──────────────────────────────────────────── (3) 社会保障","agenda":"ますので、以上で本件を終了いたします。 ──────────────────────────────────────────── (3) 社会保障","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"ということは、何ていうんでしょう、変な話ですけれども、窓口業務が簡素化されるということは、そこの人員配置とかも変わってくるという考え方でいいんですかね。７ページの、ここら辺を教えていただきたいんですが、平成２７年に通知カードということで、これが全区民のところに番号が通知をされます。何ですかね、もう１回そこを詳しく。任意なのかどうなのかというのを教えてください。","respondent":"秋山情報システム課長","answer":"メリットということで、当然手間とか時間とかというのは、区民の方にある部分と同時に区役所の内部で、例えば今まで紙でやりとりしていたものをオンラインでやりとりすることになるということで、時間も節約できますし、コストもかからないということで。","voiceIndex":52,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問","question":"任意ということで、でも通知カードが来ればそこに個人番号が出ているということで、それをカード化するというか、ＩＣカードがまた申請をすれば送られてくる。３０％、４０％多分いっているのか、何％でしたっけね、今、この間お伺いしたときに。すみません、この個人番号カードを申請してもらわないと、何かそこにデメリットが発生するのかどうなのかとか、そういうあたりを教えてください。","respondent":"秋山情報システム課長","answer":"住基カードの発行数が低いというのはこちらも認識しておりまして、個人番号カードになれば便利な手続き、添付書類が簡素化できるとかというメリットがありますので、メリットのほうを打ち出して、個人番号カードの利用が。","voiceIndex":54,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"国が国がというよりか、ぜひ品川区の行政も、何ていうんでしょう、やっぱり全区民というのであれば、本当に高齢者の人たちはおそらく何が何だかわからない部分だと思いますので、いろいろなところでカードの周知徹底を図っていっていただきたいなと。できれば、普及率というか発行率が５０％超えるのが妥当なのかどうかわかりませんが、それを目指してやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民へのメリットというところで具体的にちょっとお聞きしたいんですけれども、手続が簡素化できるということなんですけれども、簡素化できる行政手続というのは、具体的な中身としてどれとどれがどういうふうに簡素化できるのかというところをちょっと１点教えていただきたいと思います。","respondent":"秋山情報システム課長","answer":"ただ、それだけでは当然足りませんので、平成２７年度以降、これから見積もりをしてというところですけれども、概算で、これは本当にあらあらですけれども、国が示しているものでたしか１億程度であったというふうに記憶しているんですけれども。","voiceIndex":57,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区１自治体で１億ぐらいかかるという感じだということなんでしょうか。だから、年金手帳の番号と、保険証の番号というのは同じという、そういうふうな仕組みになっていくのかどうか、この仕組みの大もとのところをちょっとお聞かせいただきたいと思います。","respondent":"秋山情報システム課長","answer":"１点目なんですけれども、医療に関してはこの番号法の中には触れられておりませんので、医療に関しては今後の検討ということでご理解いただければと思います。今厚生労働省において、医療関係についてはどうするかということは検討されているというふうに。","voiceIndex":59,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません、よくわからないんですけれども、年金番号は年金番号でそのままあって、新たに年金にこのマイナンバーがつくというわけではないんですか。マイナンバーで年金が管理されるということになるわけではないのでしょうか。国民健康保険法とかそういうふうなのも、保険料の徴収に関する事務、そういうようなところは書かれているんですけれども、保険証とか何かは全く関係ないんでしょうか。","respondent":"秋山情報システム課長","answer":"それは今までどおり番号を同じように管理をしています。ただ、個人番号をもって、先ほどの繰り返しになりますけれども、照会、提供を個々の番号について行うことまで可能になるという仕組みだけですので、一元的な管理ということにはならないと考えています。","voiceIndex":61,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３年後にまた見直して、民間のところにもいくということが検討されるということになると思いますけれども、そういうところになったときに、個人的なところの保険証の番号とか、そういうところでは保険料の納付状況と保険の給付状況とかなんかもわかるような仕組みにしようというような報道がされていたと思いますけれども。","respondent":"秋山情報システム課長","answer":"そういうことだというふうに私は理解しています。","voiceIndex":63,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すごくわかりにくいんですけれども。だって、その番号で管理してなければ、そのところに聞きにいったときにその番号の人の情報を教えてくださいと言ったって、その番号でそれが管理されていなかったら、情報をとることができないわけではないですか。","respondent":"秋山情報システム課長","answer":"その途中に、個人番号から変換をした符号というものを使ってやりとりをしますので、結果として情報は品川区には来るんですけれども、個人番号一つで全てが集められるというような状況にはなっていないというのが、ちょっとその辺の説明は私のほうではしょってしまったので。","voiceIndex":65,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"初めてのこういう仕組みの説明なので、ちょっと符号とかというふうなところはなかなかわかりにくいものなんですけれども、でもどちらにしても、間に符号ということが入るかもしれませんが、どちらにしても、そのものについては個人番号で管理をされる、そこのところはひもではつけられるというふうなことに、直接はならないかもしれないけれども、その符号を通して番号は全部そういうふうなことで。","respondent":"秋山情報システム課長","answer":"特定個人情報ファイルですけれども、ちょっと説明は省いてしまって申しわけないんですが、個人情報というものに番号が加わったもの、１２桁の個人番号のことなんですけれども、それを特定個人情報というふうに番号法では規定しています。","voiceIndex":67,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このマイナンバー制度というところでは、すでに世界でも実施に移しているところで、さまざまな問題が出ているということが報道されているわけですけれども、例えばアメリカでは個人番号を盗んで給付金をだまし取るなどの成りすまし犯罪が横行していて、損害額が５,０００億円以上を超えていて、分野別の番号に転換する雰囲気も出ているという報道ですとか。","respondent":"秋山情報システム課長","answer":"利用範囲については、番号法で限定をされていますので、いろいろなアメリカとか韓国で広く使われているようなことにはならないということであります。","voiceIndex":69,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"アメリカや韓国は顔写真ついてないんでしょうか。今後品川区の庁舎内の体制というところでは、いろいろまた先ほどの組織改正のところにも出てきましたけれども、職員の体制というのはどういう体制でこれを整備していくのか、またこのシステムづくりをどこかに委託をするとかということもあるのか、その点についてもお聞かせください。","respondent":"秋山情報システム課長","answer":"アメリカの件でありますけれども、顔写真がついているようにすればいいのかですけれども、それは私ではちょっとお答えができませんので、もう一度繰り返しになりますけれども、番号のみでの本人確認は番号法ではできないという規定をしております。","voiceIndex":71,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう中での今回の、本当に国会の中でも十分な審議がされない中で法律が通って、施行されていくというふうな状況になるわけですから、そこのところも踏まえた対応をしていただきたいということと、あとここの中でずっといろいろ議事録を見るにつけ、社会保障のどれだけ保険料などの社会保険の負担をしているか、その負担の能力とそれから給付というようなところをつなげて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"それと、あと本人確認。でも、顔写真でその人が間違いなく本人かどうかという本人確認、本人として確定できるというところまで突き進めると、相当難しい問題が起きるのかなというふうに、ちょっと非常に心配なんですね。","respondent":"秋山情報システム課長","answer":"有効期限ですけれども、一応１０年を今想定していますので、１０年たったら写真が入れかわる。若年者については、変化が激しいだろうということで５年という有効期限をつくっているというふうにしておりますので、可能かと考えています。","voiceIndex":74,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"もうご存じのとおり、高齢者がますます増えてくるわけで、さまざまな障害、またご病気の方もいるんですが、区役所に来てくれというのはどうなのかなということもあるんです。今回のマイナンバー制度に対する不安と、さらにそこまで出向かなきゃいけないということが、かえってマイナンバーに移行するのに人を遠のかせてるのかなというふうなことも思いますが、その点についてどういうふうにお考えですか。","respondent":"秋山情報システム課長","answer":"大まかな今私が先ほどご説明したような流れで交付をするという形になっておりますので、例えば交付場所についても区役所でないといけないのか、それから出向いてというのができるのかできないのかという形についてはまだこれからの検討かなと考えていますので。","voiceIndex":76,"id":"exchange-029"}]},{"id":"topic-04","title":"土木工事等の契約に係る前払金対象の拡大","agenda":"土木工事等の契約に係る前払金対象の拡大","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"こういうふうに業者を助ける前払金制度というのはいいと思いますが、よくよく思いますが、ほかの民間企業ってこういうことはないんですね、ほとんどね。区のほうでこういうふうに前払金対象拡大というのは本当にうらやましがる民間企業も多々、たくさん、ほとんどがあると思いますが、その辺についてバランス的にどのようにお考えでしょうか。見解だけお聞かせください。","respondent":"立川経理課長","answer":"小規模事業者にとっては、やはり工事完了後でないと契約金額、代金が支払われないというのはかなり負担が重いというふうに考えているところです。","voiceIndex":85,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"すみません、ちょっと足りなかったんですが、今の課長のご答弁、よくわかるんですが、設計とか調査、測量に関しては、資材も何も要らないわけではないですか。どうですか。","respondent":"立川経理課長","answer":"昨今、労務単価等につきましても単価改定等をいたしまして、事業者としましては、資金繰り等がやはり前払金により安定するといった、そういったところに行政としては配慮していかなければいけないと考えているところです。","voiceIndex":87,"id":"exchange-031"}]},{"id":"topic-05","title":"品川区施工能力等審査型総合評価方式の評価項目等の変更","agenda":"品川区施工能力等審査型総合評価方式の評価項目等の変更","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと意見だけ言わせていただきたいと思います。これをやっていくんでしょうが、今後の入札状況も踏まえながら、見ながらまた次に質問させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"大きな、ざっくりでいいので、そういうのは増えるんですかね、過去の実績をとると。","respondent":"立川経理課長","answer":"価格点につきましては、最低制限価格というのを現在区では１０分の８から３分の２の範囲内で実施していますが、理論値でいけば価格点の最高点というのが２０点ということになります。これは理論値であります。","voiceIndex":94,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1980#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":40013,"voices":101}},{"id":"h26-20140416-14","meetingId":"h26-cm04","date":"2014年4月16日","dateIso":"2014-04-16","committee":"行財政改革特別委員会","time":"午後１時００分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"受益者負担に関すること","agenda":"受益者負担に関すること","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"聞き方が難しいのですが、それぞれ聞いていくと大変な量になってしまうので幾つか例としてというか、選んだ形で伺いたいと思います。免除の団体というか対象、行事は、主にどのようなものが一番多い、あるいは２番目に多い、３番目に多い、主な例として挙げていただくとイメージがわくかなと思うので、まずそれを１点、伺わせてください。","respondent":"安藤文化スポーツ振興課長","answer":"ここで免除については、区が利用するときは免除となります。それとあと、公益財団法人のスポーツ協会ならびに同協会に加盟する認定団体が、区民を対象とし、かつ、区長が必要と認めた事業を実施するために利用するときというものが全額免除となります。","voiceIndex":14,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"ありがとうございました。もちろんお１人で使うわけではないケースがほとんどですから、仲間内で、あるいはそのための会費という位置付けがほとんどだと思う中で、免除というのは逆になかなか理解が難しくなっているのかなという思いがあります。これは、今の各施設ではなくて、地域センターもひっくるめて全体として見直しが必要ではないかというのが１点です。そちらをお願いします。","respondent":"柏原行財政改革担当課長","answer":"前回の本委員会でも議論になった部分ではございまして、今、例示で出していただいた部分で、ある団体はこの施設を使うときは免除なのだけれども、うちの施設は減額だとかいう、そういうわかりづらさとかというのはあって、区民の方からすると。","voiceIndex":16,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"１回出していただくということも、施設によってはあると思うんですね。その中で、この料金収入というのは、入ったものが全部一緒くたにならずに、何か目的を持った基金的なものだとか、さっき言った区の利用料がそういうふうにプールされれば、かなり施設の修繕だとか、利用を変えるときに役立つのではないかと思ったので、ちょっと関連するこの２点、考え方をお知らせいただければと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、考え方としては、そういったニーズに合わせて改修していくというのは、当然あるべきものだと思いますので、その分析の部分と合わせながらの検討だろうと考えています。","voiceIndex":18,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"意見","question":"特に各施設に共通していくというのは、限られた施設をより効率よく、あるいは有効にするという中で、利用者のモラルとか意識も並行すべきだと思うんです。そのときに料金というのは大きな接点というか、きっかけになると思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"視覚障害者の方々がこういう施設を利用していただける、利用率を引き上げるために、やはりそういう障害を持っておられる方でも普通の健常者と同じように利用していただける設備・施設であってほしいと思うので、その辺の視覚障害者、聴覚障害者、あと身体障害者の方々はバリアフリーでエレベーターとか、そういう段差をなくすとかあると思うんですけれども。","respondent":"安藤文化スポーツ振興課長、久保田地域活動課長、米田商業・観光課長、白鳥高齢者いきがい課長、伊崎子育て支援課長","answer":"昨年末にオープンしましたスクエア荏原のホールにつきましても、磁気ループを設置しています。そうやって障害者の方等がお見えになったときは、開庁時間であれば職員が対応するなり、ご案内をしたりして、できるだけそういった配慮はしています。中小企業センターですけれども、いわゆる身体障害者の方への配慮、スロープですとか多目的トイレというものについては整備しています。","voiceIndex":21,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"施設改善には当然お金はかかりますけれども、障害者だから心身障害者福祉会館を使えばいいのだというすごく狭い考え方ではなくて、バリアフリーということを本当に施設設備の面でも貫くという立場で、やはり見ていく必要があるのではないかと思うんですけれども、総論的にちょっとその辺についてはどう捉えているか、あるいは計画をどういうふうに持とうとしているのか。","respondent":"柏原行財政改革担当課長","answer":"ですので、例えばバリアフリーの観点であるとか、それからいろいろな障害をお持ちの方に対する対応等々を含めて、それがすぐその場で全部できるかどうかはというのは、いろいろ時期的なものとか予算的なもの、それはもろもろありますので。","voiceIndex":27,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"私の住んでいる八潮で、聴覚障害者の方がいろいろな活動をしていきたいというときに、あるところを探して行くわけですけれども、行くこと自体がなかなか時間もかかり大変な状況なので、八潮の中でそういう活動ができたらと思うのは当然であり、したがって品川区の全施設の中で、こことここはあるけれども、ほかはないよというのではなくて、地域的にやはり点在させていくという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-007"},{"speaker":"須藤委員","kind":"意見","question":"この区の施設は全部、耐震化工事とか、そういうのは済んでいるのかどうかということと、それから、改築をしようと考える施設があるのか、ないのかが１点目。そうすると、これらの有料施設のあり方というのは、本格的にどうあるべきだろうと考えていく原点が、ここでこの数字で見えてきているのではないかなと思うんですけれども、そのあたりについて、お考えをお聞かせください。この３点。","respondent":"柏原行財政改革担当課長、白鳥高齢者いきがい課長","answer":"その減額とか免除の割合が施設ごとに違うというところも、恐らくなんですけれども、減額・免除の対象となっている団体であるとか、そういったところの違いであるとか、そういった利用率のところから。シルバーセンターの利用に関する区民、区民以外というご質問ですけれども、基本的には区民のみのご利用ということで、ただ一部、講師をお務めになる、いわゆる健康体操ですとか、あるいは趣味等の中で。","voiceIndex":30,"id":"exchange-008"},{"speaker":"須藤委員","kind":"提案","question":"やはり区民の、これからの高齢化社会になるとか、あるいはコミュニケーションをうまくとっていこうというときに、それをどうしたら逆に使えるような仕組みになってくるのかという、それも公平な目で見ていってやろうという仕組みづくりが考えられるのだろうと思うので、そのあたりを今後、僕らもしっかりこの数値を見ながら提案していきたいと思うんですけれども、考えておいていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"これまでの質問と部分的に似ているところもあるのですが、幾つかお伺いしたいと思います。昨秋で７万５,０００人でしたっけ。区民の４人に１人が高齢者という時代が近づきつつある中で、高齢者の団体をここまで広範に免除ということにしていいのかどうかについて、そろそろ検討する必要があるのではないかと思うんですが、この辺についての区のお考えをお聞かせください。とりあえず、以上です。","respondent":"柏原行財政改革担当課長、安藤文化スポーツ振興課長","answer":"３点のご質問の部分で、全体にかかるところで、私のほうからお答えします。委員がおっしゃった使いやすさの部分等、このデータから読み取ってということで、そういうことがあると思います。そこでスポーツ大会始め、いろいろな大会の催しなんかに向けての準備とか作業等も、この会議室を利用しているわけですけれども、全体的には体育館の会議室ということ自体が。","voiceIndex":34,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"それぞれありがとうございました。先ほどおっしゃったような準備や作業に利用しているというのは、これは利用率に入っていないんでしょうか。料金として発生するかどうかはともかく、作業に使おうが事務に使おうが、それは利用率として、きちんと手続を踏んだ上で使うべきではないかと思うんですけれども、そこはどのようにお考えでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"それと、目的外利用ですけれども、区立体育館も区民の体育、スポーツおよびレクリエーションの振興を図るという目的の区立施設です。そのために、それについて利用するという形で、スポーツ以外のお話だとか、そうしたものはうちは受け付けてはございません。","voiceIndex":37,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"すみません。２つともちょっとかみ合わなかったかなと思うんですけれども、１つ目に聞いたのは、目的がスポーツやレク団体というのはわかるんです。施設の有効利用の観点からという形で、目的外利用をやっているわけですよね。ただ、それは利用率として、ここがこの時間借りて使いましたという形で、きちんと手続を踏んで使って、利用率としても挙げてくるべきだと考えるのですが、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"１点目の目的外利用ですけれども、まず、私もスポーツ協会に何年かいました。そのときにも、だからその目的外としての利用というものは、区民の方から貸していただきたいというのは皆無に等しい状況です。ですから、目的施設として目的のために利用していると。","voiceIndex":39,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうすると、目的外利用は排除しているわけではないから、要望があれば目的外でも使えますよというご答弁という意味でよろしいでしょうか。必ず料金を発生させろということではないですし、別にほかの施設と同じように運営してもいいのではないかというか、区の施設ですから、したほうがいいのではないかと思うんですが、なぜ体育館だけそういうイレギュラーな運用になっているのかがちょっとまだわからない。","respondent":"安藤文化スポーツ振興課長","answer":"利用率ですけれども、件数について、これだけの件数はありますけれども、そのほかに私どものほうで空いているところに、それは使っている形で先ほど説明させていただきましたけれども、次の方が来て、連盟の方が来て。","voiceIndex":41,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"さらなる検討をお願いしたいと思います。すみません。それとあと一点お伺いしたいのですけれども、シルバーセンターを使っている方から、そろそろ畳や座敷だけでは使いにくいということがよく聞かれます。部分的には机と椅子という形になっているところもあると思いますけれども、今、座敷だけというか、畳の部屋だけのシルバーセンターというのは幾つぐらいあるんでしょうか。わかりますでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"ただ、今のその利用者側からの声からしますと、以前委員会のほうでご質問がございました机ですとか椅子、これは畳敷きですとやはりなかなか非常に骨が折れるといいますか、足腰が大変つらい思いをしているというご意見を頂戴いたしまして、昨年度から。","voiceIndex":43,"id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"高齢者団体の方が、畳の部屋しかないからシルバーセンターが使えないというのは何だか本末転倒な感じがしますので、いろいろな声があると思いますけれども、大きな改装だけではなくて、ちょっと高さのある机や椅子を入れるだけでも大分改善はあると思いますので、その辺はぜひご検討くださればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"ちょっと本旨からそれてしまうのかもしれないんですけれども、八潮の地域センターというか、３ページの資料なんですが、八潮というのは区民集会所と文化センター機能と児童館が一緒になっているんですね。これがちょっとどうなのかなと思うんですけれども、そのあたりのカウントの仕方がどうなっているのか、やはりちょっと性格的に分けたほうがいいのかなと思います。","respondent":"久保田地域活動課長","answer":"ですから、そういう形で表現していますので、夜間については貸出し等を行っていますから、貸出しの数はカウントされているということです。","voiceIndex":46,"id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"私はそういうふうに読んだんですね。それで、よくよく考えてみたら、スポーツ室・遊戯室・談話室は児童センターの管理する施設ですから、土曜日と日曜日の昼間、夜間は貸出しているということは、今、改めて確認したわけですけれども、これは施設的には区民の利用がないからゼロではなくて、開放しているからゼロであって、意味が違うのではないかと思うんですけれども。","respondent":"久保田地域活動課長","answer":"〔「これは除いてあるの」と呼ぶ者あり〕はい。除いてありますから。〔「その説明がなかったから、ごめんなさい」と呼ぶ者あり〕はい。ということです。〔「わかりました。","voiceIndex":50,"id":"exchange-017"},{"speaker":"井上副委員長","kind":"質問","question":"それで、免除の見直しとかの必要性はあると思っているんですけれども、ここの免除の考え方について、これは一律この割合だけで論じるのではなくて、近いところにシルバーセンターがあったりとか、目的使用する会場があったりとか、あるいは町会会館がなくて地域で使っていたりとか、ここを見直すに当たって、そういうところの分析も含めてやらなければいけないと思うんですけれども。","respondent":"柏原行財政改革担当課長","answer":"今、お話しいただいたとおり、例えば先ほど申し上げたように、区民集会所によっても、荏原地区とほかの地区が違ったりとか、その地域の部分であるとか、それからその立地の条件であるとか、ほかの近くにある施設だとか、それから地域の方の団体の状況だとか。","voiceIndex":52,"id":"exchange-018"},{"speaker":"井上副委員長","kind":"意見","question":"割合だけではなく、そういった分析を含めて、ぜひ見直しの参考にしていただくようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-019"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"それを踏まえて質問をさせていただきたいと思います。その前文にありますけれども、試行を平成２２年からということで、４年間やってこられたと思うんですけれども、建築等に関してはなかったと思うんですが、この評価というか、４年間試行をされた評価というのはどのようなことをお考えになっているのか、お聞かせください。","respondent":"立川経理課長","answer":"これまで４年間に、件数といたしましては１件から２件という少ない件数で実施してまいりました。","voiceIndex":60,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"確認","question":"本格実施ということで、さまざまな議論をする中で、いろいろなやり方がありますよということを理事者の方からも教えていただきましたし、また我々のほうからもご紹介をさせていただいたりもしました。これは、もういわゆる建築、土木、設備といった、これは全ての分野にわたるのか、それについての確認をお願いいたします。","respondent":"立川経理課長","answer":"平成２４年度については、２,５００万円以上の工事につきましては５８件、６１億円余、平成２５年度につきましては４１件、５２億円余です。平成２６年度につきましても同等数を見込んでいるところです。２,５００万円というのは建築、土木、設備、全て含んだものです。","voiceIndex":62,"id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど工事成績の評価についていろいろあったんですけれども、これを今から始めるということですから、やはりこれは導入することによって期待をされている事業者はたくさんいるわけで、やはりその中で公正な評価を求めているというところがあると思うんですけれども、いきなり５０件というところなんですが、そこについてのお考えをお聞かせいただければ。","respondent":"立川経理課長","answer":"先ほどお話ししたのは、２,５００万円以上の工事が何件くらい見込まれるかということで、５０件前後かなというところをお話ししました。","voiceIndex":64,"id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。ということは、全てに適用ということではなくて、１件ごとにいろいろ検討しながらということになるわけですか。そこのところをちょっと確認したかったんですけれども、わかりました。項目のところでちょっと確認させてください。実際、私もそういう企業を知っているんですけれども、そういうところで点が入らないということなのか、実績というのは何を指すのか、教えていただきたいと思います。","respondent":"立川経理課長","answer":"現在考えている実績ですが、こちらにつきましては、いわゆる災害時、またゲリラ豪雨や台風のときに災害対策本部ができます。そうした中で、災害対策本部の要請に従って対応していただいたというところを、実績として評価していこうと現在は考えてあります。","voiceIndex":66,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"確認","question":"もしかすると所管が異なってしまうので、そこの細かいところが今はわからないかもしれないんですけれども、私が知っている企業でも、締結はされているけれども一度も区からお呼びがかかったことがないという事業者もいらっしゃるので、そういうところは実績を積みたくても積めないのではないかなというところがあるので、それについてはちょっとまた防災課のほうとも私も確認したいと思います。","respondent":"立川経理課長","answer":"何点にするかというところは非常に大切な部分だと考えましたので、それで、昨年、他区の調査を実施しまして、導入区が千代田区を除いて試行または本格実施です。","voiceIndex":68,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点目の営業拠点の所在について、細かくなってしまうんですが、本店所在が２点で、区内に支店等所在は１点ということで、これも再三議論の中にあったんですけれども、支店の扱いについてなんですが、いわゆる大規模な大型工事を品川区でとるために、直前に品川区に入ってきて、マンションの１室とかアパートの１室に支店を置いて看板だけぶら下げて、電話は転送しているという。","respondent":"立川経理課長","answer":"連絡は電話、ファクス等ですので、当然連絡がとれない、全て転送されるというようなところにつきましては、品川区としては、そういった場合は区内業者として認定しないという扱いをこれまでも実施してまいりました。","voiceIndex":70,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"確認","question":"わかりました。経理課のほうで確認をされていらっしゃるということなんですけれども、例えば他区の場合、江東区などはこの総合評価方式の中で、事業の継続年数、本店とか支店の所在の年数によって点数を変えたりしているんですね。それは区によっていろいろ対応も違うと思うんですけれども、品川区は、そこはしっかりと実体があるのかどうかという調査をやられているということで、よろしいでしょうか。","respondent":"立川経理課長","answer":"ですから、現在のところはそういったことで、いわゆるそういったペーパーの支店、営業所については排除していくことになると考えております。","voiceIndex":72,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"は本当にこれをやっていただいて、公平性、中立性、またそういったものは入札、契約というものにはもちろん求められますし、それと、やはりこの中にも前文にうたってあるように、地域における工事事業者の健全な育成、そのためにはやはりバランスが非常に難しいと思うんですけれども、そのために総合評価方式が骨抜きになってしまっては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-027"},{"speaker":"原委員","kind":"意見","question":"私のほうも、全体的には今、あくつ委員のほうからお話があったように、試みていくという、また品川区独特のものを出していかれるというのは非常にいいことだという認識でして、まず、あくつ委員と重ならないようにいきたいんですが、２２点という何とも表現がしにくい数字を出した、その辺のところについて、そこをご説明いただければと思います。","respondent":"立川経理課長","answer":"２０点に対して、その他で２２点ということになりますので、これまでの価格点と施工能力等のバランスというのが１８対１８ということで、５０％ずつという配点ですので、今回の改定で、理論上は技術と地域貢献の割合を多くしたというものです。","voiceIndex":75,"id":"exchange-028"},{"speaker":"原委員","kind":"意見","question":"概略説明で理解をしたつもりではおりました。ただ、品川区の場合にはこれは外していく。外していくという表現がよくないのかな。ＩＳＯ基準とはちょっと違って、これもまた品川区独自のもので考えていくというような意見が出ているので、そうすると例えば横の連携的なものというのは全体的にもし考えがあれば、これからだよというのであれば、それはそれで結構なんですけれども、もしお考えがあれば。","respondent":"立川経理課長","answer":"所管が違うので、いわゆる契約における考え方ですが、品川区においても、内部的な環境対策とかその辺については、一事業者として当然これからも実施していく考えであるということは聞いているところですが、そうした中で。","voiceIndex":77,"id":"exchange-029"},{"speaker":"原委員","kind":"質問","question":"というのは、やはりなかなか仕事がとれない区内業者にとってみれば、ふざけるなというような話も出てこようかとは思うんですけれども、私も今、現実に所在がなければだめなのかどうなのかというのは、これは非常に、以前は私自体はなければだめだと、お化けはだめだよという感覚でいたのですが、最近はちょっとクエスチョンマークというか、どうかなという思いがあるものですから、その辺についてももう一回。","respondent":"立川経理課長","answer":"そういった中で、品質と価格のバランスの中に地域への貢献という視点を入れるということで、今回の総合評価方式を実施していくわけですから、実態として、品川区のある土地のところで活動してもらうということが大切なことだと考えているところです。","voiceIndex":79,"id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、逆を言えば品川区の考え方、あまりにもいろいろなところで現地調査とかをやれば、これは今度は行政の権限の力で抑えるような形にもなってしまいますし、じゃあ、今度ゆるゆるで何もやらなければ、実体がないのに、本当に登記簿上だけで、それこそ今はもう当然にここの地下１階に行かなくても、ほかの業者は全部ネットでつながっているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"何点かお伺いしたいと思います。１つ目、先ほどの質疑の中にもありましたけれども、２,５００万円以上の工事が５０件前後ということで、そのうちどれに適用するかというのは協議の上ということだったんですが、その考え方、何にはこの総合評価方式を適用して、何には適用しないという、何か基本的な考え方があるんでしょうか。とりあえずその２点でお聞かせください。","respondent":"立川経理課長","answer":"適用の考え方ですけれども、土木、建築、設備等々、各種類ございまして、それで今の考え方なんですけれども、昨年から工事実績の評価を実施して、工事成績評定を実施しておりますので、出そろうまでにはいかないんですけれども、その辺がある程度出ないと。","voiceIndex":85,"id":"exchange-032"},{"speaker":"あべ委員","kind":"確認","question":"そうすると、１つ目のほうの協議の上というのは、その工事ごとにどのような業者が集まって参入してきているかということを見ながら、不利なところが出ないような場合には適用するというようなイメージでよいのでしょうか、確認です。多分、これのどれかという話だと今でもハードルが低いですし、世の中が変わっていけば、またどんどんレベルを上げていかなくてはいけない項目だと思いますので、確認です。","respondent":"立川経理課長","answer":"１点目の、法律が改正されるごとにこちらも連動していくのかですが、こちらは現在、当然法律に従ってハードルというのは上がっていくと考えています。","voiceIndex":87,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"確認","question":"この地域貢献等評価ができたというのはすばらしいことです。この評価も十分わかりました。その上で、苦情審査の関係が出ていると思うんですけれども、そこら辺はどういうふうに考えているのか、その１点だけもう一回確認したいと思います。","respondent":"立川経理課長","answer":"苦情につきましては、実際に工事成績評定において、苦情の申し入れにつきましては取り扱いが決めてありますので、その中でしっかり対応していきたいです。","voiceIndex":89,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう一度すみませんけれども、外部委員の加入とか第三者評価委員会という話も出ていたと思うんですけれども、その辺は検討状況だけで進めていくんですか。","respondent":"立川経理課長","answer":"外部委員の関係ですが、こちらのほうにつきましては、もし苦情があった場合には、苦情審査委員会というのを副区長をトップに実施していくとなっているところです。必要に応じて専門の臨時委員ということで、外部の方をお招きするということを現在考えているところです。","voiceIndex":91,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"しかも、これから区のほうが、ここの委員会として、どういうふうにこれが次期のときに持っていかれるかは議会運営委員会の議論なんですけれども、やはりもう少し深めた議論ができ得なかったと私は印象を持っているんですが、契約の中の公契約についても文言としては出ていたので、ちょっと一言二言、公契約についても調査をしたということでもいいから、載せておけないのかなとちょっと思ったんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"今回はまとめ、提言ということなので、そこには持ち込まなかったというのはそういうことで、議長への報告には載せていったということで確認をしておきたいと思ったのですけれども、そういうことでいいんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"意見","question":"行財政改革特別委員会の活動現況についてがある。その中に出ているので、今、議題になっている部分の契約のあり方に関することは、これで十分まとまっているのではないかと私は判断して、これに賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-038"}]},{"id":"topic-03","title":"(1)の御殿山小学校西側敷地の活用計画（案）","agenda":"(1)の御殿山小学校西側敷地の活用計画（案）","exchanges":[{"speaker":"南委員","kind":"提案","question":"２点目は、文化教育施設等と介護老人保健施設ができるということは、各会派挙げて歓迎できるものだと考えていますけれども、１万m2くらいの建物が可能だという中で、1)と2)については４,０００m2から５,０００m2ぐらいの占有になってくるんだと思うので、５,０００m2ちょっと超えるぐらいの中身は事業者提案に基づく検討というのは。","respondent":"柏原行財政改革担当課長","answer":"説明のほうがちょっとはしょるような形で申しわけございませんでした。今回の活用計画案ということでお出ししましたのは、前回は方向性ということでお示しをしましたので、今回は区の考え方として、案ということでお示しをさせていただいたというところが大きなところです。","voiceIndex":111,"id":"exchange-039"},{"speaker":"南委員","kind":"提案","question":"ですから、そこはまだ時間があるところなので、もう一度検討するべきだと思っていますので、その点について、住民サービスの関係で見解を伺いたいと思います。そのプロポーザルの概要的なこと、こういう施設とこういう施設とこういう施設を入れたいんだという区としての思いがあって、プロポーザルの提案になっていくんだろうと思うので、そのあたりのことをちょっと伺っておきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"大崎図書館の部分です。大崎図書館につきましては、委員から今ご案内いただきまして、区の中でも利用率はかなり高いほうだと私のほうも認識はしています。","voiceIndex":113,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"ありがとうございました。検討にはそこの視点をやはり譲らないでいただきたいと思います。それはそれぞれ違うけれども、私はそういうように思うんです。ですから、そういうことをしっかり見ていただいて、残すからいいんだということにはしないでいただきたい。だから、そういう点でもやはり残すべきだと思うので、その辺について十分これから検討していただきたいと思います。この２点です。","respondent":"桑村企画部長","answer":"もう一つは、この北品川五丁目第１地区のところで、やはり何か図書館施設をつくりたいということもありましたので、もう一つは施設全体の有効活用というのがあって、もちろん図書館をたくさんつくっていくという一つの考え方はあろうかと思いますけれども。","voiceIndex":115,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、土地の取得費がかからないけれども、その後の運営がずっと恒常的にかかっていくという点はありますけれども、そういう点から見たら、土地に対する負担がなく、新たな事業が展開できるということですから、効率的にというのはいつの時代でもどんな問題でも必要だとは思うけれども、あまりにもお金を使わないという角度でのこの計画というのは、やはり将来的に見て。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"公募していく中で、これから委員会のほうにまたいろいろな話も出てくると思いますけれども、次の委員会あたりには基本的な考え方が出てくるんでしょうかというのが１点。それからもう一つ、活用としてこの土地も当然一緒に絡んでくるんだけれども、賃貸していく中でどのぐらいの金額になってくるか、それも次の時点ぐらいに出てくるのか、その２点だけ教えていただきたい。","respondent":"柏原行財政改革担当課長","answer":"賃料等々につきましても、現在ちょっと精査していますので、そういったところも含めた形で、ご報告できるようにと考えています。","voiceIndex":118,"id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"確認","question":"わかりました。公募に関してなんですけれども、普通こういう施設だと厚生委員会との絡みがありますね。今度の件に関しては、行財政改革特別委員会の判断でいいんですか。それともやはり厚生委員会と、その辺の絡みだけは確認を。","respondent":"桑村企画部長","answer":"これはもちろん議会側とご相談しなくてはいけないです。今の区のほうの考えでは、次の委員会では、これは厚生委員会と文教委員会にも関係してまいりますので、調整がつけば３つの委員会でかけさせていただきたいと思って、ご意見をいただきたいと考えているところです。","voiceIndex":120,"id":"exchange-044"},{"speaker":"あべ委員","kind":"提案","question":"先ほど、この残った部分についても、つまり図書館と介護老人保健施設以外のところでも、何らか公益性のある施設が提案されるのではないかというお話がありました。もし、何かもう少しでも踏み込んで考えていらっしゃることがあれば、教えていただきたいというのが、まず１点です。そういったものも、ぜひ活用の計画を検討する中では考慮に入れていただきたいと思うんですけれども、いかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"集会ができるような施設といいますか、区民の方が使える施設があるといいというご意見も伺っているのは事実でございまして、この施設でできるかどうかというのはちょっとありますけれども、周りの施設も含めて、そういったことにも考慮はしていきたいと考えています。","voiceIndex":122,"id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。前にも言いましたけれども、やはりこの御殿山小学校の敷地というのは、そもそも地域の子どもために地域の人たちが志を出し合ってつくったところですので、それが今は区の土地ということになっておりますけれども、ぜひまた住民の人たちがいろいろ広く使えるところにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-046"},{"speaker":"あくつ委員","kind":"提案","question":"１点だけ確認なんですけれども、公募のやり方について、一番最初にこのご報告を聞いたときに伺ったと思うんですけれども、まず先ほどあった医療法人もしくは社会福祉法人、およびそれに準ずる事業者というところを想定しているということですけれども、あと余剰部分については一定の公益性があるものが考えられるというお話でしたが、別に例えばその医療法人なり社会福祉法人が。","respondent":"柏原行財政改革担当課長","answer":"いろいろ考え方はできるとは思うんですけれども、あまりその権利関係を複雑にしたくないというところが片方ですので、今、公募条件は最終的に精査をしていますけれども、余りそういった形で転貸であるとか、そういったところは今のところは想定はしていないということです。","voiceIndex":125,"id":"exchange-047"},{"speaker":"あくつ委員","kind":"確認","question":"このぐらいのところを借りて地代を払うとなると、それなりの経済力があるところが母体になってくると思うので、例えば医療法人であれば病院を建てるとか、そういったことも考えられると思うんですけれども、そういった意味で、もう何か先ほど一定の方向性みたいな形でもいろいろご意見出されましたけれども、公募というのはそういうことなのかどうか。","respondent":"柏原行財政改革担当課長","answer":"ほかの事業者と組むかどうかというところだと思うんですけれども、そこについては、まだ今、精査をしているところではありますけれども、一定程度あまり複雑なことにしたくないというのがありますので、どこまで絞りを入れるかというのは今後のあれで、ただ。","voiceIndex":127,"id":"exchange-048"},{"speaker":"あくつ委員","kind":"確認","question":"確認できました。一定方向性があるということは確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-049"},{"speaker":"井上副委員長","kind":"質問・要望","question":"この定期借地の契約で成功事例というか、品川区が検討するにあたって参考にしているようなところの事例があれば、紹介をしていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"そういったところも参考にしながら、今回の公募の要件も詰めていきたいと考えています。","voiceIndex":130,"id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5964#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":51382,"voices":137}},{"id":"h26-20140417-17","meetingId":"h26-cm04","date":"2014年4月17日","dateIso":"2014-04-17","committee":"震災対策特別委員会","time":"午後１時００分～午後２時５４分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"国道１５号線徒歩帰宅者支援対策の実施","agenda":"国道１５号線徒歩帰宅者支援対策の実施","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"国道１５号線徒歩帰宅者支援対策の実施ですけれども、まずこの計画はどこの計画に位置づけられているのか、上位計画を伺いたいと思います。そうなると、初めの３日間はどうなるのか、それともかかわって４日目以降という意味合いというのはどういうことなのか、そこも伺いたいと思います。この「震災発生」というのがどういう想定なのか伺いたいと思います。","respondent":"鈴木防災課長","answer":"２点目の予防対策、応急・復旧対策、それぞれのどの時点に対応するかですが、まず予防の時点で考えますと、協議会を設置して事前の取り組みをする部分が、まさに予防の対策です。それから検討した中身で実際に災害時に対応するというのが、応急の部分になります。","voiceIndex":18,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"ある意味これからつくろうというところではありますけれども、いわば３・１１では東京はその日の夜が一番ピークになって、１２時間がとても大変だったわけですけれども、どこを捉えてやろうとしているのかよくわからなかったので、初めの３日間、そして４日目以降、ピークがいつなのか、モデル実施の対象としているのがどういうスキームなのか、そこをご説明いただきたいと思います。","respondent":"鈴木防災課長","answer":"そういう意味では、一番多いときに対応できる体制を組んでおけば、その前の３日間のまだ少ないとき、またスムーズに通過して徒歩帰宅者が減ってきたときにも十分対応できるという意味で、想定とした前提をこの一番多くなるピークという言い方をしたものであります。","voiceIndex":20,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"現状の例えばオフィスビルでの取り組みの状況を把握していく、また鉄道事業者ですよね、１５両編成でも人数としてはたくさん乗っていらっしゃいますので、それぞれの最寄りの駅なのか、ＪＲが責任を持って対策すべきだと思いますけれども、そういう鉄道事業者での対策というのは、発生抑制という対策は、どこがどのように現状の取り組みを把握し、必要な対策を求めていくのか、そこを伺いたいと思います。","respondent":"鈴木防災課長","answer":"その中で皆様にお知らせする必要な情報もはっきりしてくると思いますので、その様子を見ながら、今後の啓発、情報提供については検討していきたいと考えております。","voiceIndex":22,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"駅周辺の滞留には位置づいているけれども、この協議会には参加していないというところがよくわからないのですけれども、鉄道事業者にはどういう責任と役割を担うことが必要なのか、区の見解を伺いたいと思います。最後にもう一点だけ。平成２６年度この協議会が動き始めますけれども、そこにおける障害者、高齢者、パブリックコメントをぜひ位置づけていただきたいと思いますけれども、いかがでしょうか。","respondent":"鈴木防災課長","answer":"１点目、鉄道事業者の役割、実際に乗客の方への対応ですが、先ほど申し上げましたように、これは徒歩帰宅する方の支援の対策事業ですので、ここには鉄道事業者は直接入っておりません。","voiceIndex":24,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に品川区でいうと大井工場、今は総合車両センターですか、駅の近くに大きいスペースがあります、グラウンドもありますので、というのは、広域的な役割からしても、鉄道事業者は乗客の方々が初めの３日間、ないし帰宅困難者の発生抑制、こういったところの位置づけ、品川区の地図上の位置づけでは大事になってくるのではないかと思いますけれども、その点改めて伺いたいと思います。","respondent":"鈴木防災課長","answer":"ただ繰り返しになりますが、この協議会は、具体的な徒歩帰宅者支援の対策ですので、この中で関連する鉄道事業者に伝えて対応をとっていただく必要があるものが出てきた場合には、当然お伝えしますし、鉄道事業者は同じ帰宅困難者対策の一つである。","voiceIndex":26,"id":"exchange-005"},{"speaker":"伊藤副委員長","kind":"確認","question":"地図を見ながらふと思ったのですけれど、ＣＳＲ協議会、それはそれでいいのですけれども、例えば南大井にいすゞ自動車の本社があります。大森ベルポート。ここは１,１００名ぐらい入るスペースがあるので、そういう企業にこの話を持ちかけていけば、相当大きな協力を得られる可能性があると思うのですが、そのことのお考えを確認したいのと。","respondent":"鈴木防災課長","answer":"１点目のいすゞ自動車、大森ベルポートですが、これはほかにも、ご指摘のように協力いただくと有効であると考えられる施設が幾つかあります。","voiceIndex":28,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"今の副委員長からの質問に重なる部分も含めて、新たに加わるそうした事業者が、今後その協議会へどういった形で追加、という言い方かどうかわかりませんけれど、加入していただくのか。単純に場所として提供していただくだけなのか、その辺のところもちょっと教えていただきたいので改めて。","respondent":"鈴木防災課長","answer":"それから２点目の、東京都や隣接する区との連携体制ですが、申しわけありません、最初にちょっとご説明すればよかったのですが、事務局としては品川区が中心でやっておりますが、構成メンバーとして東京都の帰宅困難者対策の部隊、港区と大田区の防災課にもお声かけをしまして。","voiceIndex":31,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"わかりました。協議会の中に加わるということで。その辺、もし何か情報があれば教えていただきたいのと。今ご答弁いただいたように、いわゆる旧東海道で各商店街があったり、また海岸通りとか、その辺も含めて協力いただけるようなところとか、もう既にそういうお声をいただいたようなところとかは、今現在どのぐらいあるのか、わかったら教えてください。","respondent":"鈴木防災課長","answer":"具体的にはこれから対策を考えてまいりますので、その中でこういう内容だねという、協力いただく内容が確定した時点で、協定でお願いするようなことになるかとは予定しております。","voiceIndex":33,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6450#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":16673,"voices":38}},{"id":"h26-20140512-6","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"区民委員会","time":"午後１時００分～午後１時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"のふれあい掲示板の建て替え","agenda":"のふれあい掲示板の建て替え","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"２点ほどお聞きしたいのです。私は朝、ちょっと見てきました。ガラスですが、雨ざらしのところだったのが、それはガラスが入るということですけれども、ガラスの強度はどうなのかというのが１点お聞きしたいのと、下に学校避難所が書いてあるのはすばらしいと思うのですけれども、名前だけ書いてあってもわからないのではないかと思うのですよね。その２点をお聞きしたいと思います。","respondent":"久保田地域活動課長","answer":"避難所の関係ですけれども、こちらにつきましては、まずは避難所名を載せさせていただいているところでございまして、こちらもいろいろな伝えたい情報等を伝えていければとは思うのですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"吉田委員","kind":"質問・要望","question":"ありがとうございました。強度があるということで、安心しました。地図を載せるのは、この範囲内で難しいというお話を聞きましたので、これは要望なのですけれども、できるだけ簡単な方法で、そういう防災に関しての、せっかくここに避難所を挙げたので、工夫していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"老朽化だったり、台風が来た後に掲示物が剥がれてしまって困ったという話はよく聞くかと思うのですけれども、今回の理由の１番目が、震災の経験で掲示物で効果を上げたことで、地域情報の発信拠点としての機能向上というふうに理由の１つ目にありますけれども、この意味合いというのはどういうことなのかを伺いたいと思います。財源ですけれども、４,９００万円という予算ですが、これは一般財源ですか。","respondent":"久保田地域活動課長","answer":"風雨等にさらされて、掲示物が劣化して剥がれてしまうとかという状況に加えて、板面のところが風雨にさらされますので、あれはゴムのカバーはしてありますけれども、中が木でできているということがありますので。","voiceIndex":8,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＱＲコードなど、どんどん新しい技術がありますけれども、電柱にはありますが、そういうのもこの際というか、これを機会に進めていただけたらと思うのですけれども、ぜひ震災時を再認識等であれば、活用方法だったり、活用の仕組みだったり、あらかじめ計画を立てて、地域の中でそれを日常的に訓練の中にもお知らせしていくという計画をしっかり持つことを、同時に進めていただきたいと思うのですけれども。","respondent":"久保田地域活動課長","answer":"緊急時への対応ですけれども、ふれあい掲示板も本数が４８３基ありますので、これに一斉に張るのは難しいということは我々も十分認識しているところでございまして、例えば駅前とか、ご指摘がありましたように地域センターの周りとか、そういったところでお知らせする際には。","voiceIndex":10,"id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"ＱＲコードは、もちろん震災が起きたときもそうですけれども、日常的にいろいろなイベントだったり企画だったり、そういう要素があったり、逆にちょっと場所がわからなくなったときの地図だったり、いろいろな情報で活用できると思いますので、幅広くご検討いただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-005"},{"speaker":"山元委員","kind":"質問","question":"１つ目は、設置数がさまざま、数が大小ありますが、設置数というのは何か条件があるのかということと、それから先ほど、町会とも相談しながら移転するというお話がありました。そうした場合、移動しましたよというのをどんなふうにお知らせするのかというのをお聞きしたいと思いますけれども。","respondent":"久保田地域活動課長","answer":"移転の際ですけれども、私どもは移転したとしても、例えばあるエリアにあったものが全然違うエリアに行くということではなくて、数ｍとか数十ｍ程度の移動と考えていますので、移転の方法を、こちらに移りましたという方法については。","voiceIndex":14,"id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。それこそ移転する場合は旧のところに、どこそこに移ったよという張り紙ではないですが、そのようなお知らせをしていただくと、特にお年寄りは結構見ていらっしゃいますので、その辺をちょっと工夫していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"}]},{"id":"topic-02","title":"の近隣セキュリティシステム「まもるっち」","agenda":"の近隣セキュリティシステム「まもるっち」","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろん、保護者の方が若い世代で、共働きで日中いない可能性があるのかもしれないですが、例えば休日はいたりとか、それはその時々によって違うと思いますので、協力者は１人でも多くいたほうがいいと思いますので、その点をぜひ、現在保護者でいられる方たちにはできる限りの協力者依頼をしていただきたいと思いますが、その考えを教えていただきたいのと、もう一点、今回新１年生という。","respondent":"上垣外生活安全担当課長","answer":"１点目の保護者に対する協力者としての協力要請でありますが、これはおっしゃるとおり、協力者の拡大は当然必要なことだと考えておりますので、努めていくべきだと考えています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問","question":"わかりました。逆にお父さんのほうが、会社が近くてとかいう可能性もあるわけですから、基本的に貸与している人数掛ける２倍まではいかなくても、保護者というのはお子さんに貸与するわけですから、できたら１人でも多くという意味では、貸与されている保護者はマストで協力者になっていただくぐらいな気持ちで取り組んでいただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"いろいろ内容は聞いてはいるけれども、あまりにも多いというのが、どうしても思うのですよね。伺いたいのは、要するに導入してから、平成１７年以来、何回ぐらい変わっているのか伺いたいと思います。この仕組み、大切だとは思いますけれども、どんどん機種が発達して、誤解のないように、随分変わるというところを伺いたいのですけれども、いかがですか。","respondent":"上垣外生活安全担当課長","answer":"こういう体制そのものが、悪いことをたくらむ人間に対する非常に抑止力になっていると考えておりますので、もちろん機種の変更については、必要最小限のものは必要だと思っていますけれども、このシステムそのものは引き続き継続していく必要があるのではないかと考えております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"最近では携帯でＧＰＳ機能があって、保護者は子どもがどこにいるか、すぐわかる機能を伺うけれども、子どもの立場で考えれば、今日こんなことがあった、ここで遊んだと親に言う前に、何だかいつもわかっているというのもどうなのかとも思うし、子どもは子どもで親に気持ちを伝える大切さも、いつの時代もそれは変わらないとは思いますけれども、その辺、どんなふうにお考えなのか伺いたいのと。","respondent":"上垣外生活安全担当課長","answer":"システムをどのように考えるかにつきましては、現状のシステムは、先ほどの繰り返しになりますけれども、ほかの区にはないシステムですので、これはこのまま継続していく必要がありますし、さらに子どもを見守るシステムはこれだけに限らず、おっしゃるとおり。","voiceIndex":27,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"１点だけ、登下校時の交通事故の危険性とありましたけれども、例えばこのような原因の事故があったと、危険があったと。それがなかったら、これはどういう情報からわかったのかということをお聞きしたいです。お願いします。","respondent":"上垣外生活安全担当課長","answer":"実例として報告を受けているものではございませんで、例えばＰＴＡの会合等で、こういった危険があるのですよという話を伺いまして、そういったことで把握しております。加えまして、町会長あるいは町の方の声からこういった話を伺いまして、把握しております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。子どもを守るアイテムが事故の原因になってはいけないと思うので、そういう情報というのはとても大切にしていただきたいので、そういうネットワーク的なことはどうなっているのでしょうか。その辺、お願いします。要するに、今の情報だと、ＰＴＡの方と町会の方、その２点からの情報が来たということ。そういう情報はどうなっているのか、横のつながりというのを教えていただきたいと思います。","respondent":"上垣外生活安全担当課長","answer":"こういった情報を仕入れるだけではなくて、こういった事案があれば、そういった事案がないように指導するとともに、私どものほうで子ども１１０番の事業だとか、教育委員会でやっております８３運動とあわせまして、全体として子どもの安全を見守っていく。","voiceIndex":32,"id":"exchange-013"}]},{"id":"topic-03","title":"の品川パビリオン共同出展事業","agenda":"の品川パビリオン共同出展事業","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"２点ありまして、１点目が、展示会の招待をされるところというのは、例えば区内の同じような事業者といったところにも、こういうのがありますので、例えば見に来てくださいと、次につなげるような意味でも、というようなことをされているのかどうかというのを１点と、１１月のタイでの展示会ですが、海外ですのでなかなか今、いろいろと内政が混乱していたりしているときに。","respondent":"山崎ものづくり・経営支援課長","answer":"今回につきましては、先日も首相からいろいろございまして、１１月まで動向を見きわめますけれども、いろいろな意味で注意深く見守っていかなければいけないというところで、安心・安全の部分もしっかり念頭に入れて、この事業に対応していきたいと思ってあります。","voiceIndex":38,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"正確ではないですけれども、大阪では『下町ロケット』といいましたかね、まいど１号だったか、大田ではボブスレーだったり、もちろん、ロケットを飛ばすこと、ボブスレーをつくることという技術と、それをつくるネットワークがあるのだということを同時に押し出すと思うのですけれども、品川のブースを起こすということで、そういうところもしっかり、誤解のないように言うと。","respondent":"山崎ものづくり・経営支援課長","answer":"産業支援の財団法人の品川ビジネスクラブも、同時にブースの出展を予定しておりまして、品川ビジネスクラブの取り組みでありますとか、パンフレットなどを通じて品川区のものづくり産業の集積をして、高品質な製品、高い技術というような一般的な周知も同時に行いつつ。","voiceIndex":41,"id":"exchange-015"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"中小企業センターまつりと、この非核平和都市品川宣言制定３０周年記念の関係がよくわからないのですけれども、３０周年ということでいろいろやるというお話を伺っていますが、どういう関係なのでしょうか。","respondent":"米田商業・観光課長","answer":"授業等で非核平和都市品川宣言のチラシ等をお配りしたり、あるいはパネル等でそちらの取り組みについて、これは総務課との連携になると思いますけれども、そちらからいろいろ資料等を借りて、このお祭りでも宣伝しようという状況になってありますので。","voiceIndex":53,"id":"exchange-016"},{"speaker":"向副委員長","kind":"意見","question":"青森にどうしても行きたかったとか、いろいろな思いはあるのですけれども、この１年間の間にオリンピックの開催が決まったりですとか、本当に経済の流れも速いなということを実感しながら、さまざまな施策がその都度、その都度出てきて、今後も多分、区民ニーズはますます多様化もしていくと思いますし、状況は変わっていくと思うので、これからもぶれない施策を軸として、皆様、また一緒に来年も頑張れたら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2694#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":18187,"voices":59}},{"id":"h26-20140512-7","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"厚生委員会","time":"午後１時００分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)の御殿山小学校西側敷地の活用","agenda":"はじめに、(1)の御殿山小学校西側敷地の活用","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今回、事業者決定のところで、用途が三つあるわけで、決定の選考メンバーについて、どういうふうな形で品川区は捉えているのか、所管をわたってどういうメンバーなのかということ。それから、今回、定期借地というところでは、第三者のメンバーがそこに入るのか、その辺はどういうイメージを持たれているのでしょうか。","respondent":"大串福祉計画課長","answer":"基本的には、こういった事業者決定に関与するものとしては、区側のみというのが通常のパターンかと思いますが、ご指摘があったように、定期借地５０年間ということの中でということで、何かできるものがあるかどうか、この辺も検討していきたいと考えています。","voiceIndex":10,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"ちなみに、老健の補助金に対して、特別養護老人ホームの場合には、東京都への助成の請求が複数回あるようなお話でしたけれども、老健については少ない、年間１回みたいなことを聞いているのですが、これは案ですから、公募スケジュールが何らかの形で動いたときに、何か影響があると考えているのか、その辺の状況を教えてください。","respondent":"大串福祉計画課長","answer":"基本的に、今、６月上旬に公募を行い、１０月下旬までには事業者を決定すると考えておりますので、その辺で大きくずれることはないとは思いますけれども、なった場合の補助協議についても、その辺はまた詳細については、今後詰めてまいりたいと考えています。","voiceIndex":12,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"定期借地で、土地の賃貸料の収入ということと、民間の方たちの建設で、そこら辺で、品川区は負担を少なくするということで、これを始めたと思うんですけれども、貸付けの条件のところで、区施設および老健施設等の専有部分は２分の１減額とするというのは、当初からそういうふうな計画になっていたのか、それとも、こういうふうに減額ということにしないと、応募がないだろうということなのか。","respondent":"大串福祉計画課長","answer":"やはりこういった公益的な事業ということで、貸付料そのものということではなく、２分の１の減額を行うことによって、端的に言えば、法人の事業運営を図っていくということも見据えながら、こういった形態をとっていると、このように考えております。","voiceIndex":14,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"私も行財政改革特別委員会の委員なんですけれども、この部分については説明がなかったと思うんですが、区の中の方針としては、当初、定期借地を使うときから、そういうことだったということでよろしいのでしょうか。","respondent":"大串福祉計画課長","answer":"ただ、そうは言いながらも、老健施設という公共的な事業を展開していただくにあたっては、２分の１の減額といったところで、運営する事業者の事業計画といったところをサポートしていくというのも、区の大きな役割だと思いますし。","voiceIndex":16,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"提案","question":"２点あるのですけれども、活用計画の(1)の3)のその他施設で、事業者提案に基づき検討、とあるのですけれども、これを取り入れたねらい。それから、例えば、福祉関係の高齢者の介護だとか、そういうものに特化しているわけではないと思うのですけれども、とにかく事業者の提案はフリーで受けるという感じだと思うのですけれども、その辺の事業者提案を取り入れた考え方ということ。","respondent":"大串福祉計画課長","answer":"具体的には御殿山小学校全体を同一の敷地と見なして、この制度を導入する。そうしますと、容積率としては３００％から４５０％に増えるといったところで、先ほど申し上げましたが、延べ床面積につきましては、１万m2程度の利用も可能になってくるといったものです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"提案","question":"２点目のほうは、イメージは大体わかりました。それをあえてこの事業提案ということにした考え方というのですか。今、民間の自由な発想とおっしゃったんですけれども、いろいろな提案があると思うのですけれども、その辺の選考も含めて、どういう考え方なのか、もうちょっと教えていただければと思います。","respondent":"大串福祉計画課長","answer":"そうした中で、区の考えとしては、老健施設については、現行は１カ所ですので、これの２カ所目を整備したいといったところで、まずは老健施設を設置していただきたい、これが大前提になってまいります。次に、大崎図書館の移転といった問題が出てまいります。","voiceIndex":20,"id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私も、活用計画の(1)の3)のその他の施設というところで、今のお話だと、特に区のほうから、こういうものというのは考えていないと。その面積でつくれるようなものは、どういったものになるのかということもあると思うのですけれども、ここの面積がどれくらい余るのかというのは全く検討つかない状況でしょうか。","respondent":"大串福祉計画課長","answer":"それと合わせるような形での提案事業というものも出て可能性もあります。そうしたところで全体の面積というのが出てくるかなですので、今の段階で、どれくらいの面積になるかというのは、ちょっとお答えはしかねるところです。","voiceIndex":22,"id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"老健も待たれていたものですけれども、ここに一緒に特別養護老人ホームがあるというのは、ほんとうに魅力的だし、これも待たれていることだと、私は思いますので、どんな提案が出てくるかわからないですが、そういった中でも、区としてぜひそういった方向で考えていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-008"}]},{"id":"topic-02","title":"の品川区立高齢者住宅（借上型）グレースマンションの貸主の変更等","agenda":"の品川区立高齢者住宅（借上型）グレースマンションの貸主の変更等","exchanges":[{"speaker":"たけうち委員","kind":"確認","question":"念のため確認なんですけれども、場所は２９号線がすぐに通っているところですか。当たってないですよね、当たっていたら多分これにならないので、そこだけ。所管が違うかもしれないですけれども、すぐ際になるかなと思うので、一応確認です。","respondent":"白鳥高齢者いきがい課長","answer":"住所からしまして、ちょうど横須賀線のところで、ここは当たってないかと思います。","voiceIndex":30,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"よくわからないのですけれども、平成６年に２０年間の賃貸借契約を結んで、新は平成３６年５月３１日までというのは、契約が間違っているのですか。突然１０年間契約期間が増えてしまっているようになっていますけれども、間違いということですか。","respondent":"白鳥高齢者いきがい課長","answer":"契約期間ですけれども、これまでの２０年間、それから今後の契約期間ということで、本来ですと、今年の５月３１日までの契約期間満了によりまして、そこで契約の再更新という形を取らなければならないといったことから、今回、こういった変更が生じたものです。","voiceIndex":32,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"だったら、委員会資料として、貸主の変更等の「等」になるのかもしれないのですけれども、１０年間の契約変更というほうが随分大きなことというふうに捉えるのですが、この資料のつくり方が、貸主を変更したというようなことで、再契約についてのコメントが一切ない中で、契約期間が突然１０年間更新されたというのは、資料としてちょっと説明不足ではないかと思うのですけれども、どうでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"委員ご指摘のとおり、本来ですと、この高齢者住宅の貸主が変更になったということで、本来、委員会資料としては、そのほうが適切だとは思うところですが、やはりここで契約行為がありますので、今回、貸主とともに、その契約期間というものをこの中に盛り込まないと、資料的には。","voiceIndex":34,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"利用者の人たちのことは、そこはわかりました。前回は２０年間の契約を結びました、今回は１０年ですということについては、何か理由があるのか。その辺については、また契約を１０年しましたというところをどこかで報告をする予定で、このような形なのか、その辺の経過を教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"そういった中では、家賃と、それから契約期間をどうするのかということを踏まえた中で、今後、条例につきましても、使用料の一部改正ということも視野に入れた中で、今後、その辺のところは報告をさせていただきたいと考えていますが、これまで３棟。","voiceIndex":36,"id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"４番の理由のところに、貸主の都合により、平成２６年３月３１日で譲渡したということなのですけれども、２０年間契約をしたけれども、都合で１９年１０カ月で契約が終わってしまったということなのでしょうか。それから、都合により、ということは、どうしてこういうことになったのかわかれば、伺いたいのですけれども。","respondent":"白鳥高齢者いきがい課長","answer":"それ以上の詳細につきましては、私のほうでは承知しておりませんが、これから、こういうような状況につきましては生じてくるものだと認識しているものです。","voiceIndex":38,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうしたら、新しく株式会社カーマトラストになっていくというところでは、住民の皆さんにとっては、何も変更はないと考えていいのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"これまで、個人の方が管理人をしていただいていたところですけれども、今度のカーマトラストは不動産会社で、そこから別の会社法人のほうに、ここの巡回管理とあわせて夜間の管理人の設置ということで、こういうような状況を。","voiceIndex":40,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"ちゃんと契約をしているのですから、その辺について、ちゃんとした説明があって、管理運営をお任せしているということではないので、譲渡については、同じような契約をちゃんと結んでいらっしゃると思うんですけれども、その前段の部分については、説明が適切ではないのではないかと思うんですが、いかがでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"そういう中で、入居者の方々にご心配、ご不安や迷惑がかからないように、家主側とその辺の事情聴取は行った中で、きちんと引き継げるかどうかということを判断した中で、今回の変更ということで承認をしたものです。","voiceIndex":42,"id":"exchange-015"},{"speaker":"井上委員","kind":"確認","question":"ここについて、ちょっと確認なんですが、こういった場合の譲渡という場合には、貸主の双方のやり取りだけで区はオーケーをするのか、そこについて、どういうふうな区の関与の仕方、あるいは、そこに責任というものはあるのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"そういった中で、いわゆるペナルティですとか、違約金ですとか、というような問題は、今回の高齢者住宅のあり方、住宅政策を進める、特にひとり暮らしの高齢者住宅政策を進めるにあたっては、やはり家主側の理解。","voiceIndex":44,"id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"確かに、この書類を最初に見たときに、あれっと思ったところはあるのですけれども、ただ、今の議論の中で、最後に一つだけ確認させていただきたいのですけれども、要は貸主が変わるわけですが、今回契約の更新をされています。","respondent":"白鳥高齢者いきがい課長","answer":"この変更に伴いまして、貸主が変わることによって、区のほうに何ら負担になることはございません。","voiceIndex":46,"id":"exchange-017"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"視察のところで、ちょっとだけ確認をさせていただきたいのですが、ここでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"},{"speaker":"井上委員","kind":"意見","question":"視察で、２番の鮫洲なぎさの家のところで、外部サービス利用型という表記があって、グループホームはほかのところにいって、同じようにやっているのですけれども、こういった形で見たのは初めてなので、これについて、外部サービス利用型指定共同生活援助というのは、どういうものか説明をしてほしいと思います。","respondent":"中山障害者福祉課長","answer":"一方で、施設の職員が直接的に介護サービスをするというものもあります。その２種類があった中で、多くの、今までグループホームの指定を受けていたところにつきましては、大方外部サービス型のこういった形態をとっているものです。","voiceIndex":53,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これはすばらしいことだと思います。もちろん、今も置いてあることは存じているのですけれども、前にもお話しましたけれども、福岡市とかに行くと、市長肝入りのクッキーが置いてあるとか、そういうのがありましたので、私の高望みかもしれませんけれども、品川区の庁舎に来ればそういうものがあるというものを、ぜひ今後開発をしていっていただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"１年間、皆さん、ほんとうにお疲れさまでした。そして、先ほどありましたように、厚生委員会として要望してきたことが、一部結実したというところでは、私も一部だと思っていますが、ほんとうに嬉しく思っています。これからも、議会として区民サービス、そして利用しやすい事業なども一緒に提案しながら進めていけたらいいなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":15014,"voices":58}},{"id":"h26-20140512-8","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"建設委員会","time":"午後１時００分～午後４時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"」を聴取いたします。 初めに、(1)「東京港第８次改訂港湾計画の策定","agenda":"」を聴取いたします。 初めに、(1)「東京港第８次改訂港湾計画の策定","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"このパンフレットのおしまいのところに意見募集について載っていて、これはチェックして切って投函すればいいという、簡単に意見が述べられるということなのですけれども、このパンフというのはどこまで配られているのかということと、意見を募集するに当たってどういう周知がされているのかというあたりを教えてください。","respondent":"中村都市計画課長","answer":"東京都からこのパンフレットを余分にいただいておりまして、今品川区の都市計画課の窓口のところにこれをストックをしているというところと、それからホームページのほうでも当然のことながら周知をしているです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区としては、都と連絡調整をするのがどこの部署なのかというのを教えていただきたいのと、先ほども区議会と行政と港湾局との懇談ですか、あると聞いたのですけれども、そういう意見を言う場がどのくらい、交流ができる場がどのぐらいあるのかも教えてください。","respondent":"中村都市計画課長","answer":"それと、この意見交換の場ですけれども、今後協議会ということで意見交換の席を設けしますけれども、それは今、現状ではこの１回の会ですが、また状況で港湾局と協議をしてまいりたいと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、そういった協議会を開くに当たっては、何らかの形で現地が把握できるような、視察なり、何と申しましょうか、何か現状を知りたいなという思いがあるので、そういうのはどこで受けとめていただけるのかなと思って、一つ要望なのですけれども、出させていただきたいのと、あと、港湾の関係のことですけれども、コンテナが増える、物流のところが増えていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ今意見募集をされているということなのですが、結構品川区に関する意見も出てこようかと思うのですが、その情報の共有化というのはどういう仕組みになっているのかということで、品川区民も先ほども港湾になってくるとなかなか区民の方も接しにくいというか広い意味になってきてしまうので、品川区として独自に何かこういう要望等々が受けとめられるような。","respondent":"中村都市計画課長","answer":"ただ、品川区内のいろいろな運動施設ですとか、そういったもののやりくりとか、今度また調整するようなことがあるわけでして、そんなときには、東京都のほうも事前にそういった情報提供ですとか協議を、その都度あらかじめしていただいているという今までの経緯もありますので。","voiceIndex":15,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう意味では、ここの品川区内での考え方というものも周知していく必要があるし、区民の皆様方からの要望なども今まで過去においてもあると思うのですね。そこをやはりまとめた形で、それぞれの担当の委員の方たちもそれを踏まえた形でじっくりと論議ができるということはしていかなければいけないと思うのですが、その部分についてはいかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"臨海部に面しているのはたしか６区ぐらいだと思うのですけれども、その中の１つですので、そういう中でこのバース等も含めて東京都の施設等を抱える区としてしっかりとこの計画に発言をしていく必要があるだろうと考えています。","voiceIndex":17,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"前々から議会で指摘をさせていただいたけれども、浜川砲台跡地というところが、これが東京湾の中にあるので、品川区の責任では対処できない話を聞いたのだけれども、これだってオリンピックの関連からすれば、さまざまな規制を変えていただいて、そこにオリンピックに来られる方々を誘導していくなり、これは品川区でもそういった施策をとっていくと思われるので。","respondent":"松代防災まちづくり事業部長","answer":"ただし、それが一定程度今足踏み状態になっておりまして、そういったものもオリンピックというキーワードを一つに、さらに規制緩和等を進めて、区民に近い水辺、そういった観光面も景観の面でもできるようなことが、それを発信するのには今回のこの港湾局の港湾審議会、または。","voiceIndex":20,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"よろしくお願いします。それから、あとは要望だけなのですけれども、グラウンドホッケーが建設される結果として、大井のグラウンドがなくなるという矛盾も出てきますよね。大井のグラウンドが品川区からなくなることは事実でしょうから、そういうことに対しての代替案というのもさまざまな形で指摘をしていただければと考えています。よろしくお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった具体的にどの程度増えていくのかとかそういう情報なんかも報告をしていただきたいし、区民の皆さんに対する影響を伝えたいし、また意見も反映していくという意味で、ぜひその辺を区長を通して風通しよく、お互いの意見を交流し合うというところをぜひ実現をしていただきたいと思いますが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"そういった中で、その意見をきちんと申し立てるという機会があろうかと思います。そういうような中で、それを踏まえたうえで東京の広域的な位置づけ、または国家戦略としての東京湾の中での位置づけ、そういったものを十分検討する中で進めてもらえると考えています。","voiceIndex":23,"id":"exchange-008"}]},{"id":"topic-02","title":"中延一丁目区営住宅の建替えについて","agenda":"中延一丁目区営住宅の建替えについて","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この地図のところに、ＲＣ造、地上３階建て２１戸とありますけれども、これが現状で２１戸あって、それが全部今埋まっている状況、２１世帯いるのかどうか、ちょっとそこをお伺いしたいのと、具体的にどのような建物になるのかというあたりまである程度案ができているのか、ちょっとその辺を伺いたいのと、東中延１・２丁目。","respondent":"矢木住宅担当課長、品川木密整備担当課長","answer":"第１点目。２１戸の住宅数のうちどれぐらい埋まっているかというお話なのですが、２０戸現時点で埋まっております。１戸はあきが出ておりますので、それはちょっと準備ができ次第募集をかけさせていただきたいと考えています。これからニーズというか件数、どれぐらいの建物を建ててどれぐらいニーズがあるかということを今年度調査をして進めていきたいと考えております。","voiceIndex":33,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっとここで聞けるのかな。同潤会のところはこの間質問した、ほとんど地権者の方のように私は受けとめていたのです。東京都の段階で何か安い賃料かなんかで借りていらっしゃる方がいるみたいな話を聞いたのですが、「老朽家屋等の権利者から、借家人の移転先や仮住まいとして」と書いてあるのですよ。ちょっとこの辺を説明をしてほしいんですけれども。","respondent":"品川木密整備担当課長","answer":"同潤会の地区ですが、ほとんどは所有者の方と思っていただいて結構だと思います。しかし、一部にはあの手の住宅ですね、一戸建てで貸している部分もごく少ないですけれども、あるというような状況です。","voiceIndex":36,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今ご答弁いただいた一部住宅を貸していると、そういう人のためなのですか、ここに書いてある「借家人の移転先や仮住まい」と。ちょっとここにかかわってくるのかどうか教えていただきたいのと、仮移転先を、先ほど一軒ずつ丁寧にお話を聞いて対応してくださるということなのですけれども、それは近くに住めるということなのか、その辺の対策も教えてください。","respondent":"品川木密整備担当課長、矢木住宅担当課長","answer":"いろいろなケースがありますけれども、例えば金額の問題、経済的な問題等で従前居住者住宅の方に移られる方もいらっしゃいますし、これもこの地区、同潤会だけではなく、今先行実施地区でやっている地区ですので。２点目のご質問、近くに住めるのかということに対して回答させていただきたいと思います。現在、西中延区営住宅の建替え工事で移転先ということで区営・区民・都営住宅等々に皆さんにお移りいただいているところです。","voiceIndex":38,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"最後ですが、説明会、本件報告後というのですが、もう大体決まっているのでしょうか。ちょっと、いつごろだとか。","respondent":"矢木住宅担当課長","answer":"場所等、あと周知期間等々を踏まえまして、私どもとしてはなるべく早く、５月末ぐらいまでにとは思っておりますが、そういった次第でもう少し先になってしまうかもしれません。ただし、遅滞なく行わせていただきたいと思いますので、よろしくお願いします。","voiceIndex":41,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、結局は２１戸ですね、今。高さとかいろいろ住民の問題もあると思うのですけれども、でも、区民住宅とか区営とかもあると思うのですが、そこら辺で要望が高いところの対応策として、そういう人たちを含めると、要望を聞いてからではなくてもう既にほかの要望もあるわけだからということを考えると、もっと戸数を増やしておいたほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"品川木密整備担当課長","answer":"規模のほうですけれども、従前居住者住宅に限って言えば、これからニーズ調査をしていくというところもありますし、例えば容積がまだ十分とれるような場所なのですけれども、どれぐらいの部屋数で割っていくかというようなこともありますし。","voiceIndex":44,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"これからニーズ調査もありますけれども、技術的なところも含めて何戸できるのかなということなのでしょうが、やはりここだけのことを考えるのではなくて、品川区全体の区営住宅の人数というのもあると思うのですよね。そういった場合の一つのいい、何というか、改良というか少し要望がかなえられるような状況にもなるので、広い意味で考え直していただきたいなと思いますが、スケジュールも含めて、あれば。","respondent":"矢木住宅担当課長、品川木密整備担当課長","answer":"こちらにつきましては、何度かこの委員会でもご説明申し上げているとおり、私どもの住宅施策のほうが居住環境の向上であるとか、民間ストックの有効活用ということで施策をしておりますので、現時点で増設等は考えてございません。これに関しては、当然仲介しておりますディベロッパーだとかあとは事業協力者だとか、いろいろ汗をかいていただいて、やはりうまくいい条件がないかということで当然サポートはしていますので。","voiceIndex":46,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"借家人に対しての対応については、介入できるものならばしていただきたいなと思っています。いろいろなこういう代用ということも当然必要となってきますので、そこをもっと広い目でニーズ調査を含め、これからの区営住宅のあり方であるとか密集市街地の整備に関しても含めて一応考えていただいての建設をぜひお願いしたいと思います。","respondent":"藤田都市環境事業部長","answer":"こういうような考え方で木密地域の安全性を高めるため、この辺の事業を引き続き展開をしていきたいと考えています。","voiceIndex":49,"id":"exchange-015"}]},{"id":"topic-03","title":"木密地域不燃化１０年プロジェクトの推進～西品川２・３丁目地区での不燃化特区本格実施について～","agenda":"木密地域不燃化１０年プロジェクトの推進～西品川２・３丁目地区での不燃化特区本格実施について～","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"新たにこの西品川２・３丁目が特区実施を行うということなのですけれども、資料１のところに赤く新しく今回という２０地区が書かれていますけれども、この不燃化特区に申請をする基準を改めて、ちょっとどういう状況で申請が出されるのかという基準を教えていただきたいのと、この西品川２丁目・３丁目、ここには住宅がどれぐらいあるのか把握をしていたら教えてください。","respondent":"品川木密整備担当課長","answer":"以前ですと、例えば共同建替えですね、そういった部分がコア事業としてないとできないということであったのですが、若干制度が緩和しまして、例えばこの地区内の老朽木造住宅をある程度の住宅を訪問していくという形、いわゆる全件訪問というような言い方で言っているのですが。","voiceIndex":55,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きっと前の資料か何かで示していただいたのかもしれませんけれども、全棟が１,６４０棟で、そのうちの老朽の危険な家屋というか領域について出てきたのだと思うのですけれども、もしわかったら教えてほしいのと、今後品川区内でさらにこの特区申請を出していく考えがあるのかどうか、その辺を教えていただきたいのと、あと５月３１日に事業内容説明会開催とありますけれども、今お聞きしたら。","respondent":"品川木密整備担当課長","answer":"今後不燃化特区の申請があるかどうかにつきましては、平成２６年度も不燃化特区の申請がまだできるという話が来てあります。地区につきましては、品川区としましても検討しまして、今後出すか出さないかも含めて考えていっている最中です。","voiceIndex":57,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まちづくり協議会がまだないということなので、ぜひ地域の方との話し合いを密にしていただいて、安全な地域を作っていただきたいと思いますのでよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-018"},{"speaker":"西本委員","kind":"確認","question":"一点だけ確認です。その辺どうなのでしょう。中延のほうだと１つにまとめていこうという動きが出ていると思うのですけれども、こういう密集市街地というのは、更地だとありがたいですけれども、またそこに建ててしまうと余計に密集市街地帯になるということも考えられるのですが、いかがですか。","respondent":"品川木密整備担当課長、藤田都市環境事業部長","answer":"委員のおっしゃるとおり、これは非常に難しい問題ではあるのですが、当然ここの地区、新防火地域という地区になっていまして、建替えるときには基本的には準耐火建築物以上の建物しか建てられない地区になってあります。今のような施策も一つですが、もう一つ、先ほどご説明の中でもさせていただいたまちづくり協議会的なものをこれから立ち上げるということで、まちづくりを地域の皆様と一緒に考える中で。","voiceIndex":61,"id":"exchange-019"}]},{"id":"topic-04","title":"「品川駅南地域 まちづくりビジョン」について","agenda":"「品川駅南地域 まちづくりビジョン」について","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"Ａ４のところにまず、地元町会長連名により区へ要望書提出とか、あと構想の提案が住民から出されたとよくありますよね。平成２５年１２月には、地元住民への意見交換会を開催。そこに住んでいらっしゃる方々のどのくらいのパーセンテージの方にこのビジョンが伝わっているのか、まず大もとのところをどう捉えているのかちょっとお伺いしたい。","respondent":"溝口都市開発課長","answer":"そういった中で、今回のものでいきますと、一応区域内の町会長さん全てに１２月の意見交換会についてはお声かけをして、それぞれ町会の中でお声かけをしていただいたり、中には回覧していただいたり、そういったところの対応をしていただいて開催しているものです。","voiceIndex":69,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いつも同じ答弁を伺っていますけれども。そういった意味では、区独自でやはり周知をし、意見を聞き、返していくという姿勢が大事であって、まちづくりビジョン公表ではなくて、区が自らやはりこのまちづくりビジョンに対して責任を持って説明をするというのはこの間ずっと求めているのですけれども、この辺、ぜひやっていただきたいなと思うのですが、いかがでしょうか。パーセンテージを教えてください。","respondent":"溝口都市開発課長","answer":"それをしっかり区が受けて区の負担として今回つくっておりますので、受けたところにしっかりどのようなものをつくっていくのか、またはつくるに当たってはどういう形にしていったらいいのか、そういったところでの意見照会をしておりますし。","voiceIndex":71,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この地域内のところで、都営住宅のこともこの間何回も申し上げているのですけれども、都営住宅の位置づけが今回ここの中に全く住宅政策や何かでもないのですけれども、なぜ都営住宅の位置づけがないのか、ぜひ区民の願いを最優先に考えていただきたいなという思いでは、現にここに都営住宅がありますので、そのこともきちんと位置づけてほしいなと思うのと、あとこのプランの中に、何ていうのでしょうか。","respondent":"溝口都市開発課長","answer":"そういった中で、これまでも大崎駅を代表にし、再開発事業等は進めてきておりますし、さらにこのプラン等、今後具体的な事業になりましたらそれは具体的な事業として、影響する範囲の方たちをまた集めてどのような事業をやっていくのか。","voiceIndex":73,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地球温暖化の問題でも電気を３倍以上使うものがなぜ今ここで必要なのかという、環境問題でもすごくクローズアップをされているという、何かリニアが通るし、羽田２４時間で、もう品川はどんどんそういうのに求められていくのだというのに乗っかっていいのかという思いがすごくするのですよね。私は常にやはりそういうブレーキをかけながら検討をしていかなくてはいけないのではないかなと思っているのですが。","respondent":"溝口都市開発課長","answer":"そういった中でいきますと、そういうできるところであれば、まちの方針等を図っていく上での一つの解決策としては再開発事業というのは非常に有効な手段だと考えております。","voiceIndex":75,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"観光的な面ということだから、品川区のよさを活かして進めていくこと、それは十分理解をしますね。でも、何ていうのですかね、外国の企業誘致にしていくヘッドクオーター構想とか、あとリニアの中央新幹線の開発もそうですけれども、こういうものに乗っかったときに便乗開発と言えると思うのですね。私はもうこれ以上の大型の再開発はやめていただきたいという意見を申し上げて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"それから見通しですね。具体的に一個一個やろうとすると物すごいお金がかかると思いますけれども、それをどのように考えて進めようとしているのかというのが１つ。どうやって来るのって。どうやってって、何でしょうかね、何か興味がなかったら北品川のほうに来ないですよね。多分品川駅からいろいろなところに分散していく状況になると思うのですね。これをどういうふうに考えていくのかな。","respondent":"溝口都市開発課長","answer":"というのは、今後どういう事業が起きてくるのかというのが想定できませんと、やはりどういう事業費がかかるのかというのがなかなか難しい部分と、また区のほうでの予算という話になりますが、毎回再開発事業等でありますと、一定。","voiceIndex":79,"id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"具体的な形が固まってくると補助金というのは大体１４％から２０％という形なのでしょうけれども、先立つものがなければ資料の１０ページのように、これはすばらしいイメージ図だとは思うのですね、1)、2)、3)と。ここの、つくるに当たってコンサルタントの会社が区からどういうイメージを持ってお話をされて、こういうものができたのかなというところの経緯だけちょっとお願いしたいと思います。","respondent":"藤田都市環境事業部長、溝口都市開発課長","answer":"区といたしましては、例えばまちづくりのマスタープランですとか、品川区の景観計画、こういったものの中で旧東海道の重要性については十分認識をし、今後のまちづくりについていろいろ検討を進めているところです。それと、１０ページに書かれている絵ですが、具体的なものができまして、一応想定しているのは、やはり再開発事業をやることによってそうしたところでの地域貢献とかそういったものをいかに引き出すか。","voiceIndex":81,"id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"非常に、すごくビジョンがとてもいいと思うのですよね。こういう形になってくると、これが具体化されていくと非常に品川区のほうに来ていただける方が多くなるし、まちの賑わいという意味でも非常にいいのかなと思う。いずれにしても、そういう意味ではつながっていくような形で回遊性を広く持たせるような形にぜひ実現していってもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"コンサルを依頼しているということでやっていらっしゃるのはわかるのですけれども、本当にこういうふうになっていってくれたらいいなと思うのですが、まずもう一回こういった将来的なイメージ像についてのお考えと、何でかというと、やはりまちづくりのビジョンというのでもう七、八割方が決まってくるのかなという私なりの考え方が、はっきり申し上げてしまうと成功。","respondent":"溝口都市開発課長","answer":"そういったところでのゾーニングをしていくと、申しわけないのですけれども、大きくは５つ、それがちょっと入り組んだ形での配置になるというのがこの地域の、逆に特徴だと考えているものです。","voiceIndex":86,"id":"exchange-028"},{"speaker":"原委員","kind":"質問","question":"厳しい、ちょっと耳の痛い言葉かもしれませんけれども。地元の町会とかほかの団体が一番なのですけれども、それだけではなくてそういった、この中にあったり、これは都だけ、日本だけではなくて、世界的に進出している企業もおかげさまで品川区にはだいぶ増えてまいりましたので、その辺との打ち合わせ、今後ですね、今すぐということではありません、今後においてのお考えがあったらば教えてください。","respondent":"溝口都市開発課長","answer":"そういったところともしっかり連携しながら実際のところどういうまちづくりができるのか、そういったものも地元だけではなく、そういった企業の方たちとも今後、特に重点計画地域についてはどのようなまちづくりが行われるのか。","voiceIndex":88,"id":"exchange-029"},{"speaker":"原委員","kind":"質問・要望","question":"これは当然先ほどから聞いていると、地元地元とか、町会がとかあるのですけれども、地元の町会は当然に第１番で大事です。ですけれども、行政、自治体として品川区の考えも出していっていただきたいので、その辺のところのご意見を伺いたいと思います。","respondent":"溝口都市開発課長","answer":"そういった中で、一つのきっかけとしては、品川区が国家戦略特区の区域に指定される中で、そういった中での緩和施策ですとか、そういったものもどういう形で打ち出されるかというのはしっかり検討して。","voiceIndex":90,"id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"もう終わりにしようと思ったのですけれども、活用していくのは当然だと考えています。逆に言うと、東京都、国に協力していただくのは当たり前だと考えています。あれば、そうしていけということではないのですけれども、そういった形のもののご意見があればいただきたいなと思ったので、その辺だけお願いします。一言で構いません。","respondent":"溝口都市開発課長","answer":"空中権の話もそうですし、容積の話とかいろいろさまざまな事情、またはその資金調達の仕方等はあると思います。そういったところも踏まえてこのまちづくりが力強く進むように、そのほうは今後検討していきたいと考えています。","voiceIndex":92,"id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、来ないという意見もあるわけで、非常に難しいことを言いながら質問するのだけれども、そういう現状を踏まえた上で、では東海道をどうするか、それは待っている姿勢ではなくて、もう少しハードルを下げていくことも考えてはいかがでしょうかというのが１つと、それからちょっとオリンピックのことを言っていますけれども、立会川はちょうどオリンピックのことに関連して。","respondent":"藤田都市環境事業部長","answer":"その辺の動きとも連携しながら、また進めていければと考えています。オリンピックの絡み、それから立会川の駅のあたりからということになるのかもしれませんが、この辺については、やはり十分慎重な議論が必要なのかなと考えています。","voiceIndex":94,"id":"exchange-032"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ちょうど今オリンピックが来たわけですから、その機会を最大限捕まえた上で対処していただきたいのと、それから本当に東海道を考えていくとするならば、やはりもう少し都市マスタープランの中で具体的にどう鮫洲、立会川、大森海岸、ここの地域のことについての具体的な計画についても、もう少し踏み込んだ形で地域の実情を考えた上で対処していくことにしたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-033"}]},{"id":"topic-05","title":"しながわＥＣＯフェスティバル２０１４の開催について","agenda":"しながわＥＣＯフェスティバル２０１４の開催について","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"質疑と言えば質疑なのですけれども、このカラーのパンフレットのご当地キャラとクレイヴァルス、これはこれでいいのですけれども、ご当地キャラは２つだけではないと思うのですよね。例えば、しょうちゃんがあったり。何でこの２体だけなのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"今年の特色の中で、イベント実行委員の充実とあるのですが、これは何でしょうかという質問と、それからここは多分ボランティアでいろいろな方がしていただいていたと思うのですが、朋優学院だけではなくて、ほかのところもやっていたと思うのですよね。それは増えているのか。","respondent":"三ツ橋環境課長","answer":"３点ご質問があったと思います。１点目のイベントの実行委員会の充実に関してですけれども、昨年度までは２回の実行委員会だったのが、今年からは３回実行委員会を増やしております。それと、実行委員の中で、リーダー方式を今年からとりました。","voiceIndex":108,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"一番上のイベント実行、３回やるようになりました、リーダー方式にしましたよと、今まではそうではなかったのですか。何かいろいろ改善というか、課題があったからこのリーダー方式にして改善がなされるようにしたということだと思うので、どういう形になっているのか。それから、この点はわかりました。大崎高校、今年も大々的にやっていただけるということなのですね。いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"もう一つ廃油の関係ですけれども、申しわけありません、広げてこちらの右側の３段目なのですが、「公園会場における使用電力はすべて廃油を」という文言が、こちらに詳しく、文字だけですけれども、ちょっと薄いかもしれないのですが、載っておりますので。","voiceIndex":110,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"各自、いろいろな方がかかわってフェスティバルがマッチングされていますので、もっと自由に積極的にやっていただけるような仕組みをまた継続的にお願いしたいと思います。自家発電に使ったよというのはちょっとわかりづらいなと思うので、もうちょっと出してもいいのではないのというような感じがありますので、来年は工夫をしていただきたい。さらにもう一つ。キャラクターの話が先ほどありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-037"},{"speaker":"木村委員","kind":"質問","question":"くだらないことなのでしょうけれども。しながわＥＣＯフェスティバルというのは、今年何回目になるのか。今年初めてということはないですよね。違いますよね。何回目になるのか。それと、毎年やっていて、お客さんの乗りとか、それからＥＣＯに対することで区民の皆さんにどのぐらい認識をしてもらっているのか。もしそれがわかれば教えてください。","respondent":"三ツ橋環境課長","answer":"最後の区民の環境に対する認識ですけれども、ＥＣＯスタンプラリーというものを行っておりまして、そこで皆さんのＥＣＯチャレンジ宣言というものを書いていただいております。","voiceIndex":113,"id":"exchange-038"}]},{"id":"topic-06","title":"焼却灰溶融処理施設の稼働休止について","agenda":"焼却灰溶融処理施設の稼働休止について","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"灰溶融処理施設の溶融炉休止ということですが、溶融しなくとも最終処分場の延命は可能だという判断なのですかということの質問が一つと、それからこれを導入するときに相当お金をかけて建設しているはずだし、その後のランニングコストにも相当お金がかかっているはずです。単純にそれだけのコストがかかってこれをなくすならば、各区の負担が下がるのか。","respondent":"小林品川区清掃事務所長","answer":"現在、私の承知しているところでは、年間の処理量が１７万トンのスラグをつくっているところが、その後は２.４万トンぐらいに平成２８年以降は減ってしまいますので、それから逆算すると、６万トン弱の埋め立ての増が見込まれます。","voiceIndex":119,"id":"exchange-039"},{"speaker":"伊藤委員","kind":"意見","question":"清掃委員会のことにも入っていますので、なかなか突っ込めないのですけれども、私の思いとしては、これだけの灰溶融施設をとめるわけだから、かかっていたコストが当然、マイナスになるわけだから、それは結果として各区に跳ね返ってくるような制度設計をお願いしたいと思いますので、よろしくお願いします。それから、あと６万トンの埋め立て増になるのですよね。よろしくお願いします。","respondent":"小林品川区清掃事務所長","answer":"承知いたしました。","voiceIndex":121,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のに若干関連するのですけれども、休止というのをどう捉えたらいいのかなと思っているのと、多摩川と葛飾は今後もここの２つの箇所は続けていくということかと思うのですが、休止の捉え方を教えていただきたいのと、灰溶融を始めるときにも建設費も維持費もコストがかかるとか、あと１,２００度に上げるというところにおいては、地球温暖化防止に対して逆行するというか地球の環境に負荷がかるとか。","respondent":"小林品川区清掃事務所長","answer":"なぜ休止なのかということについて清掃一部組合は、将来大きく状況変化があったときに備えて、今まで投資した設備を無駄にすることなく、場合によっては必要ならば稼働の余地を残した含みだというご説明を受けておりますが。","voiceIndex":123,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"役割が小さくなっているということですけれども、基本的には燃やすごみを、大もとを減らしていく、処分場の延命にかかわるあらゆることで本当にごみを燃やす部分を減らしていくというところをぜひ追求をしていく一環として考えていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-042"}]},{"id":"topic-07","title":"補助１６３号線（東急大井町線ガード下区間）事業説明会の開催について","agenda":"補助１６３号線（東急大井町線ガード下区間）事業説明会の開催について","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"周知の方法なのですけれども、かなり長い期間、交通の混雑をする場所でありますし、あと区役所に来庁される区民の皆さんのことも考えると、かなり周知を丁寧にしていただきたいと思います。そういった意味では、この周辺にチラシ、回覧、沿道ポスティングとありますけれども、もうちょっと広範な皆さんに状況がわかるようなお知らせをきちんとしていただきたいなと思うのですけれども、いかがでしょうか。","respondent":"稲田道路課長","answer":"西品川三栄会、大井一丁目権現町会、それから二葉一丁目町会。それから商店街ですね、二葉一丁目商店街。これも３商店街ありまして、大井一本橋商店街、大井サンピア商店街というところの方たちと事前に話はしながら回覧等は回していこうと考えております。","voiceIndex":130,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひわかりやすい、区民の皆さんにお知らせするような表示の仕方も考えていただきたいと思います。裏面には、平成２６年度事業実施及び予定区間ということで赤い表示がありますけれども、結構あちこち開発も起こっていますけれども、重なるような開発とか工事とかがないのかどうか。そういうのも工事車両の回しや何かもすごく影響するので、その辺の把握とかはされていますか、どうですか。","respondent":"稲田道路課長、溝口都市開発課長","answer":"現在進めております再開発の交通関係におきましては、交通の協議会等をもって現在はやっておるですので、我々も工事に参加することになれば、その辺の情報のやりとりは綿密にやって、本当に事故が起こってはどうしようもありませんので。そういった工事期間が今回道路課がやられる東急大井町線のガード下の区間と重なるところがありますので、そういったところで工事車両の搬入・搬出、または工事規制のあり方、そういったものは十分再開発組合のほうと事業者である道路課。","voiceIndex":132,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"高さがどのぐらいになるのか、それから工事中も、交通量も多いし人もたくさん通るし、どういう形になりますか。具体的にわかれば教えてください。","respondent":"稲田道路課長","answer":"交通の関係におきましては、十分注意して、検討しながら、並行しながらやっていきたいと考えております。","voiceIndex":136,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"すごく危なくて、危うく事故が起きそうな羽目にも遭遇したりしているので、そうならないように図っていただきたいのと、ここ、信号機、５差路になるのですかね、すごくわかりづらくて、通りにくい。多分区役所に来るときに二、三回困ったことがあるかなと思うのですけれども、それは改善は無理なのかな、どうなのかなと思うのですが。道路幅は今よりも大分広がるという認識でよろしいでしょうか。","respondent":"稲田道路課長","answer":"それと、道路幅員なのですが、都市計画道路の幅としては１６ｍなのですけれども、あそこの２６号線につながる部分が約３０ｍほど広がった形になる予定です。","voiceIndex":138,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"１点だけ。今、ちょうどガード下というのは雨に濡れないようにということで区役所に来る側にあれがありますよね、屋根つきのところ。あれはああいう形で大井町から来られる方が濡れないような形で行けるというふうに配慮できるようにはなるのでしょうか。","respondent":"稲田道路課長","answer":"ただ、工事の状況状況によっては、ちょっと皆さんに周知しながら、ちょっと屋根がないですよという形になると。その屋根というのが仮設の覆工板をかけた下側になったりとかそういう状況になるかもしれませんが、その辺は十分に現場を見ながら検討したいと考えています。","voiceIndex":140,"id":"exchange-047"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"２点ほど確認させてください。あらかたまだこの予定が立たないところもありますが、この拡幅でかなり橋桁の下が広がるというのは用地を取得したりいろいろな作業が入ってきますけれども、大体具体的に工事が始まるというのはどれぐらいを見るのでしょうか。それが１点。それから、要はこの説明会が８月の上旬に１回行われる。そこら辺の進め方の姿勢というか、そこら辺を確認しておきたいと思います。","respondent":"稲田道路課長","answer":"着手の予定なのですが、事業認可を今年度１月ぐらいには取得したいなというところで、都を通じて国のほうへその前に申請していきたいと考えております。","voiceIndex":143,"id":"exchange-048"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ここは本当に狭いところをこれから拡幅され、区役所に行く道も歩道も広がってというところが非常に利便性が高まるところだと思うので、皆さんがここは希望するところだと思いますので、この長い期間工事が行われて無事故で進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-049"}]},{"id":"topic-08","title":"しながわ水族館経営改善検討委員会取りまとめについて","agenda":"しながわ水族館経営改善検討委員会取りまとめについて","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"何点か確認させてください。そこの検討会と、それからこの作業部会の関連と言ったらいいのですか。私たち、たしか議会からは、大幅な改善をしなさいということを指摘させていただいた経過があるので、まず確認したいのが、庁内経営改善検討委員会作業部会のこのとりまとめと、それからあり方検討会だと思ったのですが、その整合性について、まずお聞かせください。お願いします。","respondent":"多並公園課長","answer":"結果としては、平成２５年度５.５％プラスということでまだまだ１４％落っこちたところからすると、改善はそこまで図られていませんが、今後このような改善の取り組みを行いながら、今後の動向をある程度見据えた段階で、最終的なあり方検討というのをまとめていきたいと。","voiceIndex":150,"id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問","question":"次のステップとして、アンケートをとったら飲食店がないということ。そうなのですよね、この地域。だから、そういうところと連携をとっていくなり、それからあと、あそこの大森海岸駅の近くには飲食店がほとんどないので、地元の商店街といかに連携をとっていくかということで、ここにある飲食店がないということについての対応をとるべきだと思うのですが、それをこれから検討していくということなのですか。","respondent":"多並公園課長","answer":"発表のときには、こういう商店街が、ゆるキャラを通じてですけれども、区内にあるということを区外から来た方にも知っていただいて、そういう機会にしながら、その後の、水族館だけではなくて区という形の充実につなげていきたい。そういう考えのもとに現在企画しています。","voiceIndex":152,"id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問","question":"だったら、もう少しビジネスモデルを検討していったらいいのではないでしょうかと思うのが１点と、それから、先に聞けばよかったのですけれども、このしながわ水族館の位置づけをどう考えていくかということなのですよ。もし教育施設とするならば、しながわ区民公園の中で、５時だったかな、５時に閉まっていい話。翻って考えれば、では水族館をこれからどういうふうにしていくのか。","respondent":"多並公園課長","answer":"ただ、今後のオリンピックのことに向けると、どこをどういう形でやればいいのかというのは、今ちょうど試行錯誤していかなければいけないかなという部分で、今回まずはやってみようと思ったところが。","voiceIndex":154,"id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"それをもう少し延長して水族館の夜間営業の時間を増やしていくなり、夏休みの間は一定時間延長していくなり、もう少し柔軟に考えていって来場者を増やしていくことを考えていくなり、教育施設という枠をかけながらなんだけれども、ビジネスモデルは最大限確保していくといったりということが、そういう方向に進めていかないと厳しくなってくると思うのですが、いかがですか。","respondent":"多並公園課長","answer":"委員のお話のとおり、もちろん教育施設から出発して、運営するに当たっていわゆる民間企業の活力を得ながら効率的に運営できないかということで、当時のモデルとして今のような形で民間に任せながら成功した事例だと思います、進めてまいりました。","voiceIndex":156,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"意見","question":"まとめていきますけれども、要は商業施設ならばもっといろいろなことができるのですよね。だけれども、あくまでも教育施設というのであるならば、それはそういうところを捕まえた上で、最大限の努力をしていただいて。それぐらいの思いでやっていただいて、十分検討していただきますようお願いします。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"アンケートの中にも役に立つと思うとかで７割の方が再び来たいと。大事な教育の資源を活用してもらうという意味で、この間コミュニティバスの運行とかもいろいろ区民の皆さんから願いが出ていますけれども、足の便をもっとよくしてほしいというところの努力をちょっとしていただけたらもうちょっと行きやすくなるのではないかなと思っていますが、いかがでしょうか。","respondent":"多並公園課長","answer":"もう一つの大井町のルートについてはかなり利用がありまして、それについては入館に寄与するところが大きいだろうということで、現在も運行をしながら進めているところですので、なかなか過去の経緯と今も含めても、今のような形で進めていきたいという考えです。","voiceIndex":159,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"過去の経緯はこの間も１回お伺いしたので、把握している上でなのですけれども、区内のいろいろな施設、資源をやはり回っていくうちの一つとして水族館も考えていくみたいな、もうちょっとおおらかなところで捉えていただけたらいいかなとも思っていますので、来訪・再訪者を増やしていく、行きたいけれどもなかなか行けないという方たちのために、ちょっと工夫を考えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-056"},{"speaker":"西本委員","kind":"提案","question":"このアンケートの結果の中でも、先ほどからの飲食物の販売に対して改善提案というのが出ていますけれども、サンシャインから言われているこれはどういうことを想定しているのかな。それが２点で。今深海魚がすごくはやっていて、施設的にどうなのだろうなという部分があるのですけれども、そういう流行りというのがあるので、そこらを検討材料に入れてもいいのではないかなと思うのですが、いかがでしょうか。","respondent":"多並公園課長","answer":"ただ、それはちょうど今話していたところだったので、私もどうなのかというのは、ちょっとほかの水族館の状況とか、水族館だけではなくていろいろなところで話題になっていますから、そういうのも含めながら、どういういわゆる出し物が効果的なのかというのを。","voiceIndex":162,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"深海魚は難しいと思うのですよね。割引券ですからいい宣伝材になると思いますので、そういうことも考えていただきたいと思って、これもお願いいたします。いろいろあったほうが楽しめるし、あとは物産展みたいなものも継続的にやるとかというふうになると、人寄せパンダではないですけれども、なるのではないかなと思うのですが、いかがでしょうか。","respondent":"多並公園課長","answer":"ただ、もう一個あった物産展とかそういうのは、またいろいろなイベントを開催し企画する段階で、そういうのはまたちょっと違った形ですので、企画とかこの水族館に呼び込む形になるかと思うので、そこら辺は検討してまいりたいと考えています。","voiceIndex":164,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"もちろんサンシャインとの関係があると思うのですが、だからこそ競争心がなくなってしまうのですよ、そういう形になると。せっかくいろいろやろうと思っても、そこだけだとそれで終わっちゃう。独占企業みたいなものですよね。だから、それになるように、ちょっと行政側としては配慮していかなければいけないのではないかと思いますので、ぜひ研究をしていただきたいと思います。意見だけちょっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-059"}]},{"id":"topic-09","title":"平成２６年度の水防訓練の実施について","agenda":"平成２６年度の水防訓練の実施について","exchanges":[{"speaker":"西本委員","kind":"質問","question":"訓練内容は、新たに加わったものというのはどれになりますか。いつものですけれども、今回新たに取り入れられるというものはありますでしょうか。","respondent":"加藤防災安全担当課長","answer":"これは過去にやったことがあるないというのは、ちょっと定かではありませんけれども、昨年にはなかったものとしては、マンホールの噴出防止工法などがあります。それから、ヘリによる災害情報伝達も昨年はありません、おととしはやっていると思いますけれども。","voiceIndex":171,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"毎年毎年この水防訓練をされているのですよね。毎年ちょっと内容が違うのですよね。いろいろという意味でやっているなと思うので、それなんかも区民の皆さんに知らせてあげると、品川区としてこういう水防訓練をやっていますよみたいな宣伝をされると安心だし、あとボランティアの方々も増えるのではないかと思うのですけれども、その辺の通知とかＰＲとかは何か考えてあるのでしょうか。","respondent":"加藤防災安全担当課長","answer":"水防訓練を実施するということはお知らせはしておりますけれども、特段会場の関係で見に来てくださいという形ではご案内はしてない状況です。ただ、町会長をはじめ、ご案内をして来賓として来ていただいて見ていただくという形はとってあります。","voiceIndex":173,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"何かもったいないなと毎年と見ていると思うのですよね。毎年テーマを変えていろいろやっているなと思うのですけれども、私たちもなかなか伝え切れない部分があるので、ぜひこちらからも積極的にしていただきたいなと思いますので、今後考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4104#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":64330,"voices":180}},{"id":"h26-20140512-9","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"文教委員会","time":"午後１時００分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２５年陳情第９号「子宮頸がんワクチン接種事業の見直しと、健全な教育を求める」陳情","agenda":"平成２５年陳情第９号「子宮頸がんワクチン接種事業の見直しと、健全な教育を求める」陳情","exchanges":[{"speaker":"本多委員","kind":"意見","question":"結論を出すべきだと思います。それで、賛否につきましては不採択を主張します。理由につきましては、子宮頸がんワクチンに課題はありますけれども、予算も成立をして実施という方針でありますし、また性道徳につきましては、現行でやっていることを継続していただければいいと考えていますので、強化するという部分は必要ないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"},{"speaker":"塚本委員","kind":"意見","question":"理由につきましては、今、本多委員のほうからもあったとおりなんですけれども、文教委員会といたしましては特に性道徳教育を強化ということだったんですが、その点については現状されているもので、それ以上のもので強化していくという必要性は特にないであろうということと、子宮頸がんワクチンを勧奨するかどうかということにつきましては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-002"},{"speaker":"大倉委員","kind":"質問","question":"本日、結論を出します。態度は不採択でお願いします。不採択の理由としては、先ほどから皆さんあるとおり、予算の成立が行われ実施もされているというところと、強化というところでは現行どおりされているというところで、不採択でお願いいたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"私も不採択でいいと思います。したがって、今日結論を出したいと思います。その不採択の理由は、健康の問題と性道徳の問題は別次元の問題だと思っています。したがって、この趣旨には賛同しかねます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-004"},{"speaker":"高橋委員","kind":"意見","question":"結論を出すということで、不採択です。理由は、区立学校の中で、市民科をはじめさまざまな時間等で性についての教育が現行なされていると思いますので、そういった教育活動全体の中でそういうことを実施されていると思いますので、強化云々というところについて、やはり不採択という形になると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-005"}]},{"id":"topic-02","title":"(1)平成２６年度新入学学校別増減要因一覧","agenda":"(1)平成２６年度新入学学校別増減要因一覧","exchanges":[{"speaker":"南委員","kind":"質問","question":"１点だけ、一貫校等その導入時、私立よりも公立を選んでほしいということが言われたかと記憶しているんですけれども、その記憶が正しくなければ訂正しなくてはいけないのですが、そんな点で、私立はずっと数年前からなんですけれども、経年で見てみたら、人数的なのは増減がありますけれども、パーセンテージではそんなに大きく変動しているわけではないので。","respondent":"野呂瀬学務課長","answer":"例えば第１志望がだめだったときには公立の中学校へみたいな声もありますので、そういうことからすると、やはり公立、私どもの中学校を選んでいただけるというのが、年々人口の増加とともに増えてきているという傾向はあるのかなと捉えているところです。","voiceIndex":15,"id":"exchange-006"}]},{"id":"topic-03","title":"平成２７年度品川区立学校教育職員採用候補者選考日程","agenda":"平成２７年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"お医者さんというのは、いわゆる一人前のお医者さんになるまで、学校のところの勉強も含めて、命を徹底的に守るという勉強をすごくされると聞いたことがあるんですけれども、そういう意味で、やはり子どもたちに対して暴力をついつい使ってしまうというか、かっとなる場面、人間だからありますけれども、そういうところをもう少ししっかりと兼ね備えた資質を大事にするためにも。","respondent":"渋谷指導課長","answer":"その際には、こういった服務事故、体罰を含めた服務事故を起こさないようにということで、そういった部分の資質については必ず質問をして確認をして、またさらに徹底してまいりたいと考えているところです。","voiceIndex":22,"id":"exchange-007"},{"speaker":"高橋委員","kind":"質問","question":"前にもちょっとお尋ねしたのですけれども、選考の内容で、教員の資質として、ここにあるような一般教養、教職教養、論文等の資質もそうなんですけれども、授業の力も、もちろんそれだけではないんですが、幾つかある要件のうちの一つだと思うんですね。そういう授業とか教科の力に関するものさしは、どのようにされる状況なんでしょうか。","respondent":"渋谷指導課長","answer":"例えば発問の技術はどうなのかだとか、子どもの見とり方についてはどうなのかだとか、模擬授業等々ではさらに掘り下げることのできないものについて質問をすることによって、細かく先生の指導力というものを推し量ろうとする内容で、時間をとって面接をやっているものです。","voiceIndex":24,"id":"exchange-008"},{"speaker":"高橋委員","kind":"質問・要望","question":"わかりました。ぜひ、幾つか必要な質問の中の、特に新規採用の方は、初めから授業をもうずっと４月から持たなくてはいけないということなので、その時点で十分力がないと、その学級の把握に関してかなり影響があるので、そこを面接のほうで見ていただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"一般選考ということですから、それまで教職に全くついていない、未経験、資格は持っているけれどもという方と、この経験者採用ということで、もうちょっと年齢のいった方で教職の経験のある方と。こういう採用の立て分けをしている考え方というのをまず最初にお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"特に経験者選考については、実績のある力、即戦力を求めたいということで、経験者選考の枠を広げているものです。一般選考はいわゆる新規卒業を対象として、約３０歳までの若い先生たちの補強という意味合いで、これは通常の採用という例年のことです。","voiceIndex":27,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"一般選考が未経験ということなので、そういう意味ではもっと若い、それこそ学校を出てすぐ新卒の方というのはあえて対象にせずに、昭和５８年、３０歳ぐらいということで切っているということは、そういう意味ではないんですか。","respondent":"渋谷指導課長","answer":"３０歳が上限ということになります。２２歳から３０歳までの方が対象ということです。","voiceIndex":29,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"そういうことなんですね、ごめんなさい。私が間違えました、わかりました、結構です。そうすると、新卒で未経験の方も採用されるということで、大体人数的には何かバランシングというのはあるんですか。一般選考と経験者選考で６人程度を採用しようという中で、どちらを何人というようなところ、それはその実際の応募を見ながらいろいろ決まっていくことになるんでしょうか。","respondent":"渋谷指導課長","answer":"昨年度の申込み実績で見ますと、７６人申込みがあって、一般選考で４６人、経験者選考が３０人というような申込み区分になってあります。","voiceIndex":31,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"そういう意味では新卒というのは未経験で、初めて真っ白な中に品川の教育というものを植え付けていくではないですけれども、そういうほうがいいのではないかという考え方をお持ちの方もいらっしゃると聞いたことがあるのですけれども、そういう意味では、経験者選考で即戦力で一定程度必要というのもそのとおりだと思うんですけれども、去年も一般選考が３人のうち２人ということで。","respondent":"渋谷指導課長","answer":"すみません、ちょっと訂正させてください。昨年度３人のうち、今現在立会小学校で働いている先生が新規採用一般選考枠で、残りのお２人は経験者選考で採用をしております。","voiceIndex":33,"id":"exchange-013"}]},{"id":"topic-04","title":"平成２５年度品川区立学校における体罰等の実態把握","agenda":"平成２５年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"南委員","kind":"質問","question":"非常にちょっと憂鬱な気持ちでこの資料を読みました。それで今、現実的には現場の先生、実践されている先生の中で起きている問題ですから、ＤＶＤだとかそういうものを活用して指導し、研修し直すということは、それはそれとしてやっていただかなくてはいけないと思うんですけれども、同時に２回の調査の中でこれだけの実態が明らかになってきていると。よろしくお願いします。","respondent":"渋谷指導課長","answer":"もっと言えば、皆さんもご経験があるとおり、やはり体罰というものに対する世間の認識そのものが大きく変わってきているというところが大きいのではないか。","voiceIndex":40,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"多忙さではないとはっきりおっしゃったんですけれども、私は現場の先生方に、ぜひ研修の際でもいいですから、現場の中でいろいろ教育活動を頑張ってやっていただいているところでこういう数字が出てくるということについて、どういうふうに認識しているのかを、やはり教育委員会の側としては率直に聞いてあげるということをやっていただきたいと思います。よろしくお願いします。","respondent":"渋谷指導課長","answer":"そういったものを踏まえてきちんと怒りをコントロールする方法等々、また今年度新たに研修等を実施して、そういった角度からの体罰根絶を目指して、指導をしていきたいと考えているところです。","voiceIndex":42,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"今、そういう説明があったから手を挙げたんですけれども、そういう指導の中で、忙しかったからと率直に言える人がどれだけいるでしょうか。ぜひ、そういう具体的な活動を教育委員会としてしていただきたい。そのことをちょっとお願いして、終わりたいと思います。","respondent":"田村教育次長","answer":"先ほど来、指導課長とやり取りしているんですが、体罰については学校教育法の第１１条で、校長や教職員は児童・生徒および学生に対する懲戒を加えることはできると、ただし、体罰を加えることはできないと法律に明記されていますので。","voiceIndex":44,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、建設的な意味でやっていただきたいと思います。上から目線でだめだということだけでは、やはりなくならないと思います。現場の先生たちのいろいろな思いも受けとめながら指導していくことが、教育委員会の仕事だと思うんですね。そういう角度でお願いしたいというつもりで、今までも質問をしていたつもりですので、その辺はよろしくご理解をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"高橋委員","kind":"質問・要望","question":"そこで２つ質問なんですが、これは都教育委員会のほうの調査なわけですね。そのときに明らかにならずに、この１２月のときに報告したということは、まず教員のほうは、なぜしたときに、そのときに言わなかったのかということを聞かせてほしいんです。周りの先生方が見られていたとしたら、なぜ１２月になってからここで言っているのかというところについて、ちょっとお尋ねしたいのが１つ。その２点。","respondent":"渋谷指導課長","answer":"ただ、今回きちんと子ども用に、こういうものが先生の体罰なんだよ、よくない指導なんだよということを主張させたときに、あわせて何かそういった困ったことがあれば、目安箱だったり、専用電話を入れてもいいんだよということを話すようにという指導をしておりますので。","voiceIndex":47,"id":"exchange-018"},{"speaker":"高橋委員","kind":"質問・要望","question":"ありがとうございました。改めて東京都のほうにここで整理してみたというような形でよろしいですか。それならば、やはり事件があったときに、そのまますぐ対応するのが一番だと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-019"},{"speaker":"大倉委員","kind":"質問","question":"例えば配って、そういった問題があったときに、その先生が抜いてしまうということはないと思いますけれども、そういうのが可能な状況があるというのは少し思うところがあって、そういうことはないと思いますけれども、そういうのをしっかりと明確にするために、違う回収の方法を考えたりというのはあるんですか。","respondent":"渋谷指導課長","answer":"それぞれ１年生から３年生、４年生から６年生、中学校用というように、発達段階に応じて質問用紙を配って対応しております。２つに折って提出するような形になっています。","voiceIndex":50,"id":"exchange-020"},{"speaker":"大倉委員","kind":"確認","question":"再度確認なんですけれども、では例えば、欠席していたり何か事情でその調査票に記入できなかった子がいれば、改めてその用紙に書いてもらって、全ての子どもたちからの調査票がちゃんと人数分あって、それをもとにこうした報告書をつくっているということでよろしいでしょうか。","respondent":"渋谷指導課長","answer":"はい、ご指摘のとおりです。","voiceIndex":52,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"最初にちょっとよくわからないところで、細かいところなんですが教えてほしいんですけれども、体罰の有無の一覧表の中で、5)の正当防衛・正当行為というので、小学校で４人（４件）とあるんですけれども、正当防衛というのは何かイメージできなかったんですけれども、どういうことを指していらっしゃるんですか。","respondent":"渋谷指導課長","answer":"これは正当防衛と書いてあると、子どもが殴りかかってきた、身の安全を守るためというような感じに受け取られるんですが、例えば指導の中で、暴れた子の体を押さえつけたりする、そういった正当な行為がこれに当たるものです。","voiceIndex":54,"id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"実際には体罰というふうに最終的にきちんと厳正に処分されるのは３件ということで、これはもう本当にきちんと反省していただいて、以後再発しないようにということで対応していただくことになると思うんですが、残りについて、多くのものが不適切な行為というのもちょっとあることはあるんですけれども、そういう体罰ではなくて、これは学校指導の中で必要な行為だったのかということがあると思うんです。","respondent":"渋谷指導課長","answer":"例えば１２月初め、テストをしているときに、児童Ａがしゃべっていないのに注意をされたというようなのも１件と上がってきて、こんなのもあって４９件と上がってきていますので、ですから体罰だとか。","voiceIndex":56,"id":"exchange-023"},{"speaker":"塚本委員","kind":"意見","question":"今、おっしゃったところは大変によく納得できたんですけれども、あるいはもう一つ、学校のクラスの生徒があれは体罰ではないかとみんな見ていたけれども、それは指導上しっかりこれはやらなければいけない指導だったんだというような、教員と生徒間の認識のずれみたいなものがあった場合は、やはりこれはその担任教員だけでもし解決できないのであれば、いろいろな形でフォローして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-024"}]},{"id":"topic-05","title":"品川区立幼稚園・品川区立小中学校における指導要録の取扱い","agenda":"品川区立幼稚園・品川区立小中学校における指導要録の取扱い","exchanges":[{"speaker":"本多委員","kind":"質問","question":"この指導要録の２０年保存、５年保存とあるんですけれども、国の決め事なのか都道府県の決め事なのか、その位置づけと、この指導要録の項目というのがどういうものがあるのか。普通に考えるのが出欠状況とか成績とか、そういったところだと思うんですが、その項目を教えてください。","respondent":"渋谷指導課長","answer":"指導要録につきましては、学校教育法施行規則第２８条にきちんと残さなくてはならないという、国の法律的な位置づけに基づいて定められた文書です。","voiceIndex":64,"id":"exchange-025"},{"speaker":"本多委員","kind":"意見","question":"は当該校や園において現時点で収集するということなんですけれども、当該校で収集をされて、ある程度もうこの４３９名分全部可能な作業になってくるのか、これからその取組はやるということなんですけれども。本人に当時の資料、通知表等を取り寄せるとか、進め方によっては可能な限りかなりできるのかなと思うんですけれども、その辺の見込みについてお知らせください。","respondent":"渋谷指導課長","answer":"今回保存しなくてはならないものは、学籍に関する記録ですので、先ほどご説明さしあげました様式２に相当する指導に関する記録の部分については保存をする必要がないものですので、復元しなくてはならないものについては、卒業生の氏名、性別、生年月日、保護者氏名、住所等々。","voiceIndex":66,"id":"exchange-026"}]},{"id":"topic-06","title":"浅間台および上神明小学校特別支援学級（固定級）新規開設","agenda":"浅間台および上神明小学校特別支援学級（固定級）新規開設","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ちょっと１つ気になったのは、表現上の問題なのかもしれないんですけれども、Ａ４判の目的のところに、区の小中一貫特別支援教育の充実を図ると書いてあるんですけれども、これはどういうことなのか、ちょっと説明をしていただきたいと思っているんですが、どこの学校でも品川区内は小中学校連携で小中一貫教育というのをやっているので、そういうことで特別支援の子どもたちにも。","respondent":"村尾学校支援担当課長","answer":"特に今度固定級が２つ増えることによって充実、個に応じた指導もより適切にできるのではないかと考えております。","voiceIndex":73,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"おっしゃることはわかりました。しかし、知的障害のクラス、通級学級ですね。率直に誤解を恐れない表現をしてしまうと、なかなかちょっと難しいんじゃないかなと。難しいと、誤解を恐れずに言う表現なんですけれども、どういうふうに捉えたらいいのかというのがちょっとわからなくて聞いているんですけれども、質問したいことわかりますか。","respondent":"村尾学校支援担当課長","answer":"２点目、先ほどご指摘いただいた小・中の連携ということについての効果度なんですが、これはやはり小学校で特別支援学級で担任がいろいろな指導したことを、当然今度は中学校にもし上がったときに、中学校でもこの子は、今こういう課題があって、ここまでの学習をしている。","voiceIndex":75,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"私もこの資料を読んだときに、あまりここのところはよくわからなかったので、現場の先生にちょっと伺ったときに、教師の方としては、ご担当にかかわらず、こういう教育委員会の方針が存在したということについては知らなかったとその方はおっしゃっていました。その方の話ですから、何か今、非常にあれなんですけれども。そのことも含めて教えていただきたいと思います。","respondent":"田村教育次長","answer":"この方針は今回改訂した基本方針にも盛り込んでありますので、これはもう私のほうでも校長会で、新しく改訂したものも旧も説明し、それで各学校は責任を持って教職員に伝えるようにということなので、今回、目的の中の記載は取り立てて新しいことを記載したのではなく。","voiceIndex":77,"id":"exchange-029"},{"speaker":"南委員","kind":"意見","question":"しかし、一人一人の獲得目標というのは、やはり発達の状況が違うだけに、それぞれ違うのは当然のことだと思うんですけれども、そういうところをやはり十分配慮の上、もちろん目標を定めていると思うし、指導もしていただいていると思うんですけれども、この一貫とか連携というところをあまりに強調していくというのではなくて、個々の状況に合わせたやり方というのを実践していただくということが大事だし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-030"}]},{"id":"topic-07","title":"御殿山小学校西側敷地の活用","agenda":"御殿山小学校西側敷地の活用","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"もう一度確認したかったので、聞きそびれたところがあったので教えていただきたいと思います。その後に説明されたことがあまりよく聞き取れなかったので、確認をしたいと思うので、もう一度、申し訳ないんですけれども説明していただきたいというのが１点です。そのこともちょっと表明しておきながら、さっきの質問を伺いたいと思います。","respondent":"中元品川図書館長","answer":"その部分につきまして、ものづくり経営支援課で主催しておりました事業を、この産業支援交流施設のほうに移されるという計画がありますので、その部分で、大崎図書館でやっております図書サービスとの連携も考えたところでの案が出てきたのかというところで。","voiceIndex":85,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"その理由としては、ですから全部の移転ではなくて対応していただきたいということを再三行財政改革特別委員会でも申し上げてきたし、大崎図書館のことなのでたまたまここでも報告があったので、そのことははっきりと意見として述べたいと思っているんですけれども、なぜ大崎図書館をごっそり移転させるということに反対かというと、大崎図書館というのは、いろいろな資料を見てみると。","respondent":"中元品川図書館長","answer":"例えば取次施設であるとか、そういったものも必要かと考えているというご答弁をさしあげているところです。委員がおっしゃるように２つつくるという選択肢は、現状の区の施設展開の中ではなかなか厳しいものがあるのかなと考えています。","voiceIndex":87,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、もっと熟慮していただいて、こういう選択が一番いいと私は思えません。それはどうなんでしょうか。地域の方々への理解を求める説明というのはされる予定があるんですか、ないんですか。","respondent":"中元品川図書館長","answer":"地域の方への説明ですけれども、今後の検討の中で考えていきたいと考えています。今のところ予定はございません。","voiceIndex":89,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"私はぜひ地域住民の声を聞いて、区として選択したことが正しかったのか、あるいは不十分なところがあって改める必要があるのかということをしっかり見極める上で、また効率的な行財政運営をする上で、やはり地域の方々の要求がどこにあるのか、どんなご意見を持っているのかということをしっかりつかんで選択するべきだと思っています。したがって、説明会はやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-034"},{"speaker":"大倉委員","kind":"質問・要望","question":"もしかしたら同じ質問になってしまうかもしれないんですけれども、以前図書館長のお話の中で、移転というのはないというような答弁が以前あったかと思うんですが、この移転自体は否定するものではないんですが、その移転に変わった検討の経緯というのを教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"地域への説明については今後企画部のほうとも調整しながら、図書館だけの問題でもないと思ってありますので、どういう取扱いになるか、区で考えていきたいと思います。","voiceIndex":92,"id":"exchange-035"},{"speaker":"大倉委員","kind":"質問・要望","question":"というと、行財政改革特別委員会のほうで話が来て、移転になったということだということなので、図書館の管轄部門として館長がいらっしゃって、どっちが先ということはないですけれども、うまくそういったことがないような連携をとっていただきたいというのと、いろいろな検討をして、説明はぜひしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-036"}]},{"id":"topic-08","title":"東京都ひきこもりサポートネットによる訪問相談申込み窓口開設","agenda":"東京都ひきこもりサポートネットによる訪問相談申込み窓口開設","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"３つの条件を満たす本人・家族ということなんですけれども、あまり体験がないことなのでちょっとよくわからないんですけれども、自分の子どもが６カ月以上なかなか外に出られずに、自分の部屋に、家の中に閉じこもっているという状況というのは、家族にとってはかなりつらい事態だろうと思うんですけれども、したがって６カ月以上ですから。","respondent":"福島青少年育成課長","answer":"確かに６カ月ひきこもりというのはかなり重度なので、できたらもっと早目に対応したほうがいいということは明らかだと思いますので、その辺は受け付ける段階では柔軟に対応していきたいと考えています。","voiceIndex":100,"id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"じゃあ、その際、相談の受付電話番号のご案内を知りたいと思ったので、広報を見て知ろ、わかれ、そういう感じなんですけれども、教えていただきたいと思います。","respondent":"福島青少年育成課長","answer":"代表電話にかけていただいて、青少年育成課を呼び出していただいても結構ですし、広報のほうでは、今ある電話、青少年育成係の電話番号をお知らせする予定です。〔「直通ではなくて」と呼ぶ者あり〕直通も載せます。ただ、これが専用ダイヤルということではありません。","voiceIndex":102,"id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"これは東京都の事業で、区が窓口を行うということで、最初に区の代表番号に電話をされた方を受付けて、つなぐということですけれども、その後のフォローについて、区としてはどのような捉え方をされていらっしゃるんですか。ある程度連携をとって、東京都ひきこもりサポートネットから状況等の連携みたいなものはされるんでしょうか。","respondent":"福島青少年育成課長","answer":"その後につきましても、引き継いだまま終わりということではなくて、どういう状況になっているのか、また訪問相談をして、それから先に東京都が抱えています施設ですとか、そういうところを紹介したりだとか、そういうことをやりますので、最終的にどうなったのかということは。","voiceIndex":104,"id":"exchange-039"}]},{"id":"topic-09","title":"平成２６年４月の入園状況","agenda":"平成２６年４月の入園状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それと、単純に計算したときに１,１３１人が入れなかったと思っていたんですけれども、その方々が３月３１日までに何らかの形で、私も品川区の担当のところにちょっとお願いをしたい、どういうふうにしたらいいでしょうかというご相談をさせていただきながら対応していただいた、その結果が７７２人と理解していいのかどうかをちょっと確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"最後に、最初にいただきましたご質問は、申込者の割合でよろしいでしょうか。〔「入園率」と呼ぶ者あり〕内定者率ですね。内定者率は、子どもの児童数が、今、乳幼児人口が１万８,３５９人が４月１日ですので、在園児率は３５.９７％になっております。","voiceIndex":112,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"入園できた１,７０６人は、申請者の数の何％かというのをちょっと知りたかったので、それを質問したところですので、後でいいので、すみません。それともう一つ、待機児の１２８人のうち、今、知人だとか預け先のことを教えていただいたんですけれども、もう一つ伺いたかったのは、正規社員の方、あるいはパートとか非正規の方、そういう分類をしているのがあれば、教えていただきたい。","respondent":"今井制度改革・待機児童対策担当課長、竹田保育課長","answer":"１２８人の方の就労の形態です。こちらは例年母親の就労の形態でお話しさせていただいていると思いますけれども、１２８人のうち、常勤の方が５９人、パートの方が２８人という形で確認しております。入園申込みに対する入園決定した者の率というお話ですが、６８.７％になっております。","voiceIndex":114,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"ありがとうございました。それで、今年度の申請で、地域的に大井地域、品川地域等々幾つかあると思うんですけれども、その地域で分類してみたときに、一番厳しかった地域というのは１カ所なのか。あるいは１カ所というのも面的に大きいと思いますけれども、そのあたりのことをちょっと教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今、品川区では待機児童が２倍になったことからもわかりますように、全地域で待機児童のほうは、八潮地域以外いらっしゃる状況です。その中でも、やはり荏原地域のほうが待機の人数が半分程度を占めている状況になっておりますので、お答えとしましては荏原地域です。","voiceIndex":117,"id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"一緒に聞けばよかったのかもしれないけれども、この間もそう聞いたら荏原地域とおっしゃっていたようなことを思い出したんですけれども、大崎地域はどんな感じだったのかちょっと知りたいと思っているので、ここ数年の状況、今年度については荏原地域が待機児、これは不承諾の人数の半分という意味なんですか。その辺をはっきりさせておきたいと思っているんですけれども、改めてそこを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"地域的な割合ですけれども、今お答えしておりますのが地区別の待機児童数の割合の中で、今、半分程度が荏原地域です。半分まではいきませんけれども、品川、大崎、大井、荏原、八潮と分けますと、荏原地域がいつもこの筆頭で、４割程度の待機児童数の数を占めているところです。","voiceIndex":119,"id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"そういう点で、私たちはこの間ずっと株式会社に参入を呼びかけてきている中で、４園は開園していただいたけれども、結果的に待機児が出る、入園できなかった数が今までになくぐっと増えていきているという現実を見たときに、やはり区が短期間で、とりわけ乳幼児、３歳以下の子どもさんに対応するには、やはり今ある施設でもいいからリニューアルして。","respondent":"竹田保育課長","answer":"定数のご質問ですが、保育の定数の弾力化、それから既存施設の有効活用、それから民間活力の有効活用など、さまざまな施策をミックスしながら、今、この事態に対応しておりますので、今後もこの方向性で進めていきたいと考えております。","voiceIndex":121,"id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"そういう方向でぜひ進めていただきたいんですが、私は今一番質問したいのは、区の見解を聞きたいのは、今この時点というか、４月に入れなかった状況の中で、毎月申請をして、申請した方については入園を促すようにしているわけですけれども、絶対量が足りないので、やはり増設させていくという緊急の対応をする必要があるのではないかと思っているんですけれども、そういう認識はあるのか、ないのか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"６月の開設のほうは検討しておりますが、これも含めまして、今年度中改めてさらに開設することが、保育ママを含めまして、一番そういう意味では臨機応変に開設できる部分で、委員ご指摘の乳児に対応できる部分ですので、これはちょっと前向きに検討していきたいと考えております。","voiceIndex":123,"id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"６月に保育ママを開設予定というのは、それは受けとめていきたいと思っています。しかし、待機児童の４割が荏原地域だという具体的なその数字があれですけれども、１２８人のうちの４割というと七、八十人という感じなんですか。違う、５０人ぐらいですか。保育ママが６月にオープンするにしても、５０人を吸収できるぐらい保育ママをつくるんですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今回、６月の開設につきましては、９人が２カ所と、それから１５人という形で、定員３３名という形ですので、引き続き今後も開設については前向きに検討してまいります。","voiceIndex":125,"id":"exchange-046"},{"speaker":"南委員","kind":"確認","question":"保育ママの保育期間は１年ですよね。違いましたか。ちょっとその辺、私は１年だとずっと思っていたので、０歳で預かったら、１歳になってからはどこかのところに預ける先を探さなくてはいけないわけですよね。その辺についてはどういうふうに親の不安を解消する立場に立っているのかというところは、改めて確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"委員ご指摘のとおり、１年という形で契約はしておりますけれども、入ってから２歳で満期になるまで、それぞれの園でお預かりいただけるように事業者のほうも努めておりますし、私どもも保育ママから退所したところに空き枠という形で毎回広報していますので。","voiceIndex":127,"id":"exchange-047"},{"speaker":"南委員","kind":"意見","question":"そうすると、９人の受け入れ枠を２カ所と。１カ所で考えればいいと思うのだけれども、９人を全部０歳で入れたとしたら、その次の年は１歳になった場合に、中にはどこかに転園をするかもしれない。そうすると、その空きの部分しか今度の０歳は入れられないわけですね。その９人というのは年齢ごとの定員と考えていいのか、３年間で９人ではないということですよね。ちょっとこの辺を整理してください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"委員ご案内のとおり、保育ママの方は、認可保育園あるいは認証保育所も含めて併願といいますか、一緒に申し込まれて、品川区の第６希望、認証保育所以外ですけれども、第６希望の中で保育ママと認可保育園をそれぞれ希望されている方がいますので。","voiceIndex":129,"id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、これ以上言ったら繰り返しになりますので、もうこれで終わりにしたいと思っていますけれども、やはりこの現状を見て、待機児童数も今まで２桁だったのに、３桁にいよいよ突入してしまったという事態をやはり重く受けとめてほしいし、それから、この間不服審査請求、異議申立てを行った６人のうちの１人は毎日上司から電話がかかってきて、４月の復帰は大丈夫なんだろうなと念を押されていたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-049"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋委員","kind":"意見","question":"１つお尋ねしたいんですけれども、今、小学校・中学校の家庭訪問の時期なんですけれども、先生方やあるいはご家庭の協力を得ながら実施されていると思うんですが、時間的にどうしても家庭訪問できないという場合には、どのように対応しているかということです。訪問できない場合。２点です。","respondent":"渋谷指導課長","answer":"校外対策費等々で、時間外にどうしてもという場合については、出たものについてはそういったもので補償するような形の対応をさせていただいているところです。","voiceIndex":139,"id":"exchange-050"},{"speaker":"高橋委員","kind":"質問","question":"小学校や中学校でその対応がずれると、例えば勤務時間内でないと困るんだというような状況の学校があったり、逆に、いや、８時でも９時でも行きますよというような学校があったり、そういう形でずれていくと、今はちょっと校外対策費の話だったんですけれども、そうではなくて、その時間に実施するかどうかというところの共通認識というか、その辺はどんな形で小・中学校のほうに徹底されているんでしょうか。","respondent":"渋谷指導課長","answer":"実際に三者面談等々といっても、担任のほうがつくった枠外で、仕事の関係でなかなか休めないのでというようなご希望をしてくる保護者が多くなってきたというのが実態としてありますので、もう学校のほうで勤務時間の中で必ずということになると。","voiceIndex":141,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4822#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":47851,"voices":145}},{"id":"h26-20140512-5","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"総務委員会","time":"午後１時００分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２６年度区政モニターの委嘱","agenda":"平成２６年度区政モニターの委嘱","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この区政モニターの状況がよくわからないので教えていただきたいのですが、区政モニターの５０名の公募に対して、７２名の応募ということなんですけれども、これはどういう形で公募をするのか、５０名に対して７２名は何となく少ないような感じがするのですけれども、７２名という数に対しては、区としてはどういうふうに考えられているのかということと、あとは先ほど、任期は２年で。","respondent":"荒井広報広聴課長","answer":"任期２年ですが、こちらのほうで平成２４年、平成２５年となさいまして、平成２６年、平成２７年も引き続きとおっしゃっている方が１８名です。３分の１程度と考えていいかなと思っているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ありがとうございました。そういう中身も、多分区政モニターについてのそういうご報告というのは、１年間やってきて今日が初めてという思いがあるのですけれども、そういうところでは、その中身についても、今の集会の中身とか何かもあわせてご報告いただけたらなということで、要望させていただきたいと思います。","respondent":"荒井広報広聴課長","answer":"応募された方からどのような形で委嘱をしていくかですが、先ほどご説明させていただきました地域別、年代・男女別を主に軸といたしまして、それぞれ、まず地域別で品川、大崎、大井、荏原、八潮の中から大体構成比に合うような割合で選ばせていただきまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"今回、男女別、裏のページの年代別ということがありますが、本来、区政に対する区民のご意見などをモニター化して聞くならば、この２０代、３０代が大分少ない。逆に６０代、７０代の方が多いと。今回このアンケート調査に対してそういうふうに思うのですが、いかがでしょうか。その辺のお考えをお聞かせください。","respondent":"荒井広報広聴課長","answer":"それからもう一つの、２期まで延長についての考え方なんですけれども、もともと１期というところもあったのですが、少し深めたいとおっしゃる方の声も多かったものですから、１期でおりるには、まだ自分が十分に地域に持って帰り切れないというお声もいただいたところですので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"それと、この人数なんですが、絞って委嘱数、計５０という根拠というのは、もともと何かで来たのだと思うのですが、人口が今３６万人いて、５０でさらにこういう年代別で分けると、本当に特殊なピンポイントでアンケートをとるような格好に感じるのですけれども、この５０という数字の根拠は何なんですかね。そこら辺、すみません、もしお聞かせ願えればと思います。","respondent":"荒井広報広聴課長","answer":"そういったときの運営のことを考えますと、５０人くらいが、そういう意味では最大限かなと考えているところです。それが１つの根拠となって進めているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ、一生懸命モニターの調査をされているのはわかるのですが、１歩でも２歩でも幅広く、もしいただけるようなシステムをつくれればありがたいと思います。要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"今回、区政モニターのところですけれども、２年ほど前に、私ではないのですが、一般質問されているところがあって、その中で話としては出ていますけれども、「若年層の積極的な参加により、できる限りバランスのとれた年齢構成を実現していく」という企画部長の答弁があるのですけれども、そのために、「土日や平日夜間にモニター集会を開催するなど。","respondent":"荒井広報広聴課長","answer":"平成２６年、平成２７年につきましても、日曜日の開催を１回、平成２７年は未定ですけれども、ウイークデーの昼間以外の開催を予定しています。それから、もう一点の男女別・年代別の構成比ですが、別に作為があったわけではなくて、怠慢だったと思います。","voiceIndex":14,"id":"exchange-006"},{"speaker":"浅野委員","kind":"意見","question":"ちょっと言い過ぎたかもしれないのですけれども、ぜひともそういうところにも気を配っていただければと思います。それで、ホームページを見ますと、区政モニターを引くと、更新日が２０１２年１月１０日になっているんですね。ホームページの件だけは、ぜひとも更新を、新しくしていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。それは協力委員という位置づけがあるから。区政モニターになっていて、いろいろ議論して、何か思いをこういうときに直接区長と、年に１回か２年に１回か、委嘱中に１回でもいいのだけれども、そういう場面をつくってほしいと言われたのだけれども、これについてはどういうふうに私は思えばいいのか、どういうふうに位置づけていらっしゃるのか教えてください。","respondent":"荒井広報広聴課長","answer":"委嘱式のときには区長が講義をいたしまして、その後、自己紹介をしていただきながら懇談する機会、それから最後の離任式のときも区長が話をさせていただいて懇談する機会というのが、年に最初と最後の１回ずつ設けているところです。今後、工夫していきたいと考えています。","voiceIndex":17,"id":"exchange-008"},{"speaker":"つる副委員長","kind":"質問","question":"なので、今までやってきた工夫ですとか、これまでのことをもうちょっと具体的にお聞きしたいのと、あとは、このモニターだけではなくて、２０代の声、また学生層の声という部分、またそれをどういうふうに反映していくかということにもつながると思うのですけれども、この辺の取り組みについて、ほかに何か具体的にやっていることがあれば、それを教えてください。","respondent":"荒井広報広聴課長","answer":"２０代の声、あるいは学生層の声をどのような形でということですが、２年前になりますが、タウンミーティングの小規模の形での実施というのを行いました。このときが青年層に限っての、青年層にお呼びかけをしてタウンミーティングを実施したということがあります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"つる副委員長","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"}]},{"id":"topic-02","title":"品川区電子メール配信システムの充実","agenda":"品川区電子メール配信システムの充実","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"今でもメールマガジンという形で配信されていますけれども、今回追加された部分が別途登録が必要ということですが、これは何か制約、むしろ約款でありますとか、そういう基本的な考え方というのがあって、別途登録をされるのか、私も入っているのですけれども、別途登録というとなかなか面倒と言ったら怒られますが、そういうふうに感じられる方もおられるのかなと思うので、もし制約等がなければ。","respondent":"荒井広報広聴課長","answer":"大変お手数なところもあるのですけれども、ご自分の必要とされる情報が何なのかということを選んでいただいた上で、緊急情報あるいは防災気象情報等の配信をさせていただきたいと考えているところです。","voiceIndex":27,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういう方も多分おられるというのは、いずれにしろ承知の上なのですけれども、緊急情報、防災情報にしても、その他の気象情報にしても、かなり要望というのでしょうか、そういうのを希望される方は多いと思います。減らす方向ではなくして、増やす方向で考えていただけないかなということですが、いかがでしょう。","respondent":"荒井広報広聴課長","answer":"ご意見として承らせていただきますが、一気に流してしまうというのは、ほしくない情報まで来てしまうというところが大変懸念されるところですので、お手数をおかけいたしますけれども、ご自分の必要な情報は何なのかということを選んでいただくのが。","voiceIndex":29,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":15999,"voices":40}},{"id":"h26-20140513-14","meetingId":"h26-cm05","date":"2014年5月13日","dateIso":"2014-05-13","committee":"行財政改革特別委員会","time":"午後１時００分～午後２時２８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"御殿山小学校西側敷地の活用","agenda":"御殿山小学校西側敷地の活用","exchanges":[{"speaker":"南委員","kind":"提案","question":"品川区がもともと持っている土地に無償の土地を提供されて計画をするということは、本当に強い要望のあるところだったので、遅すぎるぐらいでありますけれども、計画を持っていただいたことはしっかりと受けとめていきたいと思っているんですが、どうせというか、つくるのであれば、もう少し空きスペースはあるわけですから、応募をする事業者にほかのものも発案してほしいという。","respondent":"柏原行財政改革担当課長","answer":"８０床と２０床という割合で確定ということではなくて、そこも含めて事業者側の提案を受けたいと考えています。逆の言い方で申しますと、自由提案のところで老健施設だけと言ってくる事業者ももしかしたらあるのかもしれません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"提案","question":"私はそう思っているんですけれども、その辺の認識をもう１回聞かないと、私としてはあれかなと思うので、もう一度、特養と保育園、この２つに限って聞きますけれども、住民のニーズがどういう状況になっているかという区の認識を伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"特養と保育園です。区の全体のことで申し上げますけれども、確かにその特養の部分であるとか、それから保育園、待機児童の関係であるとか、そういった課題があるといったところは認識しています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり課題があると認識しているというところは私もしっかり受けとめていきたいと思っていますが、しかし、これだけの土地ができて、余剰のスペースも５,０００m2までこの間のあれではいかない、少なくとも３,０００m2か４,０００m2くらいのスペースは確保できるということなので、そうであるならば、やっぱり重く受けとめて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"あべ委員","kind":"提案","question":"でも、これについてはお答えを求めている時間もないので、不思議な気がしているということだけ言わせていただきます。だから、それはぜひ１００床を越えての提案もスムーズにできるような形を工夫していただきたいと思いますし、それから自由な提案でということでありましたけれども、そこにはやはり区の土地につくる建物であるということから、一定の方向性はぜひ出していただきたいなと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、図書館があったということがありますので、文化教育的な部分で何かできないかという検討はしていますけれども、申しわけないんですが、今何か具体的に、セットのというお話もありましたけれども、何かお話しできる状況ではないです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"ありがとうございました。書きぶり、説明ぶりにも期待していきたいと思うんですけれども、やはり地域に愛される施設にしていただきたいなと思います。ほかのご質問もあるでしょうから、私からは以上で失礼します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１点だけ。ただ、私もそのとき話をしたんですけれども、ほかの建物の中で地域貢献の施設等という話が出ておりますので、果たしてこれは基本的に老健と図書館という考え方で出ると思いますという話をしてあるんですけれども、そういう要望に応えるためには地域貢献の中での部屋が多分出てくると聞いているんですが、そこら辺の活用方法をどう考えているか、その点だけ１点教えてください。","respondent":"柏原行財政改革担当課長","answer":"今委員おっしゃっていただいたとおり、この施設そのものにそれができるかどうかは若干面積の関係とかありますので、このうちの開発のところで地域貢献の部屋も想定されておりますので、そういったところも例えば使えるかとか、それから運用関係とも調整しながら。","voiceIndex":14,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、せっかくすばらしい施設をつくってくる中で、地域の方から、後でそういう問題が残らないようによく考えておいていただきたいというお願いをして、これは要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"提案","question":"先ほどの自由提案のところなんですが、なし崩しに自由というわけでは当然ない中で、主な規制ですとか、これは近隣の状況から好ましくないとか、そういったものが現時点であれば教えていただきたいのが１つです。もう１点は図書館のところです。こうやって手を入れるチャンスですから、敷地、床面積のところなんかではまずその点からも、同規模というよりは拡充の要素があっていいのではないかと。","respondent":"柏原行財政改革担当課長、桑村企画部長","answer":"先ほどのお話で単純な面積のお話だけをさせていただきましたが、我々としても介護老人保健施設の建物と一緒になることや、隣はすぐ学校ですし、それから。それからもう１つ、規制のほうの話ですけれども、１つは学校がありますので、いわゆる文教地区という意味で規制はかかりますので、一定のできない職種あるいは建物はありませんけれども、今、私どもの課長が答えたのは。","voiceIndex":17,"id":"exchange-008"},{"speaker":"井上副委員長","kind":"意見","question":"すいません、図書館の件についてなんですけれども、今、移る側の声は聞いているようですけれども、新規のほう。現在の大崎図書館の利用者と近隣の住民の方たちの反応についてお聞かせください。","respondent":"柏原行財政改革担当課長","answer":"今後、どういった形で周知等々についてはやっていくかというところも含めて、検討していきたいと思ってあります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"井上副委員長","kind":"質問・要望","question":"それはお伝えしたいと思います。そこで、それを既成事実と思うつもりはありませんけれども、そういった方針を持つ中で、変えてきたというところの説明責任を果たしていかないといけないと思うので、そこについて、庁舎の中で、プロジェクトの議論と、また全体の議論をどうされてきたのか、説明をしていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"その進んでいく状況の中で、御殿山小学校の西側の敷地について一定程度の土地であるとか、それから活用について、使えそうだということで、主に企画部門で検討を進めてきたところではありますけれども、これは１月当初の報告にも重なるんですけれども、文教地域であり。","voiceIndex":22,"id":"exchange-010"},{"speaker":"井上副委員長","kind":"質問・要望","question":"プロジェクトについてもどういう内容だったのかというのは、資料はまた改めて違う部分で請求をさせていただきたいと思いますけれども、何も住民の方たちの声が反映されないまま、ここで、これはまだ案ですので、条件としてこの案を盛り込むということについては反対だということだけ、申しわけない、時間がないので、お伝えをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"進め方なんですけれども、質問するつもりはない、本当は質問したいんだけれども、だけど今日は相手のあることなので改めたいと思うんですけれども、でもこのメンバーでの委員会は今日が最後じゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-012"},{"speaker":"山元委員長","kind":"質問・要望","question":"だって、じゃないと、それで賛成だけど理事者はだめですみたいな話になったら」と呼ぶ者あり〕賛成って、ごめんなさい、このまま、おっしゃるとおりです、いろいろな、当初は終わるのが２時半ごろということでありましたので、さまざまご都合等々あるかと思いますので、急遽、今、南委員からもう一度というお話があったものですから、皆様としては継続されて、時間、このまま討議に入っても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-013"},{"speaker":"須藤委員","kind":"意見","question":"これもまだ案もきちんと決まってきていないので、今どうのこうのというのはなかなか難しいところなんで、６月からまた進行状態あると思うので、もちろんそれはいろいろな思いがあるかもしれないけれども、改めて質疑があるなら、今、短い間に、さっきから聞いていれば、だったら長い質疑なんてまとめてぽんとＡだ、Ｂだということをやれば、３０分、４０分もかかっているんだから、そうできたと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-014"},{"speaker":"南委員","kind":"提案","question":"ごめんなさいぐらい言いなさい。私がそういう提案をさせていただいたのは、先ほどの発言の中にも、４５分という時間しかとっていなくて非常に短いと。私ももっと聞きたいけれども、皆さんの発言を聞いていてさらに深めたいというところもあったので、ぜひそういう計らいをしていただきたいとお願いしたんですけれども、ほかの委員もいろいろそういう思いがあると思うんです。ぜひ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"１人ずつお願いしていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"私は予定どおりに進んでいただいて。ですから、ここで公募の関係もまだはっきりわかって、具体的なことが出ていないのに、これ以上のことを話し合っても私は意味がないと解釈しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5966#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":17567,"voices":50}},{"id":"h26-20140515-17","meetingId":"h26-cm05","date":"2014年5月15日","dateIso":"2014-05-15","committee":"震災対策特別委員会","time":"午後１時００分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6452#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":1927,"voices":8}},{"id":"h26-20140609-6","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"区民委員会","time":"午後１時００分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"この事務事業概要の本といいますか、冊子についてお伺いしたいんですけれども、今回こういう形の印刷物で出てきましたけれども、前回か前々回ぐらいのときはちゃんとした本みたいな形で出てきたと思うんですけれども、これは年度によって変えていくというのはあるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"もう一点お伺いしたいんですけれども、細かいことではなくして、文化スポーツ振興課のところで、課長が半年ぐらいオリンピック・パラリンピック担当をやられていたと思うんですけれども、改めてオリンピック・パラリンピック担当もつくって担当課長も置いたわけですけれども、改めましてその辺の区の考え方等についてお伺いしたいんですけれども。","respondent":"小川オリンピック・パラリンピック推進担当課長、中川原地域振興事業部長","answer":"それで周知活動を実施していたんですけれども、本年、また改めて４月１日付でオリンピック・パラリンピック担当という係を置いて、品川区としては万全の体制の組織体制にしたです。体制はそういうことでありまして、そもそもなんですけれども、昨年、先ほど私のほうからご説明しました長期基本計画の改訂の中で、仕上げの段になりまして、オリンピック・パラリンピックを２０２０年に控えたということも。","voiceIndex":42,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一番初めの組織図のところなんですが、地域振興事業部、新たに地域相談担当ですとか、オリンピック・パラリンピック担当、個人番号カード担当ですか、ここ３カ所でしたか、新たに設けられたということですけれども、それぞれのところでは、体制としては正規職員、非常勤、嘱託全部合わせて３４０名ということなんですけれども、新たにそういうところの担当も設けて行うという改正の充実が。","respondent":"久保田地域活動課長","answer":"ただ、この係長１人で全てのことをやることはできませんので、当然地域支援係との連携、また地域センター、あとは地域活動課内との連携も図りながら、そうした課題に対応していきたいと思ってあります。","voiceIndex":45,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"体制のところは、そうしますと、去年からはそういうふうに新たな部署が設けられたということなんですけれども、職員の人数そのものの体制というところでは、増えているのか、変わらないのか、その体制についてもお聞かせいただきたいと思います。","respondent":"中川原地域振興事業部長","answer":"組織を組むにあたっては、今言いましたように課題が出てきます。そして検討していくんですが、組織改正でこういった形で、係なんですけれども、係として明示するという意味は、区民の方にとって、区がこういう課題に積極的に取り組みますという１つのメッセージになります。","voiceIndex":49,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこら辺は本当によかったと思っているところです。これについては今回あっさりした説明だったんですが、来年の１０月からの実施に向けて準備をしていくというところなんです。これをどういうふうに進めていくのか、どう考えられるのか。今日は事務事業概要ということなので、これだけのものですけれども、そこのところはこの委員会でご説明いただけるということになるのでしょうか。","respondent":"井浦戸籍住民課長","answer":"このカード交付につきましては来年の１０月から具体的に日程が組まれてありますので、適切な時期に適切な形で、区民委員会に報告したいと考えています。","voiceIndex":51,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは本当にさまざまな問題が想定されるものですので、ぜひこのところにしっかりとご説明いただきたいということは要望させていただいて、とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"当初予算一覧のところなんですけれども、予算書との関係で、歳入とかどういうものを拾って、ここに入れてあるのか。歳出だと事業費だと思うんですけれども、この一覧がどういうところなのか、ご説明をいただきたいと思います。","respondent":"久保田地域活動課長","answer":"これは予算書の中から引っ張ってきますが、歳入の主なもので言えば、例えば集会所の使用料が入ったり、あとは総務費の中の手数料が入ってきたり、それぞれの所管の中で歳入として調定しているものを、この中では歳入という形で入れているものです。","voiceIndex":54,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"歳入は使用料とか負担経費とか、そういうところで実際に得た収入ということで、あとは歳出のほうは、事業に合わせてというもので拾ってきてあるということで理解をすればいいのでしょうか。","respondent":"久保田地域活動課長","answer":"予算書のほうは款別のほうで作成していますけれども、こちらのほうはその事業部、課別でやっておりますので、書き方としてはそういう書き方で、私どもの事業部で主に言えば、その使用料とか手数料とか負担金等の歳入がありますから、それらを収入として載せているというものです。","voiceIndex":56,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ。それともう一つ、細かくてすみませんけれども、町会会館の補助金というのが５０％で、最大で２,０００万円までということで先ほどご説明があったんですけれども、町会の数は今２０４ということでいいのでしょうか。そこの２０４町会のうち、町会会館があるのは幾つぐらいなのかを教えていただけますでしょうか。","respondent":"あべ委員長、久保田地域活動課長","answer":"その前に、本日の議題は事務事業概要の説明ということですので、個別の事業については、また別途ご議論いただければと思いますが、簡潔にご答弁をお願いします。実際に実態調査ですけれども、地域のほうの説明も一緒に行って、町会・自治会の方々にご協力をお願いして、もう実際に動いているです。しかるべき時期に報告等があろうかと思います。","voiceIndex":59,"id":"exchange-009"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"結局、昨年の場合は、マイナス１５％を目標にということなんですけれども、昨年はどのくらいのマイナスになったかということは、行政の中ではおわかりでしょうか。","respondent":"久保田地域活動課長","answer":"昨年の節電目標は１５％ということで掲げましたけれども、最終的には目標は達成できずに、１２.６％の節減だったです。","voiceIndex":67,"id":"exchange-010"},{"speaker":"井上委員","kind":"意見","question":"商店街のところで、先ほど事務事業の説明をしていただいたところで、やはり平成１０年ぐらい、もう既に同じ事業が１０年以上たっているというところで、そこら辺で、やはり事業の組み立てとか、そういったところの施策についての評価というものは、委員会としてもすべき項目ではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は区民委員会はひさしぶりなのですけれども、今日、事務事業概要を詳しくいろいろと説明していただきましたので、今日ご説明をいただいた中身をもとにしながら、ちょっと時間をいただいて検討させていただいて、出させていただきたい。ちょっと時間的な余裕をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"都市型観光と、あと中小企業、商店街の支援というのは、特に今日、部長からも一番最初にお話があったんですけれども、この委員会は一番区民に身近というようなお話が出ていましたけれども、そういう意味において、今、井上委員からも出ましたけれども、やはり町会の支援についてのあり方というのは、いろいろ各委員から出てくると思うんですが、私はそこは入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回は区長選もあるということでの日程ということなんですが、初めに行政視察ありきで日程から決めるということよりも、本当に必要かどうかというところをもっと検討して、私はそんなに２泊３日で遠いところにこだわることはないと思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-014"},{"speaker":"本多委員","kind":"意見","question":"そのあり方については、所管事務調査を充実するべきだと思いますので、所管事務調査を固めた後に、その視察をあわせて考えていけばいいと思います。仮に遠いところになれば２泊とかになる場合は、希望としては９月８日の週がありがたいです。別にこだわりませんが、希望だけちょっと言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"私も今まで１５年議員をやっていますけれども、必ず２泊３日で行っていたわけですね。けれども、この２３区の中とかでもありますよね。最後にこれだけは言いたいんですけれども、行政視察は、私はものすごくためになって、中止しろとかそういうことを言っているのではありませんので、ただ、場所はということで、２人の意見を伺って納得したという思いで、改めて言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-016"},{"speaker":"あべ委員長","kind":"質問・要望","question":"ほかに何かご意見ありますか。そういった意味で、まずは時期を決めさせていただきたいと思っているわけです。この考え方はご理解いただけますでしょうか。２泊３日が目的ではないと私自身も思っております。ただ、増やすとなると、これはちょっと予算の問題もありますので、例えば１週間がいいとか言われても、それはちょっとご希望には沿いかねるかなと、常識的なところでご理解いただけるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"先ほど、本多委員のほうからもありましたように、やはり所管事務調査について議論をして、それからそれを深めるという形になっていくのがいいのかなという思いがあるので、ちょっと今どこにというのは、次回にちょうどそこを議論するということなので、そこのところで議論をするか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、そういうふうになったらしようがないというか、無理して行くこともないと思いますし、やはりここにどうしても委員会としてはこれを深めるために委員の行政視察が必要だというところで初めて行政視察というのがあると思いますので、今のところでどこに行くかということになったら、やはり本当に行政視察が先にありきみたいな形になるので、そういうことではない視察にしましょうということですから。","respondent":"あべ委員長","answer":"いろいろな考え方があると思います。要は、先ほど藤原委員のほうから、行くこと自体は非常に有意義だということもありました。ですので、日程の関係で行けなくなるというのもこれまた残念なことではあります。","voiceIndex":88,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"所管事務調査を決めて、それに照らし合わせて場所とかを決めましょうと言ってくださって、委員長自身も正論ですと言ってくださったんですから、本多委員もそういう意味で言ったのではないと、今、打ち消すなら別ですけれども、せっかく言ってくださったんですから、一番大会派の自民党の委員がおっしゃってくれたのだから、それに照らし合わせてやればいいじゃないですかと私は思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2696#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":43278,"voices":93}}]);
